class AssetManager {
  static getIndexHtml() { return EMBEDDED_ASSETS.indexHtml; }
  static getAppCss() { return EMBEDDED_ASSETS.appCss; }
  static getAppJs() { return EMBEDDED_ASSETS.appJs; }
  static getBackgroundImage(id) {
    const num = String(id).replace(/[^0-9]/g, '') || '1';
    const filename = 'bg' + num + '.jpg';
    const candidates = [
      path.join(process.cwd(), 'assets', filename),
      path.join('/home/container/assets', filename),
      path.join(__dirname, 'assets', filename)
    ];
    for (const p of candidates) {
      if (fs.existsSync(p)) return fs.readFileSync(p);
    }
    if (EMBEDDED_ASSETS.bgs && EMBEDDED_ASSETS.bgs['bg' + num]) {
      return Buffer.from(EMBEDDED_ASSETS.bgs['bg' + num], 'base64');
    }
    return null;
  }
  static getNinjaBgPng() {
    if (EMBEDDED_ASSETS.ninjaBgPng) return Buffer.from(EMBEDDED_ASSETS.ninjaBgPng, 'base64');
    return null;
  }
  static getPanelBgPng() {
    if (EMBEDDED_ASSETS.panelBgPng) return Buffer.from(EMBEDDED_ASSETS.panelBgPng, 'base64');
    return null;
  }
  static getCyberBgSvg() {
    if (EMBEDDED_ASSETS.cyberBgSvg) return Buffer.from(EMBEDDED_ASSETS.cyberBgSvg, 'base64');
    return null;
  }
  static getLogoPng() {
    const candidates = [
      path.join(process.cwd(), 'assets', 'logo-v3.jpg'),
      path.join('/home/container/assets', 'logo-v3.jpg'),
      path.join(__dirname, 'assets', 'logo-v3.jpg')
    ];
    for (const p of candidates) {
      if (fs.existsSync(p)) return fs.readFileSync(p);
    }
    if (EMBEDDED_ASSETS.logoPng) {
      return Buffer.from(EMBEDDED_ASSETS.logoPng, 'base64');
    }
    return null;
  }
}

function parseClientHelloSni(buf) {
  if (!Buffer.isBuffer(buf) || buf.length < 42) {
    return null;
  }

  try {
    if (buf[0] !== 0x16 || buf[1] !== 0x03) {
      return null;
    }

    let offset = 5;
    if (buf[offset] !== 0x01) {
      return null;
    }

    offset += 1 + 3 + 2 + 32;
    if (offset >= buf.length) return null;

    const sessionIdLen = buf[offset];
    offset += 1 + sessionIdLen;
    if (offset + 2 > buf.length) return null;

    const cipherSuitesLen = buf.readUInt16BE(offset);
    offset += 2 + cipherSuitesLen;
    if (offset + 1 > buf.length) return null;

    const compMethodsLen = buf[offset];
    offset += 1 + compMethodsLen;
    if (offset + 2 > buf.length) return null;

    const extTotalLen = buf.readUInt16BE(offset);
    offset += 2;
    const extLimit = Math.min(offset + extTotalLen, buf.length);

    while (offset + 4 <= extLimit) {
      const extType = buf.readUInt16BE(offset);
      const extLen = buf.readUInt16BE(offset + 2);
      offset += 4;

      if (extType === 0x0000) {
        if (offset + 2 > extLimit) return null;
        const sniListLen = buf.readUInt16BE(offset);
        let sniOffset = offset + 2;
        const sniLimit = Math.min(sniOffset + sniListLen, extLimit);

        while (sniOffset + 3 <= sniLimit) {
          const nameType = buf[sniOffset];
          const nameLen = buf.readUInt16BE(sniOffset + 1);
          sniOffset += 3;

          if (nameType === 0x00 && sniOffset + nameLen <= buf.length) {
            return buf.toString('utf8', sniOffset, sniOffset + nameLen);
          }
          sniOffset += nameLen;
        }
      }

      offset += extLen;
    }

    return null;
  } catch {
    return null;
  }
}

const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  electric: '\x1b[38;5;39m',
  navy: '\x1b[38;5;25m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m',
  magenta: '\x1b[35m',
  white: '\x1b[37m'
};

class Logger {
  static quiet = false;

  static banner() {
    if (this.quiet) return;
    console.log(`${ANSI.bold}${ANSI.electric}PARHAM${ANSI.reset}`);
    console.log(`${ANSI.cyan}Panel Address:${ANSI.reset} ${ANSI.white}http://<host>:<port>/parham-confing${ANSI.reset}`);
    console.log(`${ANSI.dim}Server name: ${process.env.SERVER_NAME || process.env.PANEL_NAME || process.env.NODE_NAME || process.env.CONTAINER_NAME || 'Parham'}${ANSI.reset}`);
    console.log(`${ANSI.dim}Telegram: https://t.me/parham_ste01${ANSI.reset}`);
  }

  static renewNotice() {
    if (this.quiet) return;
    console.log(`\n${ANSI.yellow}${ANSI.bold}[!] Katabump Notice:${ANSI.reset} ${ANSI.yellow}Free/plan servers typically require renewal every ~4 days in the panel.${ANSI.reset}`);
    console.log('');
  }

  static info(msg) {
    if (!this.quiet) console.log(`${ANSI.cyan}[i] ${msg}${ANSI.reset}`);
  }

  static success(msg) {
    if (!this.quiet) console.log(`${ANSI.green}[OK] ${msg}${ANSI.reset}`);
  }

  static warn(msg) {
    if (!this.quiet) console.log(`${ANSI.yellow}[!] ${msg}${ANSI.reset}`);
  }

  static error(msg) {
    console.error(`${ANSI.red}[X] ${msg}${ANSI.reset}`);
  }

  static step(msg) {
    if (!this.quiet) console.log(`${ANSI.electric}==> ${msg}${ANSI.reset}`);
  }

  static item(label, val) {
    if (!this.quiet) {
      console.log(`  ${ANSI.cyan}${label.padEnd(18)}:${ANSI.reset} ${ANSI.white}${val}${ANSI.reset}`);
    }
  }

  static section(title) {
    if (!this.quiet) console.log(`${ANSI.bold}${ANSI.electric}${title}${ANSI.reset}`);
  }
}

