function resolveDataDir(hint = '/home/container/bk-data') {
  const customEnv = process.env.BK_DATA_DIR || process.env.FILE_PATH;
  if (customEnv) {
    try {
      fs.mkdirSync(customEnv, { recursive: true });
      fs.accessSync(customEnv, fs.constants.W_OK);
      return customEnv;
    } catch {
    }
  }

  const candidates = [
    hint,
    path.join(__dirname, '..', 'bk-data'),
    path.join(process.cwd(), 'bk-data'),
    path.join(os.tmpdir(), 'bk-data')
  ];

  for (const dir of candidates) {
    try {
      fs.mkdirSync(dir, { recursive: true });
      fs.accessSync(dir, fs.constants.W_OK);
      return dir;
    } catch {
    }
  }

  return path.join(os.tmpdir(), 'bk-data');
}

function buildConfig(userOverrides = {}) {
  const cfg = JSON.parse(JSON.stringify(DEFAULT_CONFIG));

  if (userOverrides && typeof userOverrides === 'object') {
    for (const [key, val] of Object.entries(userOverrides)) {
      if (val !== undefined && val !== null) {
        if (typeof val === 'object' && !Array.isArray(val) && cfg[key] && typeof cfg[key] === 'object') {
          cfg[key] = { ...cfg[key], ...val };
        } else {
          cfg[key] = val;
        }
      }
    }
  }

  const env = process.env;
  const parseBool = (v, defaultVal) => (v !== undefined ? v === '1' || v === 'true' : defaultVal);

  if (env.PORT || env.SERVER_PORT || env.SB_PORT) {
    cfg.publicPort = parseInt(env.PORT || env.SERVER_PORT || env.SB_PORT, 10);
  }
  if (env.UUID || env.SB_UUID) cfg.uuid = env.UUID || env.SB_UUID;
  if (env.DOMAIN || env.SB_DOMAIN) cfg.domain = env.DOMAIN || env.SB_DOMAIN;
  if (env.FORCE_HOST || env.CFIP) cfg.forceHost = env.FORCE_HOST || env.CFIP;
  if (env.ALLOW_LOCALHOST_LINKS !== undefined) cfg.allowLocalHostLinks = parseBool(env.ALLOW_LOCALHOST_LINKS, false);
  if (env.PANEL_PATH || env.SUB_PATH) cfg.panelPath = (env.PANEL_PATH || env.SUB_PATH).replace(/^\//, '');
  if (env.NODE_PREFIX) cfg.nodePrefix = env.NODE_PREFIX;
  if (env.PANEL_TOKEN) cfg.panelToken = env.PANEL_TOKEN;
  if (env.SNI_HY2 || env.SB_SNI) cfg.sniHy2 = env.SNI_HY2 || env.SB_SNI;
  if (env.MASS_PROXY_URL || env.SB_MASS_PROXY) cfg.massProxyUrl = env.MASS_PROXY_URL || env.SB_MASS_PROXY;

  if (env.ENABLE_HYSTERIA2 !== undefined) cfg.enable.hysteria2 = parseBool(env.ENABLE_HYSTERIA2, cfg.enable.hysteria2);
  if (env.ENABLE_VLESS_WS !== undefined) cfg.enable.vlessWs = parseBool(env.ENABLE_VLESS_WS, cfg.enable.vlessWs);
  if (env.ENABLE_VMESS_WS !== undefined) cfg.enable.vmessWs = parseBool(env.ENABLE_VMESS_WS, cfg.enable.vmessWs);
  if (env.ENABLE_HTTPUPGRADE !== undefined) cfg.enable.vlessHttpUpgrade = parseBool(env.ENABLE_HTTPUPGRADE, cfg.enable.vlessHttpUpgrade);
  if (env.ENABLE_XHTTP !== undefined) cfg.enable.vlessXhttp = parseBool(env.ENABLE_XHTTP, cfg.enable.vlessXhttp);
  if (env.ENABLE_VLESS_GRPC !== undefined) cfg.enable.vlessGrpc = parseBool(env.ENABLE_VLESS_GRPC, cfg.enable.vlessGrpc);
  if (env.ENABLE_TROJAN_WS !== undefined || env.ENABLE_TROJAN !== undefined) {
    cfg.enable.trojanWs = parseBool(env.ENABLE_TROJAN_WS !== undefined ? env.ENABLE_TROJAN_WS : env.ENABLE_TROJAN, cfg.enable.trojanWs);
  }
  if (env.ENABLE_SHADOWTLS_VLESS !== undefined) cfg.enable.shadowTlsVless = parseBool(env.ENABLE_SHADOWTLS_VLESS, cfg.enable.shadowTlsVless);
  if (env.ENABLE_SS !== undefined) cfg.enable.shadowsocks = parseBool(env.ENABLE_SS, cfg.enable.shadowsocks);
  if (env.ENABLE_WIREGUARD !== undefined || env.ENABLE_WG !== undefined) {
    cfg.enable.wireguard = parseBool(env.ENABLE_WIREGUARD !== undefined ? env.ENABLE_WIREGUARD : env.ENABLE_WG, cfg.enable.wireguard);
  }
  if (env.ENABLE_TUIC !== undefined) cfg.enable.tuic = parseBool(env.ENABLE_TUIC, cfg.enable.tuic);
  if (env.ENABLE_SOCKS !== undefined) cfg.enable.socks = parseBool(env.ENABLE_SOCKS, cfg.enable.socks);
  if (env.ENABLE_HTTP_PROXY !== undefined) cfg.enable.httpProxy = parseBool(env.ENABLE_HTTP_PROXY, cfg.enable.httpProxy);
  if (env.ENABLE_ARGO !== undefined) cfg.enable.argo = parseBool(env.ENABLE_ARGO, cfg.enable.argo);

  if (env.WG_PORT) cfg.wireguard.port = parseInt(env.WG_PORT, 10);
  if (env.WG_SERVER_IP) cfg.wireguard.serverIp = env.WG_SERVER_IP;
  if (env.WG_CLIENT_IP) cfg.wireguard.clientIp = env.WG_CLIENT_IP;

  if (env.TUIC_PORT) cfg.tuic.port = parseInt(env.TUIC_PORT, 10);
  if (env.TUIC_CC) cfg.tuic.congestionController = env.TUIC_CC;

  if (env.ARGO_DOMAIN) cfg.argo.domain = env.ARGO_DOMAIN;
  if (env.ARGO_AUTH) cfg.argo.auth = env.ARGO_AUTH;
  if (env.ARGO_PORT) cfg.argo.localPort = parseInt(env.ARGO_PORT, 10);

  if (env.SHADOWTLS_SNI) cfg.shadowTls.sni = env.SHADOWTLS_SNI;
  if (env.SHADOWTLS_PASSWORD) cfg.shadowTls.password = env.SHADOWTLS_PASSWORD;

  if (env.SS_METHOD) cfg.shadowsocks.method = env.SS_METHOD;
  if (env.SS_PASSWORD) cfg.shadowsocks.password = env.SS_PASSWORD;

  if (env.CPU_LIMIT_PERCENT) cfg.cpuLimitPercent = parseInt(env.CPU_LIMIT_PERCENT, 10);

  const dataDir = resolveDataDir(cfg.dataDirHint);
  const paths = {
    dataDir,
    stateFile: path.join(dataDir, 'state.json'),
    binDir: path.join(dataDir, 'bin'),
    certDir: path.join(dataDir, 'cert'),
    certPath: path.join(dataDir, 'cert', 'cert.pem'),
    keyPath: path.join(dataDir, 'cert', 'key.pem'),
    singboxBin: path.join(dataDir, 'bin', os.platform() === 'win32' ? 'sing-box.exe' : 'sing-box'),
    singboxConfig: path.join(dataDir, 'sing-box.json'),
    singboxLog: path.join(dataDir, 'sing-box.log'),
    xrayBin: path.join(dataDir, 'bin', os.platform() === 'win32' ? 'xray.exe' : 'xray'),
    xrayConfig: path.join(dataDir, 'xray.json'),
    xrayLog: path.join(dataDir, 'xray.log'),
    cloudflaredBin: path.join(dataDir, 'bin', os.platform() === 'win32' ? 'cloudflared.exe' : 'cloudflared'),
    cloudflaredLog: path.join(dataDir, 'cloudflared.log')
  };

  return {
    ...cfg,
    paths
  };
}

function findFreePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.unref();
    srv.on('error', reject);
    srv.listen(0, '127.0.0.1', () => {
      const address = srv.address();
      const port = typeof address === 'object' && address ? address.port : null;
      srv.close((err) => {
        if (err) return reject(err);
        if (!port) return reject(new Error('Failed to resolve ephemeral port'));
        resolve(port);
      });
    });
  });
}

async function allocatePorts(count = 1) {
  const ports = [];
  for (let i = 0; i < count; i++) {
    const p = await findFreePort();
    ports.push(p);
  }
  return count === 1 ? ports[0] : ports;
}

class StateManager {
  constructor(paths, initialConfig) {
    this.paths = paths;
    this.config = initialConfig;
    this.state = {
      uuid: '',
      hy2Password: '',
      hy2ObfsPassword: '',
      shadowTlsPassword: '',
      shadowsocksPassword: '',
      wireguardPrivateKey: '',
      wireguardPublicKey: '',
      wireguardClientPrivateKey: '',
      wireguardClientPublicKey: '',
      publicIp: '',
      links: [],
      clashYaml: '',
      singboxJson: '',
      xrayJson: '',
      base64Sub: '',
      updatedAt: null
    };
  }

  loadOrCreate() {
    try {
      fs.mkdirSync(this.paths.dataDir, { recursive: true });
      if (fs.existsSync(this.paths.stateFile)) {
        const raw = fs.readFileSync(this.paths.stateFile, 'utf8');
        const parsed = JSON.parse(raw);
        this.state = { ...this.state, ...parsed };
      }
    } catch (err) {
      Logger.warn(`Failed to read existing state.json: ${err.message}. Generating fresh state.`);
    }

    if (this.config.uuid) {
      this.state.uuid = this.config.uuid;
    } else if (!this.state.uuid) {
      this.state.uuid = crypto.randomUUID();
    }

    this.state.hy2Password = this.state.uuid;
    if (!this.state.hy2ObfsPassword) {
      this.state.hy2ObfsPassword = crypto.randomBytes(8).toString('hex');
    }

    if (this.config.shadowTls.password) {
      this.state.shadowTlsPassword = this.config.shadowTls.password;
    } else if (!this.state.shadowTlsPassword) {
      this.state.shadowTlsPassword = crypto.randomBytes(12).toString('hex');
    }

    if (this.config.shadowsocks.password) {
      this.state.shadowsocksPassword = this.config.shadowsocks.password;
    } else if (!this.state.shadowsocksPassword) {
      this.state.shadowsocksPassword = crypto.randomBytes(16).toString('base64url');
    }

    if (!this.state.wireguardPrivateKey || !this.state.wireguardPublicKey || !this.state.wireguardClientPrivateKey || !this.state.wireguardClientPublicKey) {
      try {
        const srv = crypto.generateKeyPairSync('x25519');
        const srvPriv = srv.privateKey.export({ type: 'pkcs8', format: 'der' }).subarray(-32).toString('base64');
        const srvPub = srv.publicKey.export({ type: 'spki', format: 'der' }).subarray(-32).toString('base64');

        const cli = crypto.generateKeyPairSync('x25519');
        const cliPriv = cli.privateKey.export({ type: 'pkcs8', format: 'der' }).subarray(-32).toString('base64');
        const cliPub = cli.publicKey.export({ type: 'spki', format: 'der' }).subarray(-32).toString('base64');

        this.state.wireguardPrivateKey = srvPriv;
        this.state.wireguardPublicKey = srvPub;
        this.state.wireguardClientPrivateKey = cliPriv;
        this.state.wireguardClientPublicKey = cliPub;
      } catch (err) {
        Logger.warn(`Failed to generate WireGuard keypair: ${err.message}`);
      }
    }

    this.save();
    return this.state;
  }

  setWireGuardKeys(serverPriv, serverPub, clientPriv, clientPub) {
    this.state.wireguardPrivateKey = serverPriv;
    this.state.wireguardPublicKey = serverPub;
    this.state.wireguardClientPrivateKey = clientPriv;
    this.state.wireguardClientPublicKey = clientPub;
    this.save();
  }

  setLinks(links, clashYaml = '', singboxJson = '', xrayJson = '') {
    this.state.links = links;
    this.state.clashYaml = clashYaml;
    this.state.singboxJson = singboxJson;
    this.state.xrayJson = xrayJson;
    this.state.base64Sub = Buffer.from(links.join('\n')).toString('base64');
    this.save();
  }

  setPublicIp(ip) {
    this.state.publicIp = ip;
    this.save();
  }

  save() {
    try {
      this.state.updatedAt = new Date().toISOString();
      fs.mkdirSync(this.paths.dataDir, { recursive: true });
      fs.writeFileSync(this.paths.stateFile, JSON.stringify(this.state, null, 2), 'utf8');
    } catch (err) {
      Logger.warn(`Could not save state.json: ${err.message}`);
    }
  }
}

function getNormalizedArch() {
  const arch = os.arch();
  if (arch === 'arm64' || arch === 'aarch64') {
    return { sb: 'arm64', xray: 'arm64-v8a', cf: 'arm64' };
  }
  return { sb: 'amd64', xray: '64', cf: 'amd64' };
}

function checkDiskSpaceMb(dir) {
  if (os.platform() !== 'linux') return 1024;
  try {
    const res = spawnSync('df', ['-m', dir], { encoding: 'utf8', timeout: 3000 });
    if (res.status === 0 && res.stdout) {
      const lines = res.stdout.trim().split('\n');
      if (lines.length >= 2) {
        const parts = lines[1].trim().split(/\s+/);
        const avail = parseInt(parts[3], 10);
        if (!isNaN(avail)) return avail;
      }
    }
  } catch {
  }
  return null;
}

const DiskGuard = {
  started: false,
  limitMb() { return Number(process.env.DISK_LIMIT_MB) || 716; },
  dirSizeMb(root) {
    let total = 0;
    const walk = (d, depth) => {
      if (depth > 8) return;
      let list = [];
      try { list = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
      for (const e of list) {
        const p = path.join(d, e.name);
        try {
          if (e.isSymbolicLink()) continue;
          if (e.isDirectory()) walk(p, depth + 1);
          else total += fs.statSync(p).size;
        } catch {}
      }
    };
    walk(root, 0);
    return total / 1048576;
  },
  clean(paths, hard) {
    const logs = [paths.singboxLog, paths.xrayLog, paths.cloudflaredLog].filter(Boolean);
    for (const f of logs) {
      try {
        const st = fs.statSync(f);
        if (hard || st.size > 1024 * 1024) fs.truncateSync(f, 0);
      } catch {}
    }
    if (!hard) return;
    try {
      for (const n of fs.readdirSync(paths.dataDir)) {
        if (/\.tmp_|^test-check-|^xray-check-|\.log\.\d+$/.test(n)) { try { fs.unlinkSync(path.join(paths.dataDir, n)); } catch {} }
      }
    } catch {}
  },
  sweep(paths) {
    this.clean(paths, false);
    const avail = checkDiskSpaceMb(paths.dataDir);
    this.n = (this.n || 0) + 1;
    const lowAvail = avail !== null && avail < 60;
    const used = lowAvail || this.n % 5 === 0 ? this.dirSizeMb(paths.dataDir) : 0;
    if (lowAvail || used > this.limitMb() * 0.9) {
      this.clean(paths, true);
      try { Events.push('warn', 'Low disk space: logs and temp files were cleaned'); } catch {}
    }
  },
  start(paths) {
    if (this.started || !paths) return;
    this.started = true;
    try { this.clean(paths, true); } catch {}
    this.n = 0;
    const t = setInterval(() => { try { this.sweep(paths); } catch {} }, 60000);
    if (t.unref) t.unref();
  }
};

async function downloadToFile(url, destPath) {
  const tempPath = `${destPath}.tmp_${Date.now()}`;
  const writer = fs.createWriteStream(tempPath);

  try {
    const resp = await axios({
      method: 'get',
      url,
      responseType: 'stream',
      timeout: 60000,
      headers: {
        'User-Agent': 'Parham ConfingGate/1.0'
      }
    });

    await new Promise((resolve, reject) => {
      resp.data.pipe(writer);
      writer.on('finish', resolve);
      writer.on('error', reject);
    });

    fs.renameSync(tempPath, destPath);
    if (os.platform() !== 'win32') {
      fs.chmodSync(destPath, 0o755);
    }
    return true;
  } catch (err) {
    try { if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath); } catch {}
    throw err;
  }
}

class BinaryManager {
  constructor(config) {
    this.config = config;
    this.paths = config.paths;
    this.arch = getNormalizedArch();
  }

  ensureDirectories() {
    fs.mkdirSync(this.paths.dataDir, { recursive: true });
    fs.mkdirSync(this.paths.binDir, { recursive: true });
    fs.mkdirSync(this.paths.certDir, { recursive: true });
  }

  async ensureSingBox() {
    this.ensureDirectories();
    const bin = this.paths.singboxBin;

    if (fs.existsSync(bin)) {
      try {
        const stat = fs.statSync(bin);
        if (stat.size > 1024 * 1024) {
          if (os.platform() !== 'win32') fs.chmodSync(bin, 0o755);
          return true;
        }
      } catch {}
    }

    const freeMb = checkDiskSpaceMb(this.paths.binDir);
    if (freeMb !== null && freeMb < 40) {
      Logger.warn(`Low disk space (~${freeMb}MB free). sing-box download might fail with ENOSPC.`);
    }

    const ver = this.config.singBoxVersion || '1.11.15';
    const osType = os.platform() === 'win32' ? 'windows' : 'linux';
    const ext = osType === 'windows' ? 'zip' : 'tar.gz';
    const tarName = `sing-box-${ver}-${osType}-${this.arch.sb}.${ext}`;
    const url = process.env.SB_URL || `https://github.com/SagerNet/sing-box/releases/download/v${ver}/${tarName}`;
    const archivePath = path.join(this.paths.binDir, tarName);

    Logger.step(`Downloading sing-box v${ver} (${osType}-${this.arch.sb})...`);

    try {
      await downloadToFile(url, archivePath);

      if (osType === 'linux') {
        const extDir = path.join(this.paths.binDir, `sb_extract_${Date.now()}`);
        fs.mkdirSync(extDir, { recursive: true });
        const tarRes = spawnSync('tar', ['-xzf', archivePath, '-C', extDir]);
        if (tarRes.status !== 0) throw new Error(`tar extraction failed: ${tarRes.stderr}`);

        const files = fs.readdirSync(extDir);
        let foundBin = null;
        for (const f of files) {
          const sub = path.join(extDir, f);
          if (fs.statSync(sub).isDirectory()) {
            const candidate = path.join(sub, 'sing-box');
            if (fs.existsSync(candidate)) {
              foundBin = candidate;
              break;
            }
          }
        }

        if (!foundBin && fs.existsSync(path.join(extDir, 'sing-box'))) {
          foundBin = path.join(extDir, 'sing-box');
        }

        if (!foundBin) throw new Error('sing-box binary not found in archive');

        fs.copyFileSync(foundBin, bin);
        fs.chmodSync(bin, 0o755);

        try {
          fs.unlinkSync(archivePath);
          fs.rmSync(extDir, { recursive: true, force: true });
        } catch {}
      }

      Logger.success('sing-box engine installed successfully.');
      return true;
    } catch (err) {
      Logger.error(`sing-box installation error: ${err.message}`);
      return false;
    }
  }

  async ensureXray() {
    this.ensureDirectories();
    const bin = this.paths.xrayBin;

    if (fs.existsSync(bin)) {
      try {
        const stat = fs.statSync(bin);
        if (stat.size > 1024 * 1024) {
          if (os.platform() !== 'win32') fs.chmodSync(bin, 0o755);
          return true;
        }
      } catch {}
    }

    const freeMb = checkDiskSpaceMb(this.paths.binDir);
    if (freeMb !== null && freeMb < 40) {
      Logger.warn(`Low disk space (~${freeMb}MB free). Skipping optional Xray-core.`);
      return false;
    }

    const osType = os.platform() === 'win32' ? 'windows' : 'linux';
    const zipName = `Xray-${osType}-${this.arch.xray}.zip`;
    const url = this.config.xrayVersion
      ? `https://github.com/XTLS/Xray-core/releases/download/v${this.config.xrayVersion}/${zipName}`
      : `https://github.com/XTLS/Xray-core/releases/latest/download/${zipName}`;
    const archivePath = path.join(this.paths.binDir, zipName);

    Logger.step(`Downloading optional Xray-core (${osType}-${this.arch.xray})...`);

    try {
      await downloadToFile(url, archivePath);
      const extDir = path.join(this.paths.binDir, `xray_extract_${Date.now()}`);
      fs.mkdirSync(extDir, { recursive: true });

      const unzipRes = spawnSync('unzip', ['-o', archivePath, '-d', extDir]);
      if (unzipRes.status !== 0) throw new Error(`unzip failed: ${unzipRes.stderr}`);

      const candidate = path.join(extDir, os.platform() === 'win32' ? 'xray.exe' : 'xray');
      if (!fs.existsSync(candidate)) throw new Error('xray binary missing after unzip');

      fs.copyFileSync(candidate, bin);
      if (os.platform() !== 'win32') fs.chmodSync(bin, 0o755);

      try {
        fs.unlinkSync(archivePath);
        fs.rmSync(extDir, { recursive: true, force: true });
      } catch {}

      Logger.success('Xray-core engine installed successfully.');
      return true;
    } catch (err) {
      Logger.warn(`Optional Xray-core download skipped: ${err.message}. XHTTP will be disabled.`);
      return false;
    }
  }

  async ensureCloudflared() {
    this.ensureDirectories();
    const bin = this.paths.cloudflaredBin;

    if (fs.existsSync(bin)) {
      try {
        if (fs.statSync(bin).size > 1024 * 1024) {
          if (os.platform() !== 'win32') fs.chmodSync(bin, 0o755);
          return true;
        }
      } catch {}
    }

    const url = os.platform() === 'win32'
      ? `https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-windows-${this.arch.cf === 'arm64' ? 'arm64' : 'amd64'}.exe`
      : `https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-${this.arch.cf}`;

    Logger.step('Downloading optional Cloudflare Argo tunnel agent (cloudflared)...');

    try {
      await downloadToFile(url, bin);
      if (os.platform() !== 'win32') fs.chmodSync(bin, 0o755);
      Logger.success('cloudflared installed successfully.');
      return true;
    } catch (err) {
      Logger.warn(`Optional cloudflared download skipped: ${err.message}. Argo tunnel will be inactive.`);
      return false;
    }
  }
}

function ensureTlsCertificates(certPath, keyPath, sni = 'www.google.com') {
  if (fs.existsSync(certPath) && fs.existsSync(keyPath)) {
    return true;
  }

  try {
    const res = spawnSync('openssl', [
      'req', '-x509', '-newkey', 'rsa:2048', '-nodes',
      '-subj', `/CN=${sni}`,
      '-keyout', keyPath,
      '-out', certPath,
      '-days', '365'
    ], { timeout: 15000 });
    if (res.status === 0 && fs.existsSync(certPath)) {
      return true;
    }
  } catch {}

  try {
    const { privateKey, publicKey } = crypto.generateKeyPairSync('rsa', {
      modulusLength: 2048,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });

    fs.writeFileSync(keyPath, privateKey, 'utf8');

    const certForge = `-----BEGIN CERTIFICATE-----\n${Buffer.from(publicKey).toString('base64').match(/.{1,64}/g)?.join('\n') || ''}\n-----END CERTIFICATE-----`;
    fs.writeFileSync(certPath, certForge, 'utf8');
    return true;
  } catch (err) {
    Logger.error(`Failed to generate TLS certificate: ${err.message}`);
    return false;
  }
}

class SingBoxEngine {
  constructor(config, stateManager, allocatedPorts) {
    this.config = config;
    this.paths = config.paths;
    this.stateManager = stateManager;
    this.ports = allocatedPorts;
    this.process = null;
  }

  buildJsonConfig() {
    const state = this.stateManager.state;
    const enable = this.config.enable;
    const wsPath = `/${this.config.panelPath}-ws`;
    const huPath = `/${this.config.panelPath}-hu`;

    const inbounds = [];

    if (enable.hysteria2) {
      inbounds.push({
        type: 'hysteria2',
        tag: 'hy2-in',
        listen: '::',
        listen_port: this.config.publicPort,
        users: [
          { password: state.hy2Password }
        ],
        tls: {
          enabled: true,
          server_name: this.config.sniHy2 || 'www.google.com',
          alpn: ['h3'],
          certificate_path: this.paths.certPath,
          key_path: this.paths.keyPath
        },
        obfs: {
          type: 'salamander',
          password: state.hy2ObfsPassword
        },
        masquerade: {
          type: 'proxy',
          url: this.config.massProxyUrl || 'https://www.gstatic.com',
          rewrite_host: true
        },
        ignore_client_bandwidth: false,
        up_mbps: 1000,
        down_mbps: 1000
      });
    }

    if (enable.vlessWs && this.ports.vlessWs) {
      inbounds.push({
        type: 'vless',
        tag: 'vless-ws-in',
        listen: '127.0.0.1',
        listen_port: this.ports.vlessWs,
        users: [
          { uuid: state.uuid, flow: '' }
        ],
        tls: { enabled: false },
        transport: {
          type: 'ws',
          path: wsPath,
          max_early_data: 2560,
          early_data_header_name: 'Sec-WebSocket-Protocol'
        }
      });
    }

    if (enable.vmessWs && this.ports.vmessWs) {
      inbounds.push({
        type: 'vmess',
        tag: 'vmess-ws-in',
        listen: '127.0.0.1',
        listen_port: this.ports.vmessWs,
        users: [
          { uuid: state.uuid, alterId: 0 }
        ],
        tls: { enabled: false },
        transport: {
          type: 'ws',
          path: `/${this.config.panelPath}-vmess`,
          max_early_data: 2560,
          early_data_header_name: 'Sec-WebSocket-Protocol'
        }
      });
    }

    if (enable.vlessHttpUpgrade && this.ports.vlessHu) {
      inbounds.push({
        type: 'vless',
        tag: 'vless-hu-in',
        listen: '127.0.0.1',
        listen_port: this.ports.vlessHu,
        users: [
          { uuid: state.uuid, flow: '' }
        ],
        tls: { enabled: false },
        transport: {
          type: 'httpupgrade',
          path: huPath
        }
      });
    }

    if (enable.shadowTlsVless && this.ports.shadowTls) {
      inbounds.push(
        {
          type: 'shadowtls',
          tag: 'shadowtls-in',
          listen: '127.0.0.1',
          listen_port: this.ports.shadowTls,
          version: 3,
          users: [
            { name: 'bk-user', password: state.shadowTlsPassword }
          ],
          handshake: {
            server: this.config.shadowTls.sni || 'www.microsoft.com',
            server_port: 443
          },
          strict_mode: true,
          detour: 'vless-shadowtls-detour'
        },
        {
          type: 'vless',
          tag: 'vless-shadowtls-detour',
          listen: '127.0.0.1',
          listen_port: 0,
          users: [
            { uuid: state.uuid, flow: '' }
          ]
        }
      );
    }

    if (enable.shadowsocks && this.ports.shadowsocks) {
      inbounds.push({
        type: 'shadowsocks',
        tag: 'ss-in',
        listen: '127.0.0.1',
        listen_port: this.ports.shadowsocks,
        method: this.config.shadowsocks.method || 'aes-256-gcm',
        password: state.shadowsocksPassword
      });
    }

    if (enable.socks && this.ports.socks) {
      inbounds.push({
        type: 'socks',
        tag: 'socks-in',
        listen: '127.0.0.1',
        listen_port: this.ports.socks,
        users: this.config.socks.user
          ? [{ username: this.config.socks.user, password: this.config.socks.pass }]
          : []
      });
    }

    if (enable.httpProxy && this.ports.httpProxy) {
      inbounds.push({
        type: 'http',
        tag: 'http-in',
        listen: '127.0.0.1',
        listen_port: this.ports.httpProxy,
        users: this.config.httpProxy.user
          ? [{ username: this.config.httpProxy.user, password: this.config.httpProxy.pass }]
          : []
      });
    }

    if (enable.trojanWs && this.ports.trojanWs) {
      inbounds.push({
        type: 'trojan',
        tag: 'trojan-ws-in',
        listen: '127.0.0.1',
        listen_port: this.ports.trojanWs,
        users: [
          { password: state.uuid }
        ],
        transport: {
          type: 'ws',
          path: `/${this.config.panelPath}-trojan`
        }
      });
    }

    if (enable.vlessGrpc && this.ports.vlessGrpc) {
      inbounds.push({
        type: 'vless',
        tag: 'vless-grpc-in',
        listen: '127.0.0.1',
        listen_port: this.ports.vlessGrpc,
        users: [
          { uuid: state.uuid, flow: '' }
        ],
        tls: { enabled: false },
        transport: {
          type: 'grpc',
          service_name: `${this.config.panelPath}-grpc`
        }
      });
    }

    if (enable.tuic && this.config.tuic) {
      inbounds.push({
        type: 'tuic',
        tag: 'tuic-in',
        listen: '::',
        listen_port: this.config.tuic.port || 8443,
        users: [
          { uuid: state.uuid, password: state.uuid }
        ],
        congestion_controller: this.config.tuic.congestionController || 'bbr',
        tls: {
          enabled: true,
          server_name: this.config.sniHy2 || 'www.google.com',
          alpn: ['h3'],
          certificate_path: this.paths.certPath,
          key_path: this.paths.keyPath
        }
      });
    }

    const cfg = {
      log: {
        level: 'error',
        timestamp: true
      },
      inbounds,
      outbounds: [
        { type: 'direct', tag: 'direct' },
        { type: 'block', tag: 'block' }
      ]
    };

    if (enable.wireguard && this.config.wireguard && state.wireguardPrivateKey && state.wireguardClientPublicKey) {
      cfg.endpoints = [
        {
          type: 'wireguard',
          tag: 'wg-in',
          system: false,
          name: 'bk-wg0',
          mtu: this.config.wireguard.mtu || 1420,
          address: [this.config.wireguard.serverIp || '10.66.66.1/32'],
          private_key: state.wireguardPrivateKey,
          listen_port: this.config.wireguard.port || 51820,
          peers: [
            {
              public_key: state.wireguardClientPublicKey,
              allowed_ips: [this.config.wireguard.clientIp || '10.66.66.2/32']
            }
          ]
        }
      ];
    }

    return cfg;
  }

  testConfigSync(cfgObj) {
    const tmpFile = path.join(this.paths.dataDir, `test-check-${Date.now()}.json`);
    try {
      fs.writeFileSync(tmpFile, JSON.stringify(cfgObj, null, 2), 'utf8');
      const res = spawnSync(this.paths.singboxBin, ['check', '-c', tmpFile], {
        encoding: 'utf8',
        timeout: 8000
      });
      try { fs.unlinkSync(tmpFile); } catch {}
      return {
        ok: res.status === 0,
        error: (res.stderr || res.stdout || '').trim()
      };
    } catch (err) {
      try { fs.unlinkSync(tmpFile); } catch {}
      return { ok: false, error: err.message };
    }
  }

  validateAndSanitize(configData) {
    let check = this.testConfigSync(configData);
    if (check.ok) return configData;

    Logger.warn(`sing-box initial check reported: ${check.error}. Running resilience auto-fix...`);

    if (configData.endpoints && configData.endpoints.length > 0) {
      delete configData.endpoints;
      check = this.testConfigSync(configData);
      if (check.ok) {
        Logger.warn('sing-box validated after omitting endpoints. Core engines running.');
        return configData;
      }
    }

    const optionalTags = ['tuic-in', 'vless-grpc-in', 'trojan-ws-in', 'socks-in', 'http-in', 'shadowtls-in', 'vless-shadowtls-detour'];
    for (const tag of optionalTags) {
      const idx = configData.inbounds.findIndex(ib => ib.tag === tag);
      if (idx !== -1) {
        configData.inbounds.splice(idx, 1);
        check = this.testConfigSync(configData);
        if (check.ok) {
          Logger.warn(`sing-box validated after stripping ${tag}. Continuing with stable inbounds.`);
          return configData;
        }
      }
    }

    const coreTags = ['hy2-in', 'vless-ws-in', 'ss-in'];
    configData.inbounds = configData.inbounds.filter(ib => coreTags.includes(ib.tag));
    check = this.testConfigSync(configData);
    if (check.ok) {
      Logger.warn('sing-box validated with minimum core inbounds (Hysteria2, VLESS-WS, Shadowsocks).');
      return configData;
    }

    return null;
  }

  start() {
    if (!fs.existsSync(this.paths.singboxBin)) {
      Logger.warn('sing-box executable missing. Core engine skipped.');
      return false;
    }

    ensureTlsCertificates(this.paths.certPath, this.paths.keyPath, this.config.sniHy2);

    let configData = this.buildJsonConfig();
    configData = this.validateAndSanitize(configData);

    if (!configData) {
      Logger.error('sing-box validation failed completely even after auto-fix attempts.');
      return false;
    }

    fs.writeFileSync(this.paths.singboxConfig, JSON.stringify(configData, null, 2), 'utf8');
    Logger.success('sing-box configuration validated.');

    const logFd = fs.openSync(this.paths.singboxLog, 'a');
    this.process = spawn(this.paths.singboxBin, ['run', '-c', this.paths.singboxConfig], {
      stdio: ['ignore', logFd, logFd],
      env: LOW_RES_ENV('110MiB', '2'),
      detached: false
    });

    this.process.on('error', (err) => {
      Logger.error(`sing-box process error: ${err.message}`);
    });

    this.process.on('exit', (code, sig) => {
      try { fs.closeSync(logFd); } catch {}
      if (code !== 0 && code !== null) {
        Logger.warn(`sing-box exited with code ${code} (${sig || 'none'})`);
      }
    });

    return true;
  }

  stop() {
    if (this.process && !this.process.killed) {
      try {
        this.process.kill('SIGTERM');
      } catch {}
    }
  }
}

class XrayEngine {
  constructor(config, stateManager, localPort) {
    this.config = config;
    this.paths = config.paths;
    this.stateManager = stateManager;
    this.port = localPort;
    this.process = null;
  }

  buildConfig() {
    const state = this.stateManager.state;
    const xhttpPath = `/${this.config.panelPath}-xh`;

    return {
      log: {
        access: 'none',
        loglevel: 'error'
      },
      inbounds: [
        {
          port: this.port,
          listen: '127.0.0.1',
          protocol: 'vless',
          settings: {
            clients: [
              {
                id: state.uuid,
                level: 0
              }
            ],
            decryption: 'none'
          },
          streamSettings: {
            network: 'xhttp',
            xhttpSettings: {
              path: xhttpPath,
              mode: 'auto'
            }
          }
        }
      ],
      outbounds: [
        {
          protocol: 'freedom',
          tag: 'direct'
        }
      ]
    };
  }

  start() {
    if (!fs.existsSync(this.paths.xrayBin)) {
      return false;
    }

    const cfg = this.buildConfig();
    fs.writeFileSync(this.paths.xrayConfig, JSON.stringify(cfg, null, 2), 'utf8');

    const logFd = fs.openSync(this.paths.xrayLog, 'a');
    this.process = spawn(this.paths.xrayBin, ['run', '-c', this.paths.xrayConfig], {
      stdio: ['ignore', logFd, logFd],
      env: LOW_RES_ENV('60MiB', '1'),
      detached: false
    });

    this.process.on('error', (err) => {
      Logger.warn(`Xray engine error: ${err.message}`);
    });

    this.process.on('exit', () => {
      try { fs.closeSync(logFd); } catch {}
    });

    Logger.success(`Xray-core (XHTTP) running on local port ${this.port}.`);
    return true;
  }

  stop() {
    if (this.process && !this.process.killed) {
      try {
        this.process.kill('SIGTERM');
      } catch {}
    }
  }
}

class ArgoTunnel {
  constructor(config, targetPort) {
    this.config = config;
    this.paths = config.paths;
    this.targetPort = targetPort;
    this.process = null;
    this.tunnelDomain = '';
  }

  async discoverDomain(timeoutMs = 45000) {
    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      for (const p of [2000, 2001, 2002]) {
        try {
          const resp = await axios.get(`http://127.0.0.1:${p}/quicktunnel`, { timeout: 1500 });
          if (resp.data && resp.data.hostname) {
            return resp.data.hostname.replace(/^https?:\/\//, '').trim().toLowerCase();
          }
        } catch {}
      }

      if (fs.existsSync(this.paths.cloudflaredLog)) {
        try {
          const logContent = fs.readFileSync(this.paths.cloudflaredLog, 'utf8');
          const match = logContent.match(/https?:\/\/([a-z0-9-]+\.trycloudflare\.com)/i);
          if (match) {
            return match[1].toLowerCase();
          }
        } catch {}
      }

      await new Promise(r => setTimeout(r, 2000));
    }
    return null;
  }

  async start() {
    if (!this.config.enable.argo || !fs.existsSync(this.paths.cloudflaredBin)) {
      return null;
    }

    if (this.config.argo.auth && this.config.argo.domain) {
      this.tunnelDomain = this.config.argo.domain;
      Logger.success(`Cloudflare named tunnel active: ${this.tunnelDomain}`);
      return this.tunnelDomain;
    }

    Logger.step('Launching Cloudflare Argo Quick Tunnel...');
    const logFd = fs.openSync(this.paths.cloudflaredLog, 'a');

    this.process = spawn(this.paths.cloudflaredBin, [
      'tunnel', '--no-autoupdate', '--loglevel', 'error', '--metrics', '127.0.0.1:2000',
      '--url', `http://127.0.0.1:${this.targetPort}`
    ], {
      stdio: ['ignore', logFd, logFd],
      env: LOW_RES_ENV('50MiB', '1'),
      detached: false
    });

    this.process.on('exit', () => {
      try { fs.closeSync(logFd); } catch {}
    });

    this.tunnelDomain = await this.discoverDomain();
    if (this.tunnelDomain) {
      Logger.success(`Argo Quick Tunnel ready: ${this.tunnelDomain}`);
    } else {
      Logger.warn('Argo tunnel domain could not be resolved within timeout.');
    }

    return this.tunnelDomain;
  }

  stop() {
    if (this.process && !this.process.killed) {
      try { this.process.kill('SIGTERM'); } catch {}
    }
  }
}

function isLocalAddress(host) {
  if (!host) return true;
  const clean = host.toLowerCase().trim();
  return (
    clean === '127.0.0.1' ||
    clean === 'localhost' ||
    clean === '::1' ||
    clean === '0.0.0.0' ||
    clean.startsWith('127.')
  );
}

function isValidNode(node, options = {}) {
  if (!node || !node.uri || typeof node.uri !== 'string') return false;

  const { allowLocalHostLinks = false, compatMode = 'v2ray' } = options;
  const uri = node.uri.trim();

  if (/^vmess:\/\//i.test(uri)) {
    try {
      const j = JSON.parse(Buffer.from(uri.slice(8), 'base64').toString('utf8'));
      if (!j || !j.id || !j.add) return false;
      if (!options.allowLocalHostLinks && isLocalAddress(j.add)) return false;
      return true;
    } catch { return false; }
  }

  try {
    const parsed = new URL(uri);
    const scheme = parsed.protocol.replace(':', '').toLowerCase();

    if (!allowLocalHostLinks && isLocalAddress(parsed.hostname)) {
      return false;
    }

    if (compatMode === 'v2ray') {
      const allowedSchemes = ['vless', 'vmess', 'hysteria2', 'hy2', 'ss', 'trojan'];
      if (!allowedSchemes.includes(scheme)) {
        return false;
      }
    }

    if (scheme === 'vless') {
      const uuid = parsed.username;
      if (!uuid || uuid.length < 8) return false;

      const type = parsed.searchParams.get('type');
      if (type === 'ws') {
        const pathVal = parsed.searchParams.get('path');
        if (!pathVal) return false;
      }

      if (type === 'grpc') {
        const serviceName = parsed.searchParams.get('serviceName');
        if (!serviceName) return false;
      }

      if (compatMode === 'v2ray' && (type === 'httpupgrade' || type === 'xhttp')) {
        return false;
      }
    }

    if (scheme === 'trojan') {
      if (!parsed.username) return false;
    }

    if (scheme === 'hysteria2' || scheme === 'hy2') {
      if (!parsed.username) return false;
      if (!parsed.port && parsed.port !== '443') return false;
    }

    if (scheme === 'ss') {
      if (!parsed.username && !parsed.hostname) return false;
    }

    return true;
  } catch {
    return false;
  }
}

function urlSafeEncode(str) {
  return encodeURIComponent(str);
}

function yamlSafeQuote(str) {
  return `"${String(str).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

class LinkGenerator {
  constructor(config, state, resolvedHost) {
    this.config = config;
    this.state = state;
    this.hostInfo = HostDetect.effective(config, resolvedHost);
    this.host = this.hostInfo.source === 'auto' ? (config.forceHost || resolvedHost || config.domain || '127.0.0.1') : this.hostInfo.host;
    this.port = this.hostInfo.linkPort;
    this.prefix = config.nodePrefix || 'Parham Confing • ';
    this.nameMap = { Hysteria2:'Thunder H2', 'VLESS-WS':'Phantom WS', 'VLESS-HTTPUpgrade':'Eclipse HU', 'ShadowTLS-VLESS':'Shadow Veil', Shadowsocks:'Ghost SS', WireGuard:'Aegis WG', TUIC:'Velocity TUIC', 'VLESS-XHTTP':'Quantum X', 'VLESS-Argo':'Aurora Argo', 'Trojan-WS':'Crimson WS', 'VMess-WS':'Mirage VM', 'VLESS-gRPC':'Nova gRPC' };
    this.displayName = (key) => `${this.prefix}${this.nameMap[key] || key}`;
    this.wsPath = `/${config.panelPath}-ws`;
    this.huPath = `/${config.panelPath}-hu`;
    this.vmPath = `/${config.panelPath}-vmess`;
    this.xhPath = `/${config.panelPath}-xh`;
  }

  generateHysteria2() {
    if (!this.config.enable.hysteria2) return null;
    const name = this.displayName('Hysteria2');
    const sni = this.config.sniHy2 || 'www.google.com';
    const clashProxy = {
      name,
      type: 'hysteria2',
      server: this.host,
      port: this.port,
      password: this.state.hy2Password,
      sni,
      'skip-cert-verify': true,
      obfs: 'salamander',
      'obfs-password': this.state.hy2ObfsPassword,
      alpn: ['h3']
    };
    const sbOutbound = {
      type: 'hysteria2',
      tag: name,
      server: this.host,
      server_port: this.port,
      password: this.state.hy2Password,
      tls: {
        enabled: true,
        server_name: sni,
        insecure: true,
        alpn: ['h3']
      },
      obfs: {
        type: 'salamander',
        password: this.state.hy2ObfsPassword
      }
    };
    return {
      name,
      type: 'Hysteria2',
      compat: true,
      uri: `hysteria2://${this.state.hy2Password}@${this.host}:${this.port}?sni=${sni}&obfs=salamander&obfs-password=${this.state.hy2ObfsPassword}&insecure=1#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateVlessWs() {
    if (!this.config.enable.vlessWs) return null;
    const name = this.displayName('VLESS-WS');
    const clashProxy = {
      name,
      type: 'vless',
      server: this.host,
      port: this.port,
      uuid: this.state.uuid,
      network: 'ws',
      tls: false,
      'ws-opts': {
        path: this.wsPath,
        headers: { Host: this.host }
      }
    };
    const sbOutbound = {
      type: 'vless',
      tag: name,
      server: this.host,
      server_port: this.port,
      uuid: this.state.uuid,
      transport: {
        type: 'ws',
        path: this.wsPath,
        headers: { Host: this.host }
      }
    };
    return {
      name,
      type: 'VLESS-WS',
      compat: true,
      uri: `vless://${this.state.uuid}@${this.host}:${this.port}?encryption=none&security=none&type=ws&host=${this.host}&path=${urlSafeEncode(this.wsPath)}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateVmessWs() {
    if (!this.config.enable.vmessWs) return null;
    const name = this.displayName('VMess-WS');
    const clashProxy = {
      name, type: 'vmess', server: this.host, port: this.port, uuid: this.state.uuid, alterId: 0, cipher: 'auto',
      network: 'ws', tls: false, 'ws-opts': { path: this.vmPath, headers: { Host: this.host } }
    };
    const sbOutbound = {
      type: 'vmess', tag: name, server: this.host, server_port: this.port, uuid: this.state.uuid, security: 'auto', alter_id: 0,
      transport: { type: 'ws', path: this.vmPath, headers: { Host: this.host } }
    };
    return {
      name, type: 'VMess-WS', compat: true,
      uri: vmessUri({ name, host: this.host, port: this.port, uuid: this.state.uuid, path: this.vmPath, tls: false }),
      clash: clashProxy, singboxOutbound: [sbOutbound], singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateVlessHttpUpgrade() {
    if (!this.config.enable.vlessHttpUpgrade) return null;
    const name = this.displayName('VLESS-HTTPUpgrade');
    const clashProxy = {
      name,
      type: 'vless',
      server: this.host,
      port: this.port,
      uuid: this.state.uuid,
      network: 'httpupgrade',
      tls: false,
      'httpupgrade-opts': {
        path: this.huPath,
        host: this.host
      }
    };
    const sbOutbound = {
      type: 'vless',
      tag: name,
      server: this.host,
      server_port: this.port,
      uuid: this.state.uuid,
      transport: {
        type: 'httpupgrade',
        path: this.huPath,
        host: this.host
      }
    };
    return {
      name,
      type: 'VLESS-HTTPUpgrade',
      compat: false,
      uri: `vless://${this.state.uuid}@${this.host}:${this.port}?encryption=none&security=none&type=httpupgrade&path=${urlSafeEncode(this.huPath)}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateShadowTls() {
    if (!this.config.enable.shadowTlsVless || !this.state.shadowTlsPassword) return null;
    const name = this.displayName('ShadowTLS-VLESS');
    const sni = this.config.shadowTls.sni || 'www.microsoft.com';
    const clashProxy = {
      name,
      type: 'shadow-tls',
      server: this.host,
      port: this.port,
      password: this.state.shadowTlsPassword,
      version: 3,
      sni
    };
    const sbOutbounds = [
      {
        type: 'shadowtls',
        tag: name,
        server: this.host,
        server_port: this.port,
        version: 3,
        password: this.state.shadowTlsPassword,
        tls: {
          enabled: true,
          server_name: sni
        },
        detour: `${name}-detour`
      },
      {
        type: 'vless',
        tag: `${name}-detour`,
        server: this.host,
        server_port: this.port,
        uuid: this.state.uuid
      }
    ];
    return {
      name,
      type: 'ShadowTLS-VLESS',
      compat: false,
      uri: `shadowtls://${this.state.shadowTlsPassword}@${this.host}:${this.port}?sni=${sni}&version=3#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: sbOutbounds,
      singboxJson: JSON.stringify(sbOutbounds, null, 2),
      note: 'Use Hiddify, sing-box, or Clash Meta'
    };
  }

  generateShadowsocks() {
    if (!this.config.enable.shadowsocks || !this.state.shadowsocksPassword) return null;
    const name = this.displayName('Shadowsocks');
    const method = this.config.shadowsocks.method || 'aes-256-gcm';
    const auth = Buffer.from(`${method}:${this.state.shadowsocksPassword}`).toString('base64');
    const clashProxy = {
      name,
      type: 'ss',
      server: this.host,
      port: this.port,
      cipher: method,
      password: this.state.shadowsocksPassword
    };
    const sbOutbound = {
      type: 'shadowsocks',
      tag: name,
      server: this.host,
      server_port: this.port,
      method,
      password: this.state.shadowsocksPassword
    };
    return {
      name,
      type: 'Shadowsocks',
      compat: true,
      uri: `ss://${auth}@${this.host}:${this.port}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateWireGuard() {
    if (!this.config.enable.wireguard) return null;
    if (!this.state.wireguardClientPrivateKey || !this.state.wireguardPublicKey) return null;

    const name = this.displayName('WireGuard');
    const port = this.config.wireguard.port || 51820;
    const clientIp = this.config.wireguard.clientIp || '10.66.66.2/32';
    const mtu = this.config.wireguard.mtu || 1420;

    const wgConf = [
      '[Interface]',
      `PrivateKey = ${this.state.wireguardClientPrivateKey}`,
      `Address = ${clientIp}`,
      'DNS = 1.1.1.1, 8.8.8.8',
      `MTU = ${mtu}`,
      '',
      '[Peer]',
      `PublicKey = ${this.state.wireguardPublicKey}`,
      `Endpoint = ${this.host}:${port}`,
      'AllowedIPs = 0.0.0.0/0, ::/0',
      'PersistentKeepalive = 25'
    ].join('\n');

    const clashProxy = {
      name,
      type: 'wireguard',
      server: this.host,
      port,
      ip: clientIp.replace(/\/.*$/, ''),
      'public-key': this.state.wireguardPublicKey,
      'private-key': this.state.wireguardClientPrivateKey,
      udp: true,
      'remote-dns-resolve': true,
      dns: ['1.1.1.1', '8.8.8.8'],
      mtu
    };

    const sbOutbound = {
      type: 'wireguard',
      tag: name,
      server: this.host,
      server_port: port,
      local_address: [clientIp],
      private_key: this.state.wireguardClientPrivateKey,
      peer_public_key: this.state.wireguardPublicKey,
      mtu
    };

    const rawUri = `wireguard://${encodeURIComponent(this.state.wireguardClientPrivateKey)}@${this.host}:${port}?publickey=${encodeURIComponent(this.state.wireguardPublicKey)}&address=${encodeURIComponent(clientIp)}&mtu=${mtu}#${urlSafeEncode(name)}`;

    return {
      name,
      type: 'WireGuard',
      compat: false,
      uri: rawUri,
      wgConf,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2),
      note: 'WireGuard .conf / Clash Meta / Sing-box'
    };
  }

  generateTuic() {
    if (!this.config.enable.tuic) return null;
    const name = this.displayName('TUIC');
    const port = this.config.tuic.port || 8443;
    const sni = this.config.sniHy2 || 'www.google.com';
    const cc = this.config.tuic.congestionController || 'bbr';

    const clashProxy = {
      name,
      type: 'tuic',
      server: this.host,
      port,
      uuid: this.state.uuid,
      password: this.state.uuid,
      alpn: ['h3'],
      sni,
      'skip-cert-verify': true,
      'congestion-controller': cc,
      udp: true
    };

    const sbOutbound = {
      type: 'tuic',
      tag: name,
      server: this.host,
      server_port: port,
      uuid: this.state.uuid,
      password: this.state.uuid,
      congestion_controller: cc,
      tls: {
        enabled: true,
        server_name: sni,
        alpn: ['h3'],
        insecure: true
      }
    };

    return {
      name,
      type: 'TUIC',
      compat: false,
      uri: `tuic://${this.state.uuid}:${this.state.uuid}@${this.host}:${port}?congestion_control=${cc}&alpn=h3&sni=${sni}&allow_insecure=1#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateXhttp() {
    if (!this.config.enable.vlessXhttp) return null;
    const name = this.displayName('VLESS-XHTTP');
    return {
      name,
      type: 'VLESS-XHTTP',
      compat: false,
      uri: `vless://${this.state.uuid}@${this.host}:${this.port}?encryption=none&security=none&type=xhttp&path=${urlSafeEncode(this.xhPath)}&mode=auto#${urlSafeEncode(name)}`,
      clash: null
    };
  }

  generateArgo(argoDomain) {
    if (!this.config.enable.argo || !argoDomain) return null;
    const name = this.displayName('VLESS-Argo');
    const clashProxy = {
      name,
      type: 'vless',
      server: argoDomain,
      port: 443,
      uuid: this.state.uuid,
      network: 'ws',
      tls: true,
      servername: argoDomain,
      'ws-opts': {
        path: this.wsPath,
        headers: { Host: argoDomain }
      }
    };
    const sbOutbound = {
      type: 'vless',
      tag: name,
      server: argoDomain,
      server_port: 443,
      uuid: this.state.uuid,
      tls: {
        enabled: true,
        server_name: argoDomain
      },
      transport: {
        type: 'ws',
        path: this.wsPath,
        headers: { Host: argoDomain }
      }
    };
    return {
      name,
      type: 'VLESS-Argo',
      compat: true,
      uri: `vless://${this.state.uuid}@${argoDomain}:443?encryption=none&security=tls&sni=${argoDomain}&type=ws&host=${argoDomain}&path=${urlSafeEncode(this.wsPath)}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateEdgeNodes() {
    const out = [];
    const tls = !!(this.hostInfo && this.hostInfo.tls);
    const host = this.host, port = this.port;
    const sec = tls ? `security=tls&sni=${host}&` : 'security=none&';
    if (this.config.enable.vlessWs) {
      const name = this.displayName('VLESS-WS');
      const clash = { name, type: 'vless', server: host, port, uuid: this.state.uuid, network: 'ws', tls, 'ws-opts': { path: this.wsPath, headers: { Host: host } } };
      if (tls) clash.servername = host;
      const sb = { type: 'vless', tag: name, server: host, server_port: port, uuid: this.state.uuid, transport: { type: 'ws', path: this.wsPath, headers: { Host: host } } };
      if (tls) sb.tls = { enabled: true, server_name: host };
      out.push({ name, type: 'VLESS-WS', compat: true, uri: `vless://${this.state.uuid}@${host}:${port}?encryption=none&${sec}type=ws&host=${host}&path=${urlSafeEncode(this.wsPath)}#${urlSafeEncode(name)}`, clash, singboxOutbound: [sb], singboxJson: JSON.stringify([sb], null, 2) });
    }
    if (this.config.enable.trojanWs) {
      const name = this.displayName('Trojan-WS');
      const trPath = `/${this.config.panelPath}-trojan`;
      const clash = { name, type: 'trojan', server: host, port, password: this.state.uuid, network: 'ws', tls, 'ws-opts': { path: trPath, headers: { Host: host } } };
      if (tls) clash.sni = host;
      const sb = { type: 'trojan', tag: name, server: host, server_port: port, password: this.state.uuid, transport: { type: 'ws', path: trPath, headers: { Host: host } } };
      if (tls) sb.tls = { enabled: true, server_name: host };
      out.push({ name, type: 'Trojan-WS', compat: true, uri: `trojan://${this.state.uuid}@${host}:${port}?${sec}type=ws&host=${host}&path=${urlSafeEncode(trPath)}#${urlSafeEncode(name)}`, clash, singboxOutbound: [sb], singboxJson: JSON.stringify([sb], null, 2) });
    }
    if (this.config.enable.vmessWs) {
      const name = this.displayName('VMess-WS');
      const clash = { name, type: 'vmess', server: host, port, uuid: this.state.uuid, alterId: 0, cipher: 'auto', network: 'ws', tls, 'ws-opts': { path: this.vmPath, headers: { Host: host } } };
      if (tls) clash.servername = host;
      const sb = { type: 'vmess', tag: name, server: host, server_port: port, uuid: this.state.uuid, security: 'auto', alter_id: 0, transport: { type: 'ws', path: this.vmPath, headers: { Host: host } } };
      if (tls) sb.tls = { enabled: true, server_name: host };
      out.push({ name, type: 'VMess-WS', compat: true, uri: vmessUri({ name, host, port, uuid: this.state.uuid, path: this.vmPath, tls }), clash, singboxOutbound: [sb], singboxJson: JSON.stringify([sb], null, 2) });
    }
    return out;
  }

  generateTrojanWs() {
    if (!this.config.enable.trojanWs) return null;
    const name = this.displayName('Trojan-WS');
    const trPath = `/${this.config.panelPath}-trojan`;
    const clashProxy = {
      name,
      type: 'trojan',
      server: this.host,
      port: this.port,
      password: this.state.uuid,
      network: 'ws',
      tls: false,
      'ws-opts': {
        path: trPath,
        headers: { Host: this.host }
      }
    };
    const sbOutbound = {
      type: 'trojan',
      tag: name,
      server: this.host,
      server_port: this.port,
      password: this.state.uuid,
      transport: {
        type: 'ws',
        path: trPath,
        headers: { Host: this.host }
      }
    };
    return {
      name,
      type: 'Trojan-WS',
      compat: true,
      uri: `trojan://${this.state.uuid}@${this.host}:${this.port}?security=none&type=ws&host=${this.host}&path=${urlSafeEncode(trPath)}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  generateVlessGrpc() {
    if (!this.config.enable.vlessGrpc) return null;
    const name = this.displayName('VLESS-gRPC');
    const serviceName = `${this.config.panelPath}-grpc`;
    const clashProxy = {
      name,
      type: 'vless',
      server: this.host,
      port: this.port,
      uuid: this.state.uuid,
      network: 'grpc',
      tls: false,
      'grpc-opts': {
        'grpc-service-name': serviceName
      }
    };
    const sbOutbound = {
      type: 'vless',
      tag: name,
      server: this.host,
      server_port: this.port,
      uuid: this.state.uuid,
      transport: {
        type: 'grpc',
        service_name: serviceName
      }
    };
    return {
      name,
      type: 'VLESS-gRPC',
      compat: true,
      uri: `vless://${this.state.uuid}@${this.host}:${this.port}?encryption=none&security=none&type=grpc&serviceName=${urlSafeEncode(serviceName)}#${urlSafeEncode(name)}`,
      clash: clashProxy,
      singboxOutbound: [sbOutbound],
      singboxJson: JSON.stringify([sbOutbound], null, 2)
    };
  }

  getAllNodes(options = {}) {
    let argoDomain = null;
    let compat = 'v2ray';
    let allowLocalHost = this.config.allowLocalHostLinks || false;

    if (typeof options === 'string') {
      argoDomain = options;
    } else if (options && typeof options === 'object') {
      argoDomain = options.argoDomain || null;
      if (options.compat) compat = options.compat;
      if (options.allowLocalHostLinks !== undefined) allowLocalHost = options.allowLocalHostLinks;
    }

    const all = [
      this.generateHysteria2(),
      this.generateVlessWs(),
      this.generateVmessWs(),
      this.generateVlessHttpUpgrade(),
      this.generateVlessGrpc(),
      this.generateTrojanWs(),
      this.generateShadowTls(),
      this.generateShadowsocks(),
      this.generateWireGuard(),
      this.generateTuic(),
      this.generateXhttp(),
      this.generateArgo(argoDomain)
    ].filter(Boolean);

    return (this.hostInfo && this.hostInfo.edge ? [...this.generateEdgeNodes(), this.generateArgo(argoDomain)].filter(Boolean) : all).filter(node => isValidNode(node, { allowLocalHostLinks: allowLocalHost, compatMode: compat }));
  }

  buildClashMetaYaml(nodes) {
    const proxyLines = [];
    const proxyNames = [];

    for (const node of nodes) {
      if (!node.clash) continue;
      proxyNames.push(node.clash.name);
      proxyLines.push(`  - name: ${yamlSafeQuote(node.clash.name)}`);
      proxyLines.push(`    type: ${node.clash.type}`);
      proxyLines.push(`    server: ${yamlSafeQuote(node.clash.server)}`);
      proxyLines.push(`    port: ${node.clash.port}`);

      if (node.clash.password) proxyLines.push(`    password: ${yamlSafeQuote(node.clash.password)}`);
      if (node.clash.uuid) proxyLines.push(`    uuid: ${yamlSafeQuote(node.clash.uuid)}`);
      if (node.clash.alterId !== undefined) proxyLines.push(`    alterId: ${node.clash.alterId}`);
      if (node.clash.cipher) proxyLines.push(`    cipher: ${node.clash.cipher}`);
      if (node.clash.sni) proxyLines.push(`    sni: ${yamlSafeQuote(node.clash.sni)}`);
      if (node.clash.servername) proxyLines.push(`    servername: ${yamlSafeQuote(node.clash.servername)}`);
      if (node.clash['skip-cert-verify'] !== undefined) proxyLines.push(`    skip-cert-verify: ${node.clash['skip-cert-verify']}`);
      if (node.clash.obfs) proxyLines.push(`    obfs: ${node.clash.obfs}`);
      if (node.clash['obfs-password']) proxyLines.push(`    obfs-password: ${yamlSafeQuote(node.clash['obfs-password'])}`);
      if (node.clash.alpn) proxyLines.push(`    alpn: [${node.clash.alpn.map(yamlSafeQuote).join(', ')}]`);
      if (node.clash.network) proxyLines.push(`    network: ${node.clash.network}`);
      if (node.clash.tls !== undefined) proxyLines.push(`    tls: ${node.clash.tls}`);
      if (node.clash.flow) proxyLines.push(`    flow: ${node.clash.flow}`);
      if (node.clash['client-fingerprint']) proxyLines.push(`    client-fingerprint: ${node.clash['client-fingerprint']}`);

      if (node.clash.ip) proxyLines.push(`    ip: ${yamlSafeQuote(node.clash.ip)}`);
      if (node.clash['public-key']) proxyLines.push(`    public-key: ${yamlSafeQuote(node.clash['public-key'])}`);
      if (node.clash['private-key']) proxyLines.push(`    private-key: ${yamlSafeQuote(node.clash['private-key'])}`);
      if (node.clash.udp !== undefined) proxyLines.push(`    udp: ${node.clash.udp}`);
      if (node.clash['remote-dns-resolve'] !== undefined) proxyLines.push(`    remote-dns-resolve: ${node.clash['remote-dns-resolve']}`);
      if (node.clash.dns) proxyLines.push(`    dns: [${node.clash.dns.map(yamlSafeQuote).join(', ')}]`);
      if (node.clash.mtu) proxyLines.push(`    mtu: ${node.clash.mtu}`);
      if (node.clash['congestion-controller']) proxyLines.push(`    congestion-controller: ${yamlSafeQuote(node.clash['congestion-controller'])}`);

      if (node.clash['ws-opts']) {
        proxyLines.push(`    ws-opts:`);
        proxyLines.push(`      path: ${yamlSafeQuote(node.clash['ws-opts'].path)}`);
        if (node.clash['ws-opts'].headers) {
          proxyLines.push(`      headers:`);
          for (const [k, v] of Object.entries(node.clash['ws-opts'].headers)) {
            proxyLines.push(`        ${k}: ${yamlSafeQuote(v)}`);
          }
        }
      }

      if (node.clash['httpupgrade-opts']) {
        proxyLines.push(`    httpupgrade-opts:`);
        proxyLines.push(`      path: ${yamlSafeQuote(node.clash['httpupgrade-opts'].path)}`);
        proxyLines.push(`      host: ${yamlSafeQuote(node.clash['httpupgrade-opts'].host)}`);
      }

      if (node.clash['grpc-opts']) {
        proxyLines.push(`    grpc-opts:`);
        proxyLines.push(`      grpc-service-name: ${yamlSafeQuote(node.clash['grpc-opts']['grpc-service-name'])}`);
      }

      if (node.clash.cipher) proxyLines.push(`    cipher: ${node.clash.cipher}`);
      if (node.clash.version) proxyLines.push(`    version: ${node.clash.version}`);
    }

    const proxiesBlock = proxyLines.join('\n');
    const proxyListStr = proxyNames.map(name => `      - ${yamlSafeQuote(name)}`).join('\n');

    return `# Parham Confing - Clash Meta (Mihomo) Subscription
# Channel: Parham Confing (https://t.me/cynetx)
port: 7890
socks-port: 7891
allow-lan: true
mode: rule
log-level: info

proxies:
${proxiesBlock}

proxy-groups:
  - name: "🛡️ Parham Confing"
    type: select
    proxies:
      - "⚡ Auto Select"
${proxyListStr}

  - name: "⚡ Auto Select"
    type: url-test
    url: http://www.gstatic.com/generate_204
    interval: 300
    tolerance: 50
    proxies:
${proxyListStr}

rules:
  - MATCH,"🛡️ Parham Confing"
`;
  }

  buildSingBoxClientJson(nodes) {
    const outbounds = [];
    const proxyTags = [];

    for (const node of nodes) {
      if (node.singboxOutbound && Array.isArray(node.singboxOutbound)) {
        for (const ob of node.singboxOutbound) {
          outbounds.push(ob);
        }
        proxyTags.push(node.name);
      }
    }

    const allOutbounds = [];

    if (proxyTags.length > 0) {
      allOutbounds.push(
        {
          type: 'selector',
          tag: '🛡️ Parham Confing',
          outbounds: ['⚡ Auto Select', ...proxyTags]
        },
        {
          type: 'urltest',
          tag: '⚡ Auto Select',
          outbounds: [...proxyTags],
          url: 'http://www.gstatic.com/generate_204',
          interval: '5m'
        }
      );
    }

    allOutbounds.push(...outbounds);
    allOutbounds.push(
      { type: 'direct', tag: 'direct' },
      { type: 'block', tag: 'block' }
    );

    return JSON.stringify({
      log: { level: 'info' },
      outbounds: allOutbounds
    }, null, 2);
  }
}

const RENEW_PY = "import html as htmllib\nimport http.cookiejar\nimport json\nimport math\nimport os\nimport random\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport time\nimport urllib.error\nimport urllib.parse\nimport urllib.request\nfrom datetime import datetime, timezone\n\ntry:\n    from patchright.sync_api import TimeoutError as PlaywrightTimeout\n    from patchright.sync_api import sync_playwright\n    STEALTH = True\nexcept Exception:\n    from playwright.sync_api import TimeoutError as PlaywrightTimeout\n    from playwright.sync_api import sync_playwright\n    STEALTH = False\n\nEMAIL = (os.environ.get(\"KATABUMP_EMAIL\") or \"\").strip()\nPASSWORD = os.environ.get(\"KATABUMP_PASSWORD\") or \"\"\nSERVER_ID = (os.environ.get(\"SERVER_ID\") or \"\").strip()\nACCOUNT_PASSWORD = os.environ.get(\"KATABUMP_ACCOUNT_PASSWORD\") or \"\"\nCOOKIES_RAW = os.environ.get(\"KATABUMP_COOKIES\") or \"\"\n\n\ndef load_cookies():\n    out = []\n    try:\n        data = json.loads(COOKIES_RAW) if COOKIES_RAW.strip() else []\n    except Exception:\n        data = []\n    if not isinstance(data, list):\n        return out\n    for c in data:\n        try:\n            name = str(c.get(\"name\") or \"\").strip()\n            value = str(c.get(\"value\") if c.get(\"value\") is not None else \"\")\n            if not name:\n                continue\n            dom = str(c.get(\"domain\") or \"\").strip()\n            path = str(c.get(\"path\") or \"/\") or \"/\"\n            if dom:\n                out.append({\"name\": name, \"value\": value, \"domain\": dom, \"path\": path})\n            else:\n                out.append({\"name\": name, \"value\": value, \"url\": \"https://control.katabump.com\"})\n                out.append({\"name\": name, \"value\": value, \"url\": \"https://dashboard.katabump.com\"})\n        except Exception:\n            continue\n    return out\n\n\nCOOKIE_LIST = load_cookies()\nDASH = \"https://dashboard.katabump.com\"\n\nBASE = \"https://control.katabump.com\"\nLOGIN_PATH = \"/auth/login\"\nSTATE_FILE = \"katabump_state.json\"\nDASH_STATE = \"katabump_dash_state.json\"\nSTATUS_FILE = \"katabump_status.json\"\nEMAIL_RE = re.compile(r\"^[A-Za-z0-9._%+\\-]+@[A-Za-z0-9\\-]+(\\.[A-Za-z0-9\\-]+)*\\.[A-Za-z]{2,}$\")\n\nUA = (\"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 \"\n      \"(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36\")\nLAUNCH_ARGS = [\n    \"--disable-blink-features=AutomationControlled\",\n    \"--no-sandbox\",\n    \"--disable-dev-shm-usage\",\n    \"--window-size=1280,720\",\n]\n\nREJECT_HINTS = re.compile(\n    r\"invalid|incorrect|wrong|do not match|does not match|not match|no account|not found|\"\n    r\"credentials|unauthori[sz]ed|failed to log\",\n    re.I,\n)\nCF_MARKS = (\"just a moment\", \"attention required\", \"access denied\", \"you have been blocked\",\n            \"error 1020\", \"error 1015\", \"error 1010\", \"rate limited\", \"verify you are human\",\n            \"checking your browser\", \"enable javascript and cookies\")\n\nPRIORITY = [\"INVALID_CREDENTIALS\", \"CLOUDFLARE_BLOCK\", \"CAPTCHA_FAILED\", \"NO_SUBMIT\",\n            \"LOGIN_REJECTED_SILENTLY\", \"FORM_NOT_FOUND\", \"NETWORK_ERROR\", \"TIMEOUT\",\n            \"BROWSER_ERROR\", \"CAPTCHA_REQUIRED\"]\n\nDIAG = []\n\n\nclass MethodFail(Exception):\n    def __init__(self, code, detail, definitive=False):\n        super().__init__(detail)\n        self.code = code\n        self.detail = detail\n        self.definitive = definitive\n\n\ndef log(message):\n    stamp = datetime.now(timezone.utc).strftime(\"%Y-%m-%d %H:%M:%S UTC\")\n    print(\"[%s] %s\" % (stamp, message), flush=True)\n\n\ndef mask_email(value):\n    if \"@\" not in value:\n        return value[:2] + \"***\"\n    name, domain = value.split(\"@\", 1)\n    return \"%s***@%s\" % (name[:2], domain)\n\n\ndef clean(text, limit=300):\n    return re.sub(r\"\\s+\", \" \", str(text)).replace(\"%\", \"pct\").replace(\"|\", \"/\").strip()[:limit]\n\n\ndef write_summary(line):\n    path = os.environ.get(\"GITHUB_STEP_SUMMARY\")\n    if not path:\n        return\n    try:\n        with open(path, \"a\", encoding=\"utf-8\") as f:\n            f.write(line + \"\\n\")\n    except Exception:\n        pass\n\n\ndef report_auth(ok, code, reason):\n    payload = {\"ok\": ok, \"code\": code, \"reason\": reason,\n               \"checkedAt\": datetime.now(timezone.utc).isoformat()}\n    try:\n        with open(STATUS_FILE, \"w\", encoding=\"utf-8\") as f:\n            json.dump(payload, f)\n    except Exception:\n        pass\n    if ok:\n        print(\"::notice title=KB_AUTH::valid|OK|%s\" % clean(reason, 200), flush=True)\n        write_summary(\"Katabump login: VALID (%s)\" % clean(reason, 200))\n    else:\n        print(\"::error title=KB_AUTH::invalid|%s|%s\" % (code, clean(reason, 650)), flush=True)\n        write_summary(\"Katabump login: INVALID (%s) - %s\" % (code, clean(reason, 650)))\n\n\ndef validate_inputs():\n    if os.environ.get(\"WATCHDOG\"):\n        if (not PASSWORD or not PASSWORD.strip()) and not COOKIE_LIST:\n            return \"MISSING_PASSWORD\", \"KATABUMP_PASSWORD (server password) secret is empty or not defined\"\n        if not SERVER_ID:\n            return \"MISSING_SERVER_ID\", \"SERVER_ID secret is empty or not defined\"\n    else:\n        has_server = bool(SERVER_ID and PASSWORD.strip())\n        has_account = bool(EMAIL and EMAIL_RE.match(EMAIL) and ACCOUNT_PASSWORD.strip())\n        if not has_server and not has_account and not COOKIE_LIST:\n            return \"MISSING_PASSWORD\", \"SERVER_ID and KATABUMP_PASSWORD secrets are empty or not defined\"\n    if SERVER_ID and not re.match(r\"^[A-Za-z0-9_\\-]+$\", SERVER_ID):\n        return \"INVALID_SERVER_ID\", \"SERVER_ID contains unexpected characters\"\n    return None, None\n\n\ndef looks_blocked(text, title=\"\"):\n    blob = ((title or \"\") + \" \" + (text or \"\")).lower()\n    return any(m in blob for m in CF_MARKS)\n\n\nclass _Form:\n    def __init__(self, action, method, fields, user_field, pass_field):\n        self.action, self.method, self.fields = action, method, fields\n        self.user_field, self.pass_field = user_field, pass_field\n\n\ndef parse_login_form(page_html):\n    forms = re.findall(r\"<form\\b(.*?)>(.*?)</form>\", page_html, re.S | re.I)\n    for attrs, inner in forms:\n        if not re.search(r'type\\s*=\\s*[\"\\']?password', inner, re.I):\n            continue\n        action = (re.search(r'action\\s*=\\s*[\"\\']([^\"\\']*)', attrs, re.I) or [None, \"\"])[1]\n        method = ((re.search(r'method\\s*=\\s*[\"\\']?(\\w+)', attrs, re.I) or [None, \"post\"])[1]).lower()\n        fields, user_field, pass_field = {}, None, None\n        for tag in re.findall(r\"<input\\b[^>]*>\", inner, re.I):\n            name = (re.search(r'name\\s*=\\s*[\"\\']([^\"\\']+)', tag, re.I) or [None, None])[1]\n            typ = ((re.search(r'type\\s*=\\s*[\"\\']?(\\w+)', tag, re.I) or [None, \"text\"])[1]).lower()\n            val = htmllib.unescape((re.search(r'value\\s*=\\s*[\"\\']([^\"\\']*)', tag, re.I) or [None, \"\"])[1])\n            if not name:\n                continue\n            if typ == \"password\":\n                pass_field = name\n            elif typ in (\"text\", \"email\") and not user_field:\n                user_field = name\n            elif typ in (\"hidden\",):\n                fields[name] = val\n            elif typ in (\"checkbox\",) and re.search(r\"\\bchecked\\b\", tag, re.I):\n                fields[name] = val or \"on\"\n        if user_field and pass_field:\n            return _Form(htmllib.unescape(action), method, fields, user_field, pass_field)\n    return None\n\n\ndef page_errors(page_html):\n    found = []\n    for m in re.finditer(r'class\\s*=\\s*\"[^\"]*(?:alert|error|invalid-feedback|text-danger|text-red)[^\"]*\"[^>]*>(.*?)</', page_html, re.S | re.I):\n        text = clean(htmllib.unescape(re.sub(r\"<[^>]+>\", \" \", m.group(1))), 160)\n        if text and text not in found:\n            found.append(text)\n    return \" / \".join(found[:3])\n\n\ndef method_http():\n    jar = http.cookiejar.CookieJar()\n    handlers = [urllib.request.HTTPCookieProcessor(jar)]\n    opener = urllib.request.build_opener(*handlers)\n    headers = {\"User-Agent\": UA, \"Accept\": \"text/html,application/xhtml+xml,*/*;q=0.8\",\n               \"Accept-Language\": \"en-US,en;q=0.9\"}\n\n    def fetch(url, data=None, extra=None):\n        h = dict(headers)\n        h.update(extra or {})\n        req = urllib.request.Request(url, data=data, headers=h)\n        try:\n            r = opener.open(req, timeout=15)\n            return r.status, r.geturl(), r.read().decode(\"utf-8\", \"replace\")\n        except urllib.error.HTTPError as e:\n            return e.code, url, e.read().decode(\"utf-8\", \"replace\")\n        except Exception as e:\n            raise MethodFail(\"NETWORK_ERROR\", \"HTTP request failed: \" + clean(e, 120))\n\n    status, url, body = fetch(BASE + LOGIN_PATH)\n    log(\"HTTP method: GET login page -> HTTP %d\" % status)\n    if status in (403, 429, 503) or looks_blocked(body[:4000]):\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"login page answered HTTP %d (Cloudflare/IP block)\" % status)\n    if status >= 400:\n        raise MethodFail(\"NETWORK_ERROR\", \"login page answered HTTP %d\" % status)\n    form = parse_login_form(body)\n    if not form:\n        raise MethodFail(\"FORM_NOT_FOUND\", \"no login form in plain HTML (page is JS-rendered)\")\n    if re.search(r\"data-sitekey|cf-turnstile|g-recaptcha|h-captcha\", body, re.I):\n        raise MethodFail(\"CAPTCHA_REQUIRED\", \"form has a captcha, a real browser is needed\")\n\n    payload = dict(form.fields)\n    payload[form.user_field] = SERVER_ID\n    payload[form.pass_field] = PASSWORD\n    action = urllib.parse.urljoin(BASE + LOGIN_PATH, form.action or LOGIN_PATH)\n    log(\"HTTP method: submitting form (%s %s)\" % (form.method.upper(), urllib.parse.urlparse(action).path))\n    status, url, body = fetch(action, urllib.parse.urlencode(payload).encode(),\n                              {\"Content-Type\": \"application/x-www-form-urlencoded\",\n                               \"Origin\": BASE, \"Referer\": BASE + LOGIN_PATH})\n    log(\"HTTP method: POST -> HTTP %d, final URL %s\" % (status, urllib.parse.urlparse(url).path))\n    if status in (403, 429) or looks_blocked(body[:4000]):\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"login POST answered HTTP %d (blocked)\" % status)\n    if LOGIN_PATH in url:\n        err = page_errors(body)\n        if err and REJECT_HINTS.search(err):\n            raise MethodFail(\"INVALID_CREDENTIALS\", \"Katabump said: \" + err, definitive=True)\n        raise MethodFail(\"LOGIN_REJECTED_SILENTLY\", \"HTTP %d, stayed on login. %s\" % (status, err or \"no message\"))\n\n    status2, url2, _ = fetch(BASE + \"/server/\" + SERVER_ID)\n    if LOGIN_PATH in url2 or status2 >= 400:\n        raise MethodFail(\"LOGIN_REJECTED_SILENTLY\", \"logged in but session rejected on server page (HTTP %d)\" % status2)\n\n    cookies = []\n    for c in jar:\n        cookies.append({\"name\": c.name, \"value\": c.value, \"domain\": c.domain or \"control.katabump.com\",\n                        \"path\": c.path or \"/\", \"expires\": float(c.expires) if c.expires else -1,\n                        \"httpOnly\": False, \"secure\": bool(c.secure), \"sameSite\": \"Lax\"})\n    with open(STATE_FILE, \"w\", encoding=\"utf-8\") as f:\n        json.dump({\"cookies\": cookies, \"origins\": []}, f)\n    log(\"HTTP method: login OK, saved %d cookies.\" % len(cookies))\n    return \"chromium\"\n\n\ndef ensure_display():\n    if os.environ.get(\"DISPLAY\"):\n        return True\n    exe = shutil.which(\"Xvfb\")\n    if not exe:\n        return False\n    try:\n        subprocess.Popen([exe, \":99\", \"-screen\", \"0\", \"1280x720x24\", \"-nolisten\", \"tcp\"],\n                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n        time.sleep(2)\n        os.environ[\"DISPLAY\"] = \":99\"\n        return True\n    except Exception:\n        return False\n\n\ndef new_browser(p, engine):\n    headed = ensure_display()\n    kw = {\"headless\": not headed}\n    if engine == \"firefox\":\n        return p.firefox.launch(**kw)\n    if STEALTH:\n        for channel in (\"chrome\", \"chromium\", None):\n            try:\n                if channel:\n                    return p.chromium.launch(channel=channel, args=[\"--no-sandbox\", \"--window-size=1280,720\"], **kw)\n                return p.chromium.launch(args=[\"--no-sandbox\", \"--window-size=1280,720\"], **kw)\n            except Exception:\n                continue\n    try:\n        return p.chromium.launch(channel=\"chromium\", args=LAUNCH_ARGS, **kw)\n    except Exception:\n        return p.chromium.launch(args=LAUNCH_ARGS, **kw)\n\n\ndef new_context(browser, engine, state=None):\n    kwargs = dict(viewport={\"width\": 1280, \"height\": 720}, locale=\"en-US\", timezone_id=\"UTC\")\n    if engine == \"chromium\" and not STEALTH:\n        kwargs[\"user_agent\"] = UA\n    if state:\n        kwargs[\"storage_state\"] = state\n    ctx = browser.new_context(**kwargs)\n    if COOKIE_LIST:\n        try:\n            ctx.add_cookies(COOKIE_LIST)\n        except Exception:\n            pass\n    if engine == \"chromium\" and not STEALTH:\n        ctx.add_init_script(\"Object.defineProperty(navigator, 'webdriver', {get: () => undefined});\")\n    return ctx\n\n\nclass Mouse:\n    def __init__(self, page, cdp):\n        self.page, self.cdp = page, cdp\n        self.pos = (random.uniform(100, 300), random.uniform(100, 300))\n\n    def _dispatch(self, kind, x, y, button=\"none\", clicks=0):\n        self.cdp.send(\"Input.dispatchMouseEvent\", {\"type\": kind, \"x\": float(x), \"y\": float(y),\n                                                    \"button\": button, \"clickCount\": clicks})\n\n    def move(self, x1, y1):\n        x0, y0 = self.pos\n        steps = max(12, min(45, int(math.hypot(x1 - x0, y1 - y0) / 12)))\n        cx = (x0 + x1) / 2 + random.uniform(-40, 40)\n        cy = (y0 + y1) / 2 + random.uniform(-25, 25)\n        for i in range(1, steps + 1):\n            t = i / steps\n            e = t * t * (3 - 2 * t)\n            x = (1 - e) ** 2 * x0 + 2 * (1 - e) * e * cx + e ** 2 * x1 + random.uniform(-0.6, 0.6)\n            y = (1 - e) ** 2 * y0 + 2 * (1 - e) * e * cy + e ** 2 * y1 + random.uniform(-0.6, 0.6)\n            if self.cdp:\n                self._dispatch(\"mouseMoved\", x, y)\n            else:\n                self.page.mouse.move(x, y)\n            time.sleep(random.uniform(0.008, 0.024))\n        self.pos = (x1, y1)\n\n    def click(self, x, y):\n        self.move(x, y)\n        time.sleep(random.uniform(0.08, 0.2))\n        if self.cdp:\n            self._dispatch(\"mousePressed\", x, y, \"left\", 1)\n            time.sleep(random.uniform(0.05, 0.12))\n            self._dispatch(\"mouseReleased\", x, y, \"left\", 1)\n        else:\n            self.page.mouse.down()\n            time.sleep(random.uniform(0.05, 0.12))\n            self.page.mouse.up()\n\n\nTS_SELECTORS = [\n    'iframe[src*=\"challenges.cloudflare.com\"]', 'iframe[src*=\"turnstile\"]',\n    'iframe[title*=\"Cloudflare\"]', 'iframe[title*=\"Widget containing\"]',\n    '[id^=\"cf-chl-widget\"]', \".cf-turnstile\", \"[data-sitekey]\",\n]\n\n\ndef turnstile_frame_present(page):\n    try:\n        for fr in page.frames:\n            if \"challenges.cloudflare.com\" in (fr.url or \"\") or \"turnstile\" in (fr.url or \"\"):\n                return True\n    except Exception:\n        pass\n    return False\n\n\ndef turnstile_box(page):\n    for sel in TS_SELECTORS:\n        loc = page.locator(sel).first\n        try:\n            if loc.count() > 0:\n                loc.scroll_into_view_if_needed(timeout=3000)\n                box = loc.bounding_box()\n                if box and box[\"width\"] > 20 and box[\"height\"] > 20:\n                    return box\n        except Exception:\n            continue\n    return None\n\n\ndef turnstile_token(page):\n    try:\n        return page.evaluate(\"\"\"() => {\n            const el = document.querySelector('input[name=\"cf-turnstile-response\"], input[name=\"cf-chl-widget-response\"]');\n            return el ? el.value : null; }\"\"\")\n    except Exception:\n        return None\n\n\ndef wait_token(page, seconds):\n    end = time.time() + seconds\n    while time.time() < end:\n        if turnstile_token(page):\n            return True\n        page.wait_for_timeout(500)\n    return bool(turnstile_token(page))\n\n\ndef solve_turnstile(page, mouse):\n    deadline = time.time() + 10\n    box = None\n    while time.time() < deadline:\n        box = turnstile_box(page)\n        if box or turnstile_token(page) is not None or turnstile_frame_present(page):\n            break\n        page.wait_for_timeout(500)\n    present = bool(box) or turnstile_token(page) is not None or turnstile_frame_present(page)\n    if not present:\n        log(\"No Cloudflare Turnstile widget detected on the page.\")\n        return True\n    if wait_token(page, 25):\n        log(\"Turnstile solved automatically.\")\n        return True\n    for attempt in range(1, 4):\n        box = turnstile_box(page) or box\n        if not box:\n            if wait_token(page, 4):\n                return True\n            continue\n        tx = box[\"x\"] + min(30.0, box[\"width\"] * 0.12) + random.uniform(-3, 3)\n        ty = box[\"y\"] + box[\"height\"] / 2 + random.uniform(-3, 3)\n        log(\"Turnstile click attempt %d/3 at (%d, %d).\" % (attempt, tx, ty))\n        mouse.click(tx, ty)\n        if wait_token(page, 8):\n            log(\"Turnstile solved.\")\n            return True\n    return False\n\n\ndef body_text(page, limit=200):\n    try:\n        return clean(page.evaluate(\"() => (document.body && document.body.innerText) || ''\"), limit)\n    except Exception:\n        return \"\"\n\n\ndef read_page_error(page):\n    found = []\n    for sel in ['[role=\"alert\"]', \".alert-danger\", \".alert-error\", \".alert\", \".error\",\n                \".invalid-feedback\", \".text-danger\", \".text-red-500\", \".toast\", \".notification\"]:\n        try:\n            items = page.locator(sel)\n            for i in range(min(items.count(), 4)):\n                t = (items.nth(i).inner_text(timeout=1500) or \"\").strip()\n                if t and t not in found:\n                    found.append(t)\n        except Exception:\n            continue\n    return clean(\" / \".join(found), 200) if found else \"\"\n\n\ndef save_debug(page, name):\n    try:\n        page.screenshot(path=\"debug-%s.png\" % name, full_page=True)\n    except Exception:\n        pass\n    try:\n        with open(\"debug-%s.html\" % name, \"w\", encoding=\"utf-8\") as f:\n            f.write(page.content()[:400000])\n    except Exception:\n        pass\n\n\ndef pick_inputs(page):\n    pass_loc = page.locator('input[type=\"password\"]:visible').first\n    form = pass_loc.locator(\"xpath=ancestor::form[1]\")\n    scope = form if form.count() > 0 else page\n    candidates = scope.locator('input[name=\"username\"]:visible, input[name=\"email\"]:visible, input[name=\"id\"]:visible, input[type=\"email\"]:visible, input[type=\"text\"]:visible')\n    user_loc = candidates.first\n    return user_loc, pass_loc, form\n\n\ndef set_value(page, loc, value):\n    for mode in (\"type\", \"fill\", \"type\"):\n        try:\n            loc.click()\n            loc.fill(\"\")\n            if mode == \"type\":\n                loc.type(value, delay=random.randint(8, 20))\n            else:\n                loc.fill(value)\n            page.wait_for_timeout(150)\n            if loc.input_value() == value:\n                return True\n        except Exception:\n            pass\n        page.wait_for_timeout(400)\n    return False\n\n\ndef attempt_login(page, mouse, tag, post, number, ident):\n    post[\"status\"] = None\n    post[\"body\"] = \"\"\n    log(\"Opening the Katabump login page (attempt %d)...\" % number)\n    resp = page.goto(BASE + LOGIN_PATH, wait_until=\"domcontentloaded\", timeout=30000)\n    if resp is not None and resp.status in (403, 429, 503):\n        save_debug(page, tag + \"-blocked\")\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"login page answered HTTP %d\" % resp.status)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=10000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(1500)\n    try:\n        title = page.title()\n    except Exception:\n        title = \"\"\n    if looks_blocked(body_text(page, 600), title):\n        save_debug(page, tag + \"-blocked\")\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"Cloudflare challenge/block page: \" + body_text(page, 90))\n    if LOGIN_PATH not in page.url:\n        log(\"Already authenticated. URL: \" + page.url)\n        return True\n\n    try:\n        page.locator('input[type=\"password\"]').first.wait_for(state=\"visible\", timeout=10000)\n    except PlaywrightTimeout:\n        save_debug(page, tag + \"-noform\")\n        raise MethodFail(\"FORM_NOT_FOUND\", \"login form never appeared. Page: \" + body_text(page, 90))\n    page.wait_for_timeout(1500)\n\n    user_input, pass_input, form = pick_inputs(page)\n    log(\"Filling credentials for %s...\" % mask_email(ident))\n    if not set_value(page, user_input, ident):\n        save_debug(page, tag + \"-fill\")\n        raise MethodFail(\"NO_SUBMIT\", \"could not type the ID/email into the login field\")\n    page.wait_for_timeout(random.randint(100, 250))\n    if not set_value(page, pass_input, PASSWORD):\n        save_debug(page, tag + \"-fill\")\n        raise MethodFail(\"NO_SUBMIT\", \"could not type the password into the login field\")\n    page.wait_for_timeout(random.randint(150, 350))\n\n    if not solve_turnstile(page, mouse):\n        save_debug(page, tag + \"-captcha\")\n        raise MethodFail(\"CAPTCHA_FAILED\", \"Turnstile token not received after 3 clicks\")\n\n    try:\n        if user_input.input_value() != ident or pass_input.input_value() != PASSWORD:\n            set_value(page, user_input, ident)\n            set_value(page, pass_input, PASSWORD)\n    except Exception:\n        pass\n\n    submit = form.locator('button[type=\"submit\"], input[type=\"submit\"], button:not([type])').first\n    try:\n        if form.count() == 0 or submit.count() == 0:\n            submit = page.locator('button[type=\"submit\"], input[type=\"submit\"]').first\n    except Exception:\n        submit = page.locator('button[type=\"submit\"], input[type=\"submit\"]').first\n    box = None\n    try:\n        box = submit.bounding_box()\n    except Exception:\n        pass\n    log(\"Submitting login form...\")\n    if box:\n        mouse.click(box[\"x\"] + box[\"width\"] / 2 + random.uniform(-4, 4),\n                    box[\"y\"] + box[\"height\"] / 2 + random.uniform(-2, 2))\n    else:\n        submit.click()\n    try:\n        page.wait_for_url(lambda u: LOGIN_PATH not in u, timeout=8000)\n    except PlaywrightTimeout:\n        if post[\"status\"] is None:\n            log(\"No POST sent by the click, pressing Enter as fallback.\")\n            try:\n                pass_input.press(\"Enter\")\n            except Exception:\n                pass\n        if post[\"status\"] is None or post[\"status\"] < 400:\n            try:\n                page.wait_for_url(lambda u: LOGIN_PATH not in u, timeout=7000)\n            except PlaywrightTimeout:\n                pass\n    page.wait_for_timeout(800)\n    log(\"Post-login URL: \" + page.url)\n    if LOGIN_PATH not in page.url:\n        return True\n\n    save_debug(page, tag + \"-failed-%d\" % number)\n    err = read_page_error(page)\n    if err and REJECT_HINTS.search(err):\n        raise MethodFail(\"INVALID_CREDENTIALS\", \"Katabump said: \" + err, definitive=True)\n    st = post[\"status\"]\n    hint = body_text(page, 110)\n    if st in (403, 429) or looks_blocked(hint):\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"POST answered HTTP %s. %s\" % (st, hint))\n    if st is None:\n        raise MethodFail(\"NO_SUBMIT\", \"the form never sent a POST request. %s\" % (err or hint))\n    token = turnstile_token(page)\n    if token is not None and not token:\n        raise MethodFail(\"CAPTCHA_FAILED\", \"POST HTTP %s but captcha token was empty\" % st)\n    reply = post[\"body\"]\n    if reply and re.search(r\"no account|could not be found|credentials\", reply, re.I):\n        raise MethodFail(\"NO_ACCOUNT\", \"Katabump said: no account matches these credentials (%s)\" % mask_email(ident))\n    extra = err or hint\n    if reply and extra and reply in extra:\n        extra = \"\"\n    raise MethodFail(\"LOGIN_REJECTED_SILENTLY\", \"POST HTTP %s, stayed on login. %s %s\" % (st, reply, extra))\n\n\ndef browser_login(page, mouse, tag):\n    post = {\"status\": None, \"body\": \"\"}\n\n    def on_response(resp):\n        try:\n            if resp.request.method == \"POST\" and BASE in resp.url:\n                post[\"status\"] = resp.status\n                log(\"POST %s -> HTTP %d\" % (resp.url.replace(BASE, \"\"), resp.status))\n                if resp.status >= 400:\n                    try:\n                        post[\"body\"] = clean(resp.text(), 160)\n                        log(\"POST reply: \" + post[\"body\"])\n                    except Exception:\n                        pass\n        except Exception:\n            pass\n\n    page.on(\"response\", on_response)\n    idents = [SERVER_ID]\n    last = None\n    for ident in idents:\n        for number in range(1, 4):\n            try:\n                attempt_login(page, mouse, tag, post, number, ident)\n                return\n            except MethodFail as e:\n                last = e\n                if e.definitive or e.code in (\"CLOUDFLARE_BLOCK\", \"FORM_NOT_FOUND\"):\n                    raise\n                log(\"Attempt %d failed: %s (%s)\" % (number, e.code, e.detail))\n                if e.code == \"NO_ACCOUNT\":\n                    break\n                if number < 3:\n                    try:\n                        page.context.clear_cookies()\n                    except Exception:\n                        pass\n                    page.wait_for_timeout(random.randint(3000, 5000))\n        if last is not None and last.code != \"NO_ACCOUNT\":\n            raise last\n    if last is not None and last.code == \"NO_ACCOUNT\":\n        raise MethodFail(\"INVALID_CREDENTIALS\", \"Katabump says no account matches this server ID and password. Check the server ID (SERVER_ID) and the server password (KATABUMP_PASSWORD).\", definitive=True)\n    raise last\n\n\ndef method_browser(p, engine, tag):\n    browser = None\n    try:\n        browser = new_browser(p, engine)\n    except Exception as e:\n        raise MethodFail(\"BROWSER_ERROR\", \"%s failed to start: %s\" % (engine, clean(e, 120)))\n    try:\n        ctx = new_context(browser, engine)\n        page = ctx.new_page()\n        cdp = ctx.new_cdp_session(page) if engine == \"chromium\" else None\n        mouse = Mouse(page, cdp)\n        try:\n            browser_login(page, mouse, tag)\n            ctx.storage_state(path=STATE_FILE)\n            log(\"Login successful. Saved %d cookies.\" % len(ctx.cookies()))\n            return engine\n        except PlaywrightTimeout as e:\n            save_debug(page, tag + \"-timeout\")\n            raise MethodFail(\"TIMEOUT\", \"timeout: \" + clean(e, 120))\n        except MethodFail:\n            raise\n        except Exception as e:\n            save_debug(page, tag + \"-error\")\n            raise MethodFail(\"BROWSER_ERROR\", \"unexpected: \" + clean(e, 120))\n    finally:\n        try:\n            browser.close()\n        except Exception:\n            pass\n\n\nRENEW_RE = re.compile(r\"renew|extend|add\\s*time|prolong\", re.I)\nCONFIRM_RE = re.compile(r\"^\\s*(confirm|yes|ok|continue|submit|proceed)\\b\", re.I)\nACTION_SEL = 'button, a, input[type=\"submit\"], input[type=\"button\"], [role=\"button\"]'\n\n\ndef visible_actions(page):\n    names = []\n    try:\n        items = page.locator(ACTION_SEL)\n        for i in range(min(items.count(), 80)):\n            item = items.nth(i)\n            try:\n                if not item.is_visible():\n                    continue\n                label = clean(item.inner_text(timeout=800) or item.get_attribute(\"value\") or \"\", 40)\n                if label:\n                    names.append(label)\n            except Exception:\n                continue\n    except Exception:\n        pass\n    return names\n\n\ndef open_server_page(page):\n    log(\"Renewal step: opening the dashboard...\")\n    page.goto(BASE + \"/\", wait_until=\"domcontentloaded\", timeout=30000)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=8000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(1500)\n    if LOGIN_PATH in page.url:\n        raise RuntimeError(\"Saved session was rejected (redirected to /auth/login)\")\n    link = page.locator('a[href*=\"/server/%s\"]' % SERVER_ID).first\n    try:\n        if link.count() > 0:\n            link.scroll_into_view_if_needed(timeout=3000)\n            log(\"Clicking the server link on the dashboard.\")\n            link.click(timeout=5000)\n            page.wait_for_load_state(\"domcontentloaded\", timeout=15000)\n        else:\n            manage = page.locator(ACTION_SEL).filter(has_text=re.compile(r\"manage\\s*server|manage|see\\s*server|open\", re.I)).first\n            if manage.count() > 0 and manage.is_visible():\n                log(\"Clicking the Manage Server button.\")\n                manage.click(timeout=5000)\n                page.wait_for_load_state(\"domcontentloaded\", timeout=15000)\n    except Exception:\n        pass\n    page.wait_for_timeout(1500)\n    if SERVER_ID not in page.url:\n        log(\"Opening the server page directly.\")\n        page.goto(BASE + \"/server/\" + SERVER_ID, wait_until=\"domcontentloaded\", timeout=30000)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=8000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(2000)\n    if LOGIN_PATH in page.url:\n        raise RuntimeError(\"Saved session was rejected (redirected to /auth/login)\")\n\n\nSTART_RE = re.compile(r\"^\\s*start\\b\", re.I)\n\n\ndef find_start(page):\n    items = page.locator(ACTION_SEL).filter(has_text=START_RE)\n    for i in range(items.count()):\n        item = items.nth(i)\n        try:\n            if item.is_visible():\n                cls = item.get_attribute(\"class\") or \"\"\n                if item.get_attribute(\"disabled\") is not None or \"disabled\" in cls:\n                    continue\n                return item\n        except Exception:\n            continue\n    return None\n\n\ndef ensure_running(page):\n    btn = find_start(page)\n    if btn is None:\n        for label in (\"Console\", \"Overview\", \"Power\"):\n            tab = page.locator('a, button, [role=\"tab\"]').filter(has_text=re.compile(r\"^\\s*\" + label, re.I)).first\n            try:\n                if tab.count() > 0 and tab.is_visible():\n                    tab.click(timeout=4000)\n                    page.wait_for_timeout(1800)\n                    btn = find_start(page)\n                    if btn is not None:\n                        break\n            except Exception:\n                continue\n    if btn is None:\n        log(\"Power check: no Start button available, the server is already running.\")\n        return False\n    log(\"Power check: the server is offline, clicking Start.\")\n    try:\n        btn.scroll_into_view_if_needed(timeout=3000)\n        btn.click(timeout=6000)\n    except Exception as e:\n        save_debug(page, \"start\")\n        raise RuntimeError(\"Start button could not be clicked: \" + clean(e, 100))\n    page.wait_for_timeout(6000)\n    save_debug(page, \"start-after\")\n    log(\"RESULT: the server was offline and Start was clicked.\")\n    write_summary(\"Katabump server %s: was offline, Start clicked\" % SERVER_ID)\n    return True\n\n\ndef find_renew(page):\n    items = page.locator(ACTION_SEL).filter(has_text=RENEW_RE)\n    for i in range(items.count()):\n        item = items.nth(i)\n        try:\n            if item.is_visible():\n                disabled = item.get_attribute(\"disabled\")\n                cls = item.get_attribute(\"class\") or \"\"\n                if disabled is not None or \"disabled\" in cls:\n                    continue\n                return item\n        except Exception:\n            continue\n    return None\n\n\ndef open_direct(page):\n    log(\"Renewal step: opening the server page directly...\")\n    page.goto(BASE + \"/server/\" + SERVER_ID, wait_until=\"domcontentloaded\", timeout=60000)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=10000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(4000)\n    if LOGIN_PATH in page.url:\n        raise RuntimeError(\"Saved session was rejected (redirected to /auth/login)\")\n\n\ndef renew(p, engine):\n    if not os.path.exists(STATE_FILE):\n        raise RuntimeError(\"Saved session file is missing; cannot start the renewal step\")\n    browser = new_browser(p, engine)\n    context = new_context(browser, engine, STATE_FILE)\n    page = context.new_page()\n    try:\n        open_direct(page)\n        log(\"Server page: \" + page.url)\n        try:\n            ensure_running(page)\n        except Exception as e:\n            log(\"Power check failed: \" + clean(e))\n        btn = find_renew(page)\n        if btn is None:\n            log(\"Renew not on the direct page, trying through the dashboard...\")\n            open_server_page(page)\n            btn = find_renew(page)\n        if btn is None:\n            for label in (\"Manage\", \"Settings\", \"Billing\", \"Overview\"):\n                tab = page.locator('a, button, [role=\"tab\"]').filter(has_text=re.compile(r\"^\\s*\" + label, re.I)).first\n                try:\n                    if tab.count() > 0 and tab.is_visible():\n                        tab.click(timeout=4000)\n                        page.wait_for_timeout(1800)\n                        btn = find_renew(page)\n                        if btn is not None:\n                            break\n                except Exception:\n                    continue\n        if btn is None:\n            save_debug(page, \"renew\")\n            options = \" | \".join(visible_actions(page)[:40])\n            log(\"Options visible on the page: \" + options)\n            report_renew(\"missing\", \"Renew option is not on the page yet. Options: \" + options)\n            log(\"RESULT: not needed - the Renew button is not available right now.\")\n            write_summary(\"Katabump server %s: no renewal needed\" % SERVER_ID)\n            return\n        label_found = clean(btn.inner_text(timeout=1500), 40)\n        log(\"Renew option found: \" + label_found)\n        report_renew(\"seen\", \"Renew option is visible (%s)\" % label_found)\n        btn.scroll_into_view_if_needed(timeout=3000)\n        btn.click(timeout=6000)\n        page.wait_for_timeout(2000)\n        confirm = page.locator('.modal button, [role=\"dialog\"] button, .swal2-confirm, .bootbox button, button, input[type=\"submit\"]').filter(has_text=CONFIRM_RE)\n        for i in range(confirm.count()):\n            c = confirm.nth(i)\n            try:\n                if c.is_visible() and c.is_enabled():\n                    log(\"Confirming: \" + clean(c.inner_text(timeout=1000), 30))\n                    c.click(timeout=5000)\n                    page.wait_for_timeout(2500)\n                    break\n            except Exception:\n                continue\n        save_debug(page, \"renew-after\")\n        report_renew(\"clicked\", \"Renew option was seen and clicked (%s)\" % label_found)\n        log(\"RESULT: renewed - the Renew button was clicked successfully.\")\n        write_summary(\"Katabump server %s: renewed\" % SERVER_ID)\n    except Exception:\n        save_debug(page, \"renew\")\n        raise\n    finally:\n        browser.close()\n\n\ndef watchdog(p, engine):\n    if not os.path.exists(STATE_FILE):\n        raise RuntimeError(\"Saved session file is missing; cannot start the power check\")\n    browser = new_browser(p, engine)\n    context = new_context(browser, engine, STATE_FILE)\n    page = context.new_page()\n    try:\n        open_server_page(page)\n        log(\"Server page: \" + page.url)\n        if not ensure_running(page):\n            write_summary(\"Katabump server %s: running, nothing to do\" % SERVER_ID)\n    except Exception:\n        save_debug(page, \"watchdog\")\n        raise\n    finally:\n        browser.close()\n\n\ndef pick_code():\n    codes = [d[1] for d in DIAG]\n    real = [c for c in codes if c != \"CAPTCHA_REQUIRED\"] or codes\n    for c in PRIORITY:\n        if c in real:\n            return c\n    return \"LOGIN_FAILED\"\n\n\ndef report_renew(state, detail):\n    print(\"::notice title=KB_RENEW::%s|%s\" % (state, clean(detail, 200)), flush=True)\n    write_summary(\"Katabump Renew: %s - %s\" % (state, clean(detail, 200)))\n\n\ndef dash_login(page, mouse, tag):\n    log(\"Opening the Katabump dashboard...\")\n    resp = page.goto(DASH + \"/dashboard\", wait_until=\"domcontentloaded\", timeout=30000)\n    if resp is not None and resp.status in (403, 429, 503):\n        save_debug(page, tag + \"-blocked\")\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"dashboard answered HTTP %d\" % resp.status)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=10000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(2000)\n    try:\n        title = page.title()\n    except Exception:\n        title = \"\"\n    if looks_blocked(body_text(page, 600), title):\n        save_debug(page, tag + \"-blocked\")\n        raise MethodFail(\"CLOUDFLARE_BLOCK\", \"Cloudflare challenge/block page: \" + body_text(page, 90))\n\n    if page.locator('input[type=\"password\"]:visible').count() == 0:\n        link = page.locator('a, button').filter(has_text=re.compile(r\"^\\s*(log\\s?in|sign\\s?in)\", re.I)).first\n        try:\n            if link.count() > 0 and link.is_visible():\n                link.click(timeout=5000)\n                page.wait_for_timeout(2500)\n        except Exception:\n            pass\n    if page.locator('input[type=\"password\"]:visible').count() == 0:\n        if re.search(r\"login|signin|sign-in|auth\", page.url, re.I):\n            save_debug(page, tag + \"-noform\")\n            raise MethodFail(\"FORM_NOT_FOUND\", \"dashboard login form never appeared. Page: \" + body_text(page, 90))\n        log(\"Dashboard is already open without a login form. URL: \" + page.url)\n        return\n\n    user_input, pass_input, form = pick_inputs(page)\n    log(\"Filling dashboard credentials for %s...\" % mask_email(EMAIL))\n    if not set_value(page, user_input, EMAIL):\n        save_debug(page, tag + \"-fill\")\n        raise MethodFail(\"NO_SUBMIT\", \"could not type the email into the dashboard login field\")\n    page.wait_for_timeout(random.randint(100, 250))\n    if not set_value(page, pass_input, ACCOUNT_PASSWORD):\n        save_debug(page, tag + \"-fill\")\n        raise MethodFail(\"NO_SUBMIT\", \"could not type the password into the dashboard login field\")\n    page.wait_for_timeout(random.randint(150, 350))\n    if not solve_turnstile(page, mouse):\n        save_debug(page, tag + \"-captcha\")\n        raise MethodFail(\"CAPTCHA_FAILED\", \"Turnstile token not received after 3 clicks\")\n\n    submit = form.locator('button[type=\"submit\"], input[type=\"submit\"], button:not([type])').first\n    try:\n        if form.count() == 0 or submit.count() == 0:\n            submit = page.locator('button[type=\"submit\"], input[type=\"submit\"]').first\n    except Exception:\n        submit = page.locator('button[type=\"submit\"], input[type=\"submit\"]').first\n    log(\"Submitting the dashboard login form...\")\n    try:\n        submit.click(timeout=6000)\n    except Exception:\n        pass_input.press(\"Enter\")\n    try:\n        page.wait_for_function(\"() => !document.querySelector('input[type=password]') || document.querySelector('input[type=password]').offsetParent === null\", timeout=15000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(2000)\n    if page.locator('input[type=\"password\"]:visible').count() > 0:\n        save_debug(page, tag + \"-failed\")\n        err = read_page_error(page) or body_text(page, 140)\n        if REJECT_HINTS.search(err):\n            raise MethodFail(\"INVALID_CREDENTIALS\", \"Katabump said: \" + err, definitive=True)\n        raise MethodFail(\"LOGIN_REJECTED_SILENTLY\", \"dashboard stayed on login. \" + err)\n    log(\"Dashboard login OK. URL: \" + page.url)\n\n\ndef renew_candidates(page):\n    found = []\n    items = page.locator(ACTION_SEL).filter(has_text=RENEW_RE)\n    for i in range(items.count()):\n        item = items.nth(i)\n        try:\n            if not item.is_visible():\n                continue\n            cls = item.get_attribute(\"class\") or \"\"\n            if item.get_attribute(\"disabled\") is not None or \"disabled\" in cls:\n                continue\n            found.append(item)\n        except Exception:\n            continue\n    return found\n\n\ndef pick_for_server(found):\n    if len(found) <= 1 or not SERVER_ID:\n        return found[0] if found else None\n    for item in found:\n        try:\n            hit = item.evaluate(\"(el, id) => { let n = el; for (let i = 0; i < 7 && n; i++) { n = n.parentElement; if (n && n.innerText && n.innerText.length < 2500 && n.innerText.indexOf(id) >= 0) return true; } return false; }\", SERVER_ID)\n            if hit:\n                return item\n        except Exception:\n            continue\n    return found[0]\n\n\ndef dash_renew(page):\n    if \"/dashboard\" not in page.url:\n        page.goto(DASH + \"/dashboard\", wait_until=\"domcontentloaded\", timeout=30000)\n    try:\n        page.wait_for_load_state(\"networkidle\", timeout=10000)\n    except PlaywrightTimeout:\n        pass\n    page.wait_for_timeout(2500)\n    log(\"Dashboard page: \" + page.url)\n    found = renew_candidates(page)\n    if not found:\n        entry = page.locator('a, button').filter(has_text=re.compile(r\"manage|see|view|open|details\", re.I))\n        for i in range(min(entry.count(), 6)):\n            try:\n                el = entry.nth(i)\n                if not el.is_visible():\n                    continue\n                log(\"Opening: \" + clean(el.inner_text(timeout=1000), 40))\n                el.click(timeout=5000)\n                page.wait_for_timeout(3000)\n                found = renew_candidates(page)\n                if found:\n                    break\n                page.goto(DASH + \"/dashboard\", wait_until=\"domcontentloaded\", timeout=30000)\n                page.wait_for_timeout(2000)\n            except Exception:\n                continue\n    if not found:\n        options = \" | \".join(visible_actions(page)[:30])\n        save_debug(page, \"dash-norenew\")\n        log(\"Options visible on the page: \" + options)\n        report_renew(\"missing\", \"Renew option is not on the dashboard yet. Options: \" + options)\n        log(\"RESULT: the Renew option is not available right now.\")\n        return\n    btn = pick_for_server(found)\n    label = clean(btn.inner_text(timeout=1500), 40)\n    log(\"Renew option found: \" + label)\n    report_renew(\"seen\", \"Renew option is visible (%s)\" % label)\n    btn.scroll_into_view_if_needed(timeout=3000)\n    btn.click(timeout=6000)\n    page.wait_for_timeout(2500)\n    confirm = page.locator('.modal button, [role=\"dialog\"] button, .swal2-confirm, .bootbox button, button, input[type=\"submit\"]').filter(has_text=CONFIRM_RE)\n    for i in range(confirm.count()):\n        c = confirm.nth(i)\n        try:\n            if c.is_visible() and c.is_enabled():\n                log(\"Confirming: \" + clean(c.inner_text(timeout=1000), 30))\n                c.click(timeout=5000)\n                page.wait_for_timeout(3000)\n                break\n        except Exception:\n            continue\n    save_debug(page, \"dash-renew-after\")\n    report_renew(\"clicked\", \"Renew option was seen and clicked (%s)\" % label)\n    log(\"RESULT: renewed - the Renew button was clicked successfully.\")\n    write_summary(\"Katabump server %s: renewed\" % SERVER_ID)\n\n\ndef dashboard_main(p):\n    last = None\n    plan = [(\"chromium\", \"dash-chromium-1\"), (\"chromium\", \"dash-chromium-2\")]\n    if not STEALTH:\n        plan.append((\"firefox\", \"dash-firefox\"))\n    for engine, tag in plan:\n        browser = None\n        page = None\n        try:\n            browser = new_browser(p, engine)\n            ctx = new_context(browser, engine, DASH_STATE if os.path.exists(DASH_STATE) and \"-2\" not in tag else None)\n            page = ctx.new_page()\n            cdp = ctx.new_cdp_session(page) if engine == \"chromium\" else None\n            mouse = Mouse(page, cdp)\n            log(\"=== Dashboard login: %s ===\" % tag)\n            dash_login(page, mouse, tag)\n            try:\n                ctx.storage_state(path=DASH_STATE)\n            except Exception:\n                pass\n        except MethodFail as e:\n            last = e\n            DIAG.append((tag, e.code, e.detail))\n            log(\"Dashboard method %s failed: %s (%s)\" % (tag, e.code, e.detail))\n            if e.definitive:\n                report_auth(False, e.code, \"%s: %s\" % (tag, e.detail))\n                sys.exit(2)\n            continue\n        except Exception as e:\n            last = MethodFail(\"BROWSER_ERROR\", clean(e, 120))\n            DIAG.append((tag, \"BROWSER_ERROR\", clean(e, 100)))\n            log(\"Dashboard method %s crashed: %s\" % (tag, clean(e)))\n            continue\n        else:\n            report_auth(True, \"OK\", \"Dashboard login via \" + tag)\n            try:\n                dash_renew(page)\n            except Exception as e:\n                save_debug(page, \"dash-renew\")\n                report_renew(\"error\", clean(e, 160))\n                log(\"RESULT: renewal failed - \" + clean(e))\n                write_summary(\"Katabump server %s: renewal FAILED (%s)\" % (SERVER_ID, clean(e, 120)))\n                sys.exit(1)\n            return\n        finally:\n            if browser is not None:\n                try:\n                    browser.close()\n                except Exception:\n                    pass\n    final = pick_code()\n    summary = \"; \".join(\"%s=%s (%s)\" % (t, c, clean(d, 95)) for t, c, d in DIAG)\n    log(\"RESULT: dashboard login failed. Main cause: %s\" % final)\n    log(\"Details: \" + summary)\n    report_auth(False, final, summary)\n    sys.exit(1)\n\n\ndef control_main(p, power_only, can_fallback=False):\n    plan = [(\"http\", \"http\"), (\"chromium\", \"chromium-1\"), (\"firefox\", \"firefox-1\")]\n    engine_ok = None\n    used = None\n    del DIAG[:]\n    for i, (kind, tag) in enumerate(plan):\n        log(\"=== Server login method %d/%d: %s ===\" % (i + 1, len(plan), tag))\n        try:\n            engine_ok = method_http() if kind == \"http\" else method_browser(p, kind, tag)\n            used = tag\n            break\n        except MethodFail as e:\n            log(\"Method %s failed: %s (%s)\" % (tag, e.code, e.detail))\n            DIAG.append((tag, e.code, e.detail))\n            if e.definitive:\n                log(\"Server credentials were rejected, stopping so the account is not locked.\")\n                if can_fallback:\n                    return False\n                report_auth(False, e.code, \"%s: %s\" % (tag, e.detail))\n                sys.exit(2)\n        except Exception as e:\n            log(\"Method %s crashed: %s\" % (tag, clean(e)))\n            DIAG.append((tag, \"BROWSER_ERROR\", clean(e, 100)))\n        if i < len(plan) - 1:\n            time.sleep(1)\n    if not used:\n        summary = \"; \".join(\"%s=%s (%s)\" % (t, c, clean(d, 95)) for t, c, d in DIAG)\n        log(\"RESULT: server login failed. Details: \" + summary)\n        if can_fallback:\n            return False\n        report_auth(False, pick_code(), summary)\n        sys.exit(1)\n    log(\"Server login OK using method: \" + used)\n    report_auth(True, \"OK\", \"Logged in via \" + used)\n    try:\n        if power_only:\n            watchdog(p, engine_ok or \"chromium\")\n        else:\n            renew(p, engine_ok or \"chromium\")\n    except Exception as e:\n        log(\"RESULT: %s failed - %s\" % (\"power check\" if power_only else \"renewal\", clean(e)))\n        if not power_only:\n            report_renew(\"error\", clean(e, 160))\n            write_summary(\"Katabump server %s: renewal FAILED (%s)\" % (SERVER_ID, clean(e, 120)))\n        sys.exit(1)\n    return True\n\n\ndef main():\n    code, reason = validate_inputs()\n    if code:\n        log(\"ERROR: credential check failed - \" + reason)\n        log(\"Stopping now. No login attempt was made.\")\n        report_auth(False, code, reason)\n        sys.exit(2)\n    power_only = bool(os.environ.get(\"WATCHDOG\"))\n    log(\"Credential check passed (%s mode).\" % (\"power watchdog\" if power_only else \"renew\"))\n    has_server = bool(SERVER_ID and (PASSWORD.strip() or COOKIE_LIST))\n    has_account = bool(EMAIL and EMAIL_RE.match(EMAIL) and ACCOUNT_PASSWORD.strip()) or bool(COOKIE_LIST)\n    with sync_playwright() as p:\n        if power_only:\n            control_main(p, True)\n            return\n        if has_server:\n            if control_main(p, False, can_fallback=has_account):\n                return\n            log(\"Falling back to the dashboard login...\")\n        dashboard_main(p)\n\n\nif __name__ == \"__main__\":\n    main()\n";
const RENEW_YML_TEMPLATE = "name: Parham Confing Auto Renew\n\non:\n  schedule:\n    - cron: '__CRON__'\n  workflow_dispatch:\n\nconcurrency:\n  group: katabump-renew\n  cancel-in-progress: false\n\njobs:\n  renew-job:\n    runs-on: ubuntu-latest\n    timeout-minutes: 10\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Setup Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n\n      - name: Install Playwright\n        run: |\n          python -m pip install --upgrade pip\n          pip install playwright patchright\n          playwright install --with-deps chromium firefox\n          patchright install chromium || true\n          sudo apt-get install -y xvfb\n\n      - name: Restore dashboard session\n        uses: actions/cache@v4\n        with:\n          path: katabump_dash_state.json\n          key: dash-state-${{ github.run_id }}\n          restore-keys: |\n            dash-state-\n\n      - name: Run renew script\n        env:\n          KATABUMP_EMAIL: ${{ secrets.KATABUMP_EMAIL }}\n          KATABUMP_PASSWORD: ${{ secrets.KATABUMP_PASSWORD }}\n          KATABUMP_ACCOUNT_PASSWORD: ${{ secrets.KATABUMP_ACCOUNT_PASSWORD }}\n          KATABUMP_COOKIES: ${{ secrets.KATABUMP_COOKIES }}\n          SERVER_ID: ${{ secrets.SERVER_ID }}\n        run: xvfb-run -a --server-args=\"-screen 0 1280x720x24\" python renew.py\n\n      - name: Upload debug screenshots\n        if: failure()\n        uses: actions/upload-artifact@v4\n        with:\n          name: debug\n          path: |\n            debug-*.png\n            debug-*.html\n          if-no-files-found: ignore\n";
const WATCHDOG_YML = "name: Parham Confing Watchdog\n\non:\n  schedule:\n    - cron: '*/15 * * * *'\n  workflow_dispatch:\n\nconcurrency:\n  group: katabump-watchdog\n  cancel-in-progress: false\n\njobs:\n  watchdog-job:\n    runs-on: ubuntu-latest\n    timeout-minutes: 8\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Setup Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: '3.11'\n\n      - name: Install Playwright\n        run: |\n          python -m pip install --upgrade pip\n          pip install playwright\n          playwright install --with-deps chromium\n          sudo apt-get install -y xvfb\n\n      - name: Check power and start if offline\n        env:\n          KATABUMP_EMAIL: ${{ secrets.KATABUMP_EMAIL }}\n          KATABUMP_PASSWORD: ${{ secrets.KATABUMP_PASSWORD }}\n          KATABUMP_COOKIES: ${{ secrets.KATABUMP_COOKIES }}\n          SERVER_ID: ${{ secrets.SERVER_ID }}\n          WATCHDOG: '1'\n        run: xvfb-run -a --server-args=\"-screen 0 1280x720x24\" python renew.py\n\n      - name: Upload debug screenshots\n        if: failure()\n        uses: actions/upload-artifact@v4\n        with:\n          name: debug-watchdog\n          path: |\n            debug-*.png\n            debug-*.html\n          if-no-files-found: ignore\n";

const dns = require('dns');
const HostDetect = {
  dir: null,
  startup: null,
  override: null,
  learned: null,
  rebuild: null,
  _lastLearn: 0,

  SUFFIXES: {
    'antx.fr': ['Antagonix', true],
    'onrender.com': ['Render', true],
    'up.railway.app': ['Railway', true],
    'railway.app': ['Railway', true],
    'koyeb.app': ['Koyeb', true],
    'fly.dev': ['Fly.io', true],
    'herokuapp.com': ['Heroku', true],
    'glitch.me': ['Glitch', true],
    'repl.co': ['Replit', true],
    'replit.dev': ['Replit', true],
    'hf.space': ['Hugging Face Spaces', true],
    'app.github.dev': ['GitHub Codespaces', true],
    'katabump.com': ['Katabump', false]
  },

  ENV_PROVIDERS: [
    { id: 'render', label: 'Render', host: (e) => e.RENDER_EXTERNAL_HOSTNAME || e.RENDER_EXTERNAL_URL },
    { id: 'railway', label: 'Railway', host: (e) => e.RAILWAY_PUBLIC_DOMAIN || e.RAILWAY_STATIC_URL },
    { id: 'koyeb', label: 'Koyeb', host: (e) => e.KOYEB_PUBLIC_DOMAIN },
    { id: 'fly', label: 'Fly.io', host: (e) => e.FLY_APP_NAME && (e.FLY_APP_NAME + '.fly.dev') },
    { id: 'heroku', label: 'Heroku', host: (e) => e.DYNO && e.HEROKU_APP_NAME && (e.HEROKU_APP_NAME + '.herokuapp.com') },
    { id: 'huggingface', label: 'Hugging Face Spaces', host: (e) => e.SPACE_HOST, listenPort: 7860 },
    { id: 'replit', label: 'Replit', host: (e) => e.REPLIT_DEV_DOMAIN || (e.REPL_SLUG && e.REPL_OWNER && (e.REPL_SLUG + '.' + e.REPL_OWNER + '.repl.co')) },
    { id: 'glitch', label: 'Glitch', host: (e) => e.PROJECT_DOMAIN && (e.PROJECT_DOMAIN + '.glitch.me') }
  ],

  SAFE_ENV_VALUES: ['SERVER_IP', 'SERVER_PORT', 'PORT', 'P_SERVER_LOCATION', 'NODE_ENV'],

  init(paths) {
    this.dir = paths.dataDir;
    this.override = this._readJson('host-override.json');
    this.learned = this._readJson('host-learned.json');
  },

  _readJson(name) { try { return JSON.parse(fs.readFileSync(path.join(this.dir, name), 'utf8')); } catch { return null; } },
  _writeJson(name, obj) { try { fs.writeFileSync(path.join(this.dir, name), JSON.stringify(obj, null, 2), { mode: 0o600 }); } catch {} },
  _rm(name) { try { fs.unlinkSync(path.join(this.dir, name)); } catch {} },

  cleanHost(v) {
    if (!v) return '';
    let h = String(v).trim().toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/[\/?#].*$/, '').replace(/:\d+$/, '');
    return h;
  },
  validHost(h) {
    if (!h || h.length > 253) return false;
    if (/^\d{1,3}(\.\d{1,3}){3}$/.test(h)) return h.split('.').every((n) => Number(n) <= 255);
    if (/^\[?[0-9a-f:]+\]?$/.test(h) && h.includes(':')) return true;
    return /^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/.test(h);
  },
  isPrivateHost(h) {
    if (!h) return true;
    if (h === 'localhost' || h.endsWith('.local') || h.endsWith('.internal') || h === '::1' || h === '[::1]') return true;
    const m = h.match(/^(\d+)\.(\d+)\.\d+\.\d+$/);
    if (m) { const a = +m[1], b = +m[2]; return a === 10 || a === 127 || a === 0 || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 169 && b === 254) || (a === 100 && b >= 64 && b <= 127); }
    return false;
  },
  isIp(h) { return /^\d{1,3}(\.\d{1,3}){3}$/.test(h) || (h.includes(':') && /^\[?[0-9a-f:]+\]?$/.test(h)); },
  validPort(p) { p = Number(p); return Number.isInteger(p) && p >= 1 && p <= 65535; },

  suffixInfo(host) {
    const h = this.cleanHost(host);
    let best = null;
    for (const s of Object.keys(this.SUFFIXES)) if (h === s || h.endsWith('.' + s)) { if (!best || s.length > best.length) best = s; }
    return best ? { suffix: best, label: this.SUFFIXES[best][0], edge: this.SUFFIXES[best][1] } : null;
  },

  async detectStartup(config, resolvePublicHost) {
    if (!this.dir) this.init(config.paths);
    const env = process.env, reasons = [];
    const info = { provider: 'unknown', label: 'نامشخص', kind: 'raw', source: 'auto', host: '', listenPort: config.publicPort, tls: false, reasons, publicIp: '', ptr: '' };

    for (const p of this.ENV_PROVIDERS) {
      let h = '';
      try { h = this.cleanHost(p.host(env)); } catch {}
      if (h && this.validHost(h)) {
        Object.assign(info, { provider: p.id, label: p.label, kind: 'edge', source: 'env', host: h, tls: true });
        reasons.push('متغیرهای محیطی ' + p.label + ' پیدا شد');
        if (p.listenPort && !(env.PORT || env.SERVER_PORT || env.SB_PORT)) { config.publicPort = p.listenPort; info.listenPort = p.listenPort; reasons.push('پورت ' + p.listenPort + ' برای ' + p.label + ' تنظیم شد'); }
        break;
      }
    }

    if (info.source === 'auto') {
      const keys = Object.keys(this.SUFFIXES).map((s) => s.replace(/\./g, '\\.')).join('|');
      const re = new RegExp('(?:^|[^a-z0-9-.])((?:[a-z0-9-]+\\.)+(?:' + keys + '))(?![a-z0-9-])', 'i');
      const hay = Object.entries(env).filter(([k]) => !/PASS|SECRET|TOKEN|KEY/i.test(k)).map(([k, v]) => [k, String(v)]);
      try { hay.push(['hostname', os.hostname()]); } catch {}
      for (const [k, v] of hay) {
        const m = v.match(re);
        if (m) {
          const h = this.cleanHost(m[1]); const si = this.suffixInfo(h);
          if (si && this.validHost(h)) {
            Object.assign(info, { provider: si.label.toLowerCase().replace(/[^a-z0-9]+/g, ''), label: si.label, kind: si.edge ? 'edge' : 'raw', source: 'env', host: h, tls: !!si.edge });
            reasons.push('دامنه ' + h + ' داخل ' + (k === 'hostname' ? 'hostname' : 'متغیر ' + k) + ' پیدا شد');
            break;
          }
        }
      }
    }

    if (info.provider === 'unknown') {
      const keyHit = Object.keys(env).find((k) => /antagonix|antx/i.test(k));
      let hn = ''; try { hn = os.hostname(); } catch {}
      if (keyHit || /antagonix|antx/i.test(hn)) { info.provider = 'antagonix'; info.label = 'Antagonix'; info.kind = 'edge'; info.tls = true; reasons.push('نشانه‌ی Antagonix در محیط پیدا شد (دامنه‌ی .antx.fr از اولین ورود ادمین یاد گرفته می‌شود)'); }
      else if (Object.keys(env).some((k) => /katabump/i.test(k)) || /katabump/i.test(hn)) { info.provider = 'katabump'; info.label = 'Katabump'; reasons.push('نشانه‌ی Katabump پیدا شد'); }
      else if (env.P_SERVER_UUID || (env.SERVER_IP && env.SERVER_PORT)) { info.provider = 'pterodactyl'; info.label = 'Pterodactyl (مثل Katabump)'; reasons.push('متغیرهای Pterodactyl پیدا شد (SERVER_IP / SERVER_PORT)'); }
    }
    if (info.provider === 'katabump' && !info.label.includes('Katabump')) info.label = 'Katabump';
    if (info.kind === 'raw' && (env.SERVER_PORT || env.PORT)) reasons.push('پورت اختصاصی ' + (env.SERVER_PORT || env.PORT) + ' از متغیر محیطی خوانده شد');

    let host = '';
    try { host = await resolvePublicHost(config); } catch { host = ''; }
    if (info.source === 'auto') {
      info.host = host || '127.0.0.1';
      if (config.forceHost || config.domain) { info.source = 'config'; reasons.push('آدرس از DOMAIN / FORCE_HOST خوانده شد'); }
      else if (this.isIp(info.host)) { info.publicIp = info.host; reasons.push('آی‌پی عمومی سرور از اینترنت گرفته شد'); }
    } else if (this.isIp(host)) { info.publicIp = host; }
    if (info.publicIp) {
      try {
        const names = await Promise.race([dns.promises.reverse(info.publicIp), new Promise((r) => setTimeout(() => r([]), 2500))]);
        if (names && names[0]) info.ptr = names[0];
      } catch {}
      if (info.provider === 'unknown' && info.ptr) { const si = this.suffixInfo(info.ptr); if (si) { info.provider = si.label.toLowerCase(); info.label = si.label; reasons.push('Reverse-DNS آی‌پی به ' + si.label + ' اشاره کرد'); } }
    }
    this.startup = info;
    return info.host;
  },

  effective(config, fallbackHost) {
    const s = this.startup || { provider: 'unknown', label: 'نامشخص', kind: 'raw', source: 'auto', tls: false };
    const out = { host: fallbackHost || s.host || config.forceHost || config.domain || '127.0.0.1', linkPort: config.publicPort, tls: false, edge: false, provider: s.provider, label: s.label, source: 'auto', manual: false };
    const edgeOf = (host, port, tls, edge) => ({ host, linkPort: port, tls: !!tls, edge: !!edge });
    const o = this.override, l = this.learned;
    if (o && o.host) { Object.assign(out, edgeOf(o.host, o.port || config.publicPort, o.tls, o.edge), { source: 'manual', manual: true }); return out; }
    if (s.source === 'env' && s.host) { Object.assign(out, edgeOf(s.host, s.kind === 'edge' ? 443 : (Number(process.env.PUBLIC_PORT) || config.publicPort), s.kind === 'edge', s.kind === 'edge'), { source: 'env' }); return out; }
    if (config.forceHost || config.domain) {
      Object.assign(out, edgeOf(config.forceHost || config.domain, Number(process.env.PUBLIC_PORT) || config.publicPort, false, false), { source: 'config' }); return out;
    }
    if (l && l.host) { Object.assign(out, edgeOf(l.host, l.port || config.publicPort, l.tls, l.edge), { source: 'learned' }); return out; }
    if (Number(process.env.PUBLIC_PORT)) out.linkPort = Number(process.env.PUBLIC_PORT);
    return out;
  },

  panelUrl(config, fallbackHost) {
    const e = this.effective(config, fallbackHost);
    const def = e.tls ? 443 : 80;
    return (e.tls ? 'https://' : 'http://') + e.host + (e.linkPort && e.linkPort !== def ? ':' + e.linkPort : '') + '/' + config.panelPath;
  },

  observe(req, config) {
    try {
      if (this.override) return;
      const hdr = (n) => String(req.headers[n] || '').split(',')[0].trim();
      const rawHost = hdr('x-forwarded-host') || hdr('host');
      if (!rawHost) return;
      let host = this.cleanHost(rawHost);
      if (!this.validHost(host) || this.isPrivateHost(host) || host.endsWith('trycloudflare.com')) return;
      const proto = hdr('x-forwarded-proto').toLowerCase();
      const tls = proto === 'https' || !!(req.socket && req.socket.encrypted);
      const hostPort = (rawHost.match(/:(\d+)$/) || [])[1];
      const port = Number(hdr('x-forwarded-port')) || Number(hostPort) || (tls ? 443 : 80);
      if (!this.validPort(port)) return;
      const viaProxy = !!(hdr('x-forwarded-host') || hdr('x-forwarded-proto'));
      const edge = !this.isIp(host) && (viaProxy || port === 443 || port === 80);
      const next = { host, port, tls, edge, at: new Date().toISOString() };
      const cur = this.learned;
      if (cur && cur.host === next.host && cur.port === next.port && cur.tls === next.tls && cur.edge === next.edge) return;
      if (Date.now() - this._lastLearn < 3000) return;
      this._lastLearn = Date.now();
      this.learned = next; this._writeJson('host-learned.json', next);
      if (this.rebuild) try { this.rebuild(); } catch {}
    } catch {}
  },

  setOverride(config, body) {
    const host = this.cleanHost(body && body.host);
    if (!this.validHost(host)) throw new UserError('آدرس هاست نامعتبر است (فقط دامنه یا IP، بدون http و مسیر).', 400);
    let port = body && body.port !== undefined && body.port !== '' ? Number(body.port) : null;
    const tls = !!(body && body.tls);
    if (port === null) port = tls ? 443 : config.publicPort;
    if (!this.validPort(port)) throw new UserError('پورت نامعتبر است.', 400);
    const edge = !this.isIp(host) && (tls || port === 443 || port === 80);
    this.override = { host, port, tls, edge, at: new Date().toISOString() };
    this._writeJson('host-override.json', this.override);
    if (this.rebuild) try { this.rebuild(); } catch {}
    return this.override;
  },
  clear() { this.override = null; this.learned = null; this._rm('host-override.json'); this._rm('host-learned.json'); if (this.rebuild) try { this.rebuild(); } catch {} },

  banner(config, fallbackHost) {
    const L = [];
    const e = this.effective(config, fallbackHost), st = this.startup || {};
    const env = process.env;
    const needDomain = st.kind === 'edge' && !e.edge;
    const modeText = needDomain ? 'هاست با دامنه‌ی HTTPS (دامنه هنوز مشخص نیست)' : e.edge ? (e.tls ? 'دامنه + HTTPS (پورت ' + e.linkPort + ')' : 'دامنه + HTTP (پورت ' + e.linkPort + ')') : (this.isIp(e.host) ? 'آی‌پی + پورت اختصاصی' : 'دامنه + پورت اختصاصی');
    L.push(['Host', e.label + '  ·  ' + modeText]);
    L.push(['Give users', needDomain ? 'دامنه‌ی هاست (مثل name.antx.fr) روی پورت 443' : e.host + ':' + e.linkPort + (e.edge ? '   (WS' + (e.tls ? ' + TLS' : '') + ')' : '')]);
    if (!e.edge && !needDomain && st.ptr && this.isIp(e.host)) L.push(['Hostname', st.ptr + '  (آدرس جایگزین، اگه آی‌پی عوض شد)']);
    if (!e.edge && !needDomain) L.push(['Protocols', 'همه فعال (Hysteria2 / VLESS / Trojan / ...)']);
    else L.push(['Protocols', 'فقط WebSocket (VLESS-WS / Trojan-WS)؛ پورت مستقیم روی این هاست کار نمی‌کنه']);
    const warn = [];
    if (!e.edge && !needDomain && !(env.SERVER_PORT || env.PORT || env.SB_PORT) && !e.manual) warn.push('پورت اختصاصی از هاست پیدا نشد؛ پورت پیش‌فرض ' + config.publicPort + ' استفاده شد. اگه هاست پورت دیگه‌ای داده، متغیر PORT رو بذار.');
    if (!e.edge && !needDomain && (e.host === '127.0.0.1' || this.isPrivateHost(e.host))) warn.push('آی‌پی عمومی پیدا نشد؛ از «تشخیص هاست» تو پنل آدرس رو دستی بزن.');
    if (needDomain || (e.edge && e.source === 'auto')) warn.push('دامنه هنوز مشخص نیست؛ پنل رو از لینک خود هاست باز کن و وارد Admin شو تا یاد بگیره.');
    if (e.source === 'learned') L.push(['Source', 'از آدرس مرورگر ادمین یاد گرفته شد']);
    return { rows: L, warn };
  },

  probe(config, fallbackHost, cb) {
    try {
      const e = this.effective(config, fallbackHost);
      if (e.edge || !this.isIp(e.host) || this.isPrivateHost(e.host)) return;
      const sock = require('net').connect({ host: e.host, port: e.linkPort, timeout: 2500 });
      let done = false; const fin = (ok) => { if (done) return; done = true; try { sock.destroy(); } catch {} cb(ok); };
      sock.on('connect', () => fin(true)); sock.on('timeout', () => fin(false)); sock.on('error', () => fin(false));
    } catch {}
  },

  report(req, config, fallbackHost) {
    const e = this.effective(config, fallbackHost);
    const hdr = (n) => String(req.headers[n] || '').split(',')[0].trim();
    const bh = this.cleanHost(hdr('x-forwarded-host') || hdr('host'));
    const proto = hdr('x-forwarded-proto').toLowerCase();
    const env = process.env;
    const names = Object.keys(env).sort();
    const safe = {}; for (const k of this.SAFE_ENV_VALUES) if (env[k] !== undefined) safe[k] = String(env[k]).slice(0, 80);
    let hn = ''; try { hn = os.hostname(); } catch {}
    return {
      effective: { host: e.host, port: e.linkPort, tls: e.tls, edge: e.edge, source: e.source, provider: e.provider, label: e.label },
      startup: this.startup ? { provider: this.startup.provider, label: this.startup.label, kind: this.startup.kind, source: this.startup.source, host: this.startup.host, listenPort: this.startup.listenPort, publicIp: this.startup.publicIp, ptr: this.startup.ptr, reasons: this.startup.reasons } : null,
      override: this.override, learned: this.learned,
      browser: { host: bh, proto: proto || (req.socket && req.socket.encrypted ? 'https' : 'http'), port: hdr('x-forwarded-port') || ((hdr('host').match(/:(\d+)$/) || [])[1] || ''), private: this.isPrivateHost(bh) },
      diag: { hostname: hn, platform: process.platform, envCount: names.length, envNames: names.filter((n) => !/PASS|SECRET|TOKEN|KEY|AUTH|COOKIE/i.test(n)), safeValues: safe }
    };
  }
};

class UserError extends Error {
  constructor(message, status = 400) { super(message); this.status = status; }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const Events = {
  items: [],
  push(level, msg) {
    this.items.push({ t: Date.now(), level, msg: String(msg).replace(/\x1b\[[0-9;]*m/g, '').slice(0, 500) });
    if (this.items.length > 200) this.items.splice(0, this.items.length - 200);
  }
};
['info', 'success', 'warn', 'error'].forEach((k) => {
  const orig = Logger[k];
  if (typeof orig !== 'function') return;
  Logger[k] = function (m) {
    try { Events.push(k, m); } catch {}
    return orig.call(this, m);
  };
});

function readNum(file) {
  try {
    const v = fs.readFileSync(file, 'utf8').trim();
    if (!v || v === 'max') return null;
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
  } catch { return null; }
}

class RuntimeStats {
  constructor() {
    this.totalUp = 0;
    this.totalDown = 0;
    this.totalConns = 0;
    this.activeConns = 0;
    this.byProto = {};
    this.since = Date.now();
    this.history = [];
    this.file = null;
    this.lastCpu = os.cpus();
    this.lastProc = process.cpuUsage();
    this.lastCg = null;
    this.lastT = process.hrtime.bigint();
    this.lastUp = 0;
    this.lastDown = 0;
    this.rates = { up: 0, down: 0 };
    this.cpu = { system: 0, process: 0, container: null };
    this.timer = null;
    this.saveTimer = null;
    this.dataDir = null;
  }

  init(paths) {
    if (this.file) return;
    this.dataDir = paths.dataDir;
    this.file = path.join(paths.dataDir, 'traffic.json');
    try {
      const j = JSON.parse(fs.readFileSync(this.file, 'utf8'));
      this.totalUp = Number(j.totalUp) || 0;
      this.totalDown = Number(j.totalDown) || 0;
      this.totalConns = Number(j.totalConns) || 0;
      this.since = Number(j.since) || this.since;
      if (j.byProto && typeof j.byProto === 'object') {
        for (const [k, v] of Object.entries(j.byProto)) {
          this.byProto[k] = { up: Number(v.up) || 0, down: Number(v.down) || 0, conns: Number(v.conns) || 0 };
        }
      }
    } catch {}
    this.lastUp = this.totalUp;
    this.lastDown = this.totalDown;
    this.timer = setInterval(() => this.sample(), 10000);
    this.saveTimer = setInterval(() => this.save(), 120000);
    if (this.timer.unref) this.timer.unref();
    if (this.saveTimer.unref) this.saveTimer.unref();
    process.on('exit', () => this.save());
    this.sample();
  }

  proto(label) {
    if (!this.byProto[label]) this.byProto[label] = { up: 0, down: 0, conns: 0 };
    return this.byProto[label];
  }

  track(label, clientSock, backendSock, firstBytes = 0) {
    const p = this.proto(label);
    p.conns++;
    this.totalConns++;
    this.activeConns++;
    if (firstBytes) { p.up += firstBytes; this.totalUp += firstBytes; }
    clientSock.on('data', (c) => { p.up += c.length; this.totalUp += c.length; });
    backendSock.on('data', (c) => { p.down += c.length; this.totalDown += c.length; });
    let closed = false;
    const done = () => { if (!closed) { closed = true; this.activeConns = Math.max(0, this.activeConns - 1); } };
    clientSock.once('close', done);
    backendSock.once('close', done);
  }

  save() {
    if (!this.file) return;
    try {
      fs.writeFileSync(this.file, JSON.stringify({
        totalUp: this.totalUp, totalDown: this.totalDown, totalConns: this.totalConns,
        since: this.since, byProto: this.byProto
      }), 'utf8');
    } catch {}
  }

  reset() {
    this.totalUp = this.totalDown = this.totalConns = 0;
    this.byProto = {};
    this.since = Date.now();
    this.lastUp = this.lastDown = 0;
    this.save();
  }

  readCgroup() {
    const cur = readNum('/sys/fs/cgroup/memory.current');
    const max = readNum('/sys/fs/cgroup/memory.max');
    if (cur !== null) return { used: cur, total: max };
    const cur1 = readNum('/sys/fs/cgroup/memory/memory.usage_in_bytes');
    let max1 = readNum('/sys/fs/cgroup/memory/memory.limit_in_bytes');
    if (cur1 !== null) {
      if (max1 !== null && max1 > os.totalmem() * 4) max1 = null;
      return { used: cur1, total: max1 };
    }
    return null;
  }

  readCgroupCpu() {
    try {
      const txt = fs.readFileSync('/sys/fs/cgroup/cpu.stat', 'utf8');
      const m = txt.match(/usage_usec\s+(\d+)/);
      if (!m) return null;
      let quota = null;
      try {
        const [q, per] = fs.readFileSync('/sys/fs/cgroup/cpu.max', 'utf8').trim().split(/\s+/);
        if (q !== 'max') quota = Number(q) / Number(per);
      } catch {}
      return { usec: Number(m[1]), quota };
    } catch { return null; }
  }

  sample() {
    const now = process.hrtime.bigint();
    const dtSec = Number(now - this.lastT) / 1e9 || 1;
    this.lastT = now;

    const cpus = os.cpus();
    let idle = 0, total = 0;
    for (let i = 0; i < cpus.length; i++) {
      const a = cpus[i].times, b = (this.lastCpu[i] || cpus[i]).times;
      const di = a.idle - b.idle;
      const dt = (a.user - b.user) + (a.nice - b.nice) + (a.sys - b.sys) + (a.irq - b.irq) + di;
      idle += di; total += dt;
    }
    this.lastCpu = cpus;
    this.cpu.system = total > 0 ? Math.max(0, Math.min(100, (1 - idle / total) * 100)) : 0;

    const pu = process.cpuUsage();
    const used = (pu.user - this.lastProc.user) + (pu.system - this.lastProc.system);
    this.lastProc = pu;
    this.cpu.process = Math.max(0, used / 1e6 / dtSec * 100);

    const cg = this.readCgroupCpu();
    if (cg && this.lastCg) {
      const dUsec = cg.usec - this.lastCg.usec;
      const cores = cg.quota || 1;
      this.cpu.container = Math.max(0, Math.min(100, dUsec / 1e6 / dtSec / cores * 100));
    } else if (!cg) {
      this.cpu.container = null;
    }
    this.lastCg = cg;

    this.rates.up = Math.max(0, (this.totalUp - this.lastUp) / dtSec);
    this.rates.down = Math.max(0, (this.totalDown - this.lastDown) / dtSec);
    this.lastUp = this.totalUp;
    this.lastDown = this.totalDown;

    const mem = this.memory();
    const cpuShown = this.cpu.container !== null ? this.cpu.container : this.cpu.process;
    this.history.push({
      t: Date.now(),
      cpu: Number(cpuShown.toFixed(1)),
      mem: mem.total ? Number((mem.used / mem.total * 100).toFixed(1)) : 0,
      up: Math.round(this.rates.up),
      down: Math.round(this.rates.down)
    });
    if (this.history.length > 60) this.history.shift();
  }

  memory() {
    const rss = process.memoryUsage().rss;
    const cg = this.readCgroup();
    if (cg) {
      const total = cg.total || os.totalmem();
      return { used: cg.used, total, rss, source: cg.total ? 'container' : 'host' };
    }
    const total = os.totalmem();
    return { used: total - os.freemem(), total, rss, source: 'host' };
  }

  disk() {
    try {
      if (typeof fs.statfsSync !== 'function' || !this.dataDir) return null;
      const s = fs.statfsSync(this.dataDir);
      const total = s.blocks * s.bsize;
      const free = s.bavail * s.bsize;
      return { total, free, used: total - free };
    } catch { return null; }
  }

  snapshot() {
    return {
      now: Date.now(),
      uptime: process.uptime(),
      node: process.version,
      platform: `${os.platform()} ${os.arch()}`,
      cores: os.cpus().length,
      load: os.loadavg(),
      cpu: { ...this.cpu },
      mem: this.memory(),
      disk: this.disk(),
      net: {
        totalUp: this.totalUp, totalDown: this.totalDown,
        totalConns: this.totalConns, activeConns: this.activeConns,
        upRate: this.rates.up, downRate: this.rates.down,
        since: this.since, byProto: this.byProto
      },
      history: this.history
    };
  }
}
const Stats = new RuntimeStats();

class AdminAuth {
  constructor(config, paths) {
    this.fromPanelToken = !!config.panelToken;
    this.key = config.panelToken || '';
    if (!this.key) {
      const f = path.join(paths.dataDir, 'admin-key.txt');
      try { this.key = fs.readFileSync(f, 'utf8').trim(); } catch {}
      if (!this.key || this.key.length < 16) {
        this.key = crypto.randomBytes(18).toString('base64url');
        try { fs.writeFileSync(f, this.key + '\n', { mode: 0o600 }); } catch {}
      }
    }
    this.fails = new Map();
    this.middleware = this.middleware.bind(this);
  }

  digest(s) { return crypto.createHash('sha256').update(String(s)).digest(); }

  valid(req) {
    try {
      const h = req.headers['authorization'];
      const bearer = h && h.startsWith('Bearer ') ? h.slice(7).trim() : '';
      const given = bearer || String(req.headers['x-admin-key'] || '');
      return !!given && crypto.timingSafeEqual(this.digest(given), this.digest(this.key));
    } catch { return false; }
  }

  middleware(req, res, next) {
    const ip = (req.socket && req.socket.remoteAddress) || 'x';
    const rec = this.fails.get(ip);
    const now = Date.now();
    const h = req.headers['authorization'];
    const bearer = h && h.startsWith('Bearer ') ? h.slice(7).trim() : '';
    const given = bearer || String(req.headers['x-admin-key'] || '');
    if (given && crypto.timingSafeEqual(this.digest(given), this.digest(this.key))) {
      this.fails.delete(ip);
      return next();
    }
    if (!given) {
      return res.status(401).json({ ok: false, error: 'کلید مدیریت لازم است.', needKey: true });
    }
    if (rec && rec.until > now) {
      return res.status(429).json({ ok: false, error: 'تلاش‌های ناموفق زیاد بود؛ چند دقیقه بعد دوباره امتحان کن.' });
    }
    const r = rec || { n: 0, until: 0 };
    r.n++;
    if (r.n >= 8) { r.until = now + 5 * 60 * 1000; r.n = 0; }
    this.fails.set(ip, r);
    if (this.fails.size > 500) this.fails.clear();
    return res.status(401).json({ ok: false, error: 'کلید مدیریت نامعتبر است.', needKey: true });
  }
}


/* ===== GitHub robust transport: many routes, retries, no single point of failure ===== */
try { require('dns').setDefaultResultOrder('ipv4first'); } catch {}
const GH_FALLBACK_IPS = ['140.82.112.6', '140.82.113.6', '140.82.114.6', '140.82.121.6', '20.205.243.168'];
const GH_CONNECT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET', 'ECONNREFUSED', 'ENOTFOUND', 'EAI_AGAIN', 'EHOSTUNREACH', 'ENETUNREACH', 'EPIPE', 'EADDRNOTAVAIL', 'ECONNABORTED', 'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_SOCKET', 'UND_ERR_HEADERS_TIMEOUT', 'UND_ERR_BODY_TIMEOUT', 'ERR_TLS_CERT_ALTNAME_INVALID', 'CERT_HAS_EXPIRED', 'EPROTO']);

function ghProxyUrl(cfg) {
  const e = process.env;
  return (cfg && cfg.githubProxy) || e.GITHUB_PROXY || e.HTTPS_PROXY || e.https_proxy || e.ALL_PROXY || e.all_proxy || '';
}

function ghProxySocket(proxy, host, port, timeout) {
  return new Promise((resolve, reject) => {
    const tlsMod = require('tls');
    let pu;
    try { pu = new URL(proxy.includes('://') ? proxy : 'http://' + proxy); } catch (e) { return reject(e); }
    const headers = { Host: host + ':' + port };
    if (pu.username) headers['Proxy-Authorization'] = 'Basic ' + Buffer.from(decodeURIComponent(pu.username) + ':' + decodeURIComponent(pu.password || '')).toString('base64');
    const req = http.request({ host: pu.hostname, port: pu.port || 80, method: 'CONNECT', path: host + ':' + port, headers, timeout });
    req.once('timeout', () => req.destroy(Object.assign(new Error('proxy timeout'), { code: 'ETIMEDOUT' })));
    req.once('error', reject);
    req.once('connect', (res, socket) => {
      if (res.statusCode !== 200) { socket.destroy(); return reject(Object.assign(new Error('proxy status ' + res.statusCode), { code: 'ECONNREFUSED' })); }
      const t = tlsMod.connect({ socket, servername: host });
      t.once('secureConnect', () => resolve(t));
      t.once('error', reject);
    });
    req.end();
  });
}

/* one HTTPS request over a chosen route (family / fixed ip / proxy). Rejects with err.phase = 'connect' | 'response' */
async function ghHttps(o) {
  const httpsMod = require('https');
  const u = new URL(o.base + o.path);
  const port = Number(u.port) || 443;
  let sock = null;
  if (o.proxy) sock = await ghProxySocket(o.proxy, u.hostname, port, o.connectTimeout);
  return new Promise((resolve, reject) => {
    let done = false, sent = false, req = null;
    const finish = (fn, v) => { if (done) return; done = true; clearTimeout(total); fn(v); };
    const fail = (e) => { try { req && req.destroy(); } catch {} try { sock && sock.destroy(); } catch {} e.phase = sent ? 'response' : 'connect'; finish(reject, e); };
    const total = setTimeout(() => fail(Object.assign(new Error('timeout'), { code: 'ETIMEDOUT' })), o.totalTimeout);
    const headers = { ...o.headers, Host: u.hostname, Connection: 'close' };
    if (o.payload !== undefined) headers['Content-Length'] = Buffer.byteLength(o.payload);
    const opts = {
      method: o.method, host: o.ip || u.hostname, port, path: u.pathname + u.search, headers,
      servername: u.hostname, agent: false, timeout: o.connectTimeout
    };
    if (o.family && !o.ip && !sock) opts.family = o.family;
    if (sock) opts.createConnection = () => sock;
    req = httpsMod.request(opts, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('error', fail);
      res.on('end', () => {
        const txt = Buffer.concat(chunks).toString('utf8');
        let data = null;
        if (txt) { try { data = JSON.parse(txt); } catch { data = txt; } }
        const h = {};
        for (const [k, v] of Object.entries(res.headers)) h[k] = Array.isArray(v) ? v.join(', ') : String(v);
        finish(resolve, { status: res.statusCode, ok: res.statusCode >= 200 && res.statusCode < 300, data, headers: new Headers(h) });
      });
    });
    req.on('timeout', () => { if (!sent) fail(Object.assign(new Error('connect timeout'), { code: 'ETIMEDOUT' })); });
    req.on('error', fail);
    req.on('finish', () => { sent = true; });
    if (o.payload !== undefined) req.write(o.payload);
    req.end();
  });
}

async function ghFetchRoute(o) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), o.totalTimeout);
  try {
    const res = await fetch(o.base + o.path, { method: o.method, signal: ctrl.signal, headers: o.headers, body: o.payload });
    const txt = await res.text();
    let data = null;
    if (txt) { try { data = JSON.parse(txt); } catch { data = txt; } }
    return { status: res.status, ok: res.ok, data, headers: res.headers };
  } catch (e) {
    const err = e.cause && e.cause.code ? Object.assign(new Error(e.message), { code: e.cause.code }) : e;
    if (e.name === 'AbortError') err.code = 'ETIMEDOUT';
    err.phase = 'connect';
    throw err;
  } finally { clearTimeout(timer); }
}

/* fresh A records for a host via public DNS (UDP) and, if blocked, via DNS-over-HTTPS */
async function ghResolveIps(host) {
  const out = [];
  try {
    const dnsMod = require('dns');
    const r = new dnsMod.promises.Resolver({ timeout: 4000, tries: 1 });
    r.setServers(['1.1.1.1', '8.8.8.8', '9.9.9.9']);
    out.push(...await r.resolve4(host));
  } catch {}
  if (!out.length) {
    for (const [ip, sni] of [['1.1.1.1', 'cloudflare-dns.com'], ['8.8.8.8', 'dns.google']]) {
      try {
        const r = await ghHttps({ base: 'https://' + sni, path: '/dns-query?name=' + host + '&type=A', method: 'GET', ip, headers: { Accept: 'application/dns-json' }, connectTimeout: 6000, totalTimeout: 8000 });
        const ans = r.data && r.data.Answer;
        if (Array.isArray(ans)) ans.filter((a) => a.type === 1 && a.data).forEach((a) => out.push(a.data));
        if (out.length) break;
      } catch {}
    }
  }
  return [...new Set(out)];
}

const UNLIMITED_SCHEDULES = {
  six_hours: { cron: '0 */6 * * *', label: 'هر ۶ ساعت' },
  daily: { cron: '0 12 * * *', label: 'روزی یک بار' },
  three_days: { cron: '0 12 */3 * *', label: 'هر ۳ روز' }
};

class UnlimitedManager {
  constructor(config, paths) {
    this.config = config;
    this.file = path.join(paths.dataDir, 'unlimited.json');
    this.apiBase = process.env.GITHUB_API_BASE || 'https://api.github.com';
    this.data = null;
    this.job = null;
    this.cache = null;
    this.sealerFactory = null;
    SecretBox.init(paths.dataDir);
    try { this.data = JSON.parse(fs.readFileSync(this.file, 'utf8')); } catch {}
    if (this.data && !this.data.token) this.data = null;
    if (this.data) {
      const opened = SecretBox.open(this.data.token);
      if (opened === null) {
        Logger.warn('Stored GitHub token could not be decrypted (secret key changed). Reconnect Unlimited to continue.');
        this.data = null;
      } else {
        this.data.token = opened.plain;
        if (opened.legacy) { this.save(); Logger.info('Stored GitHub token is now encrypted at rest.'); }
      }
    }
  }

  save() {
    try {
      if (!this.data) return;
      fs.writeFileSync(this.file, JSON.stringify({ ...this.data, token: SecretBox.seal(this.data.token) }, null, 2), { mode: 0o600 });
      try { fs.chmodSync(this.file, 0o600); } catch {}
    } catch (e) { Logger.warn(`Could not save unlimited.json: ${e.message}`); }
  }

  isConnected() { return !!(this.data && this.data.token && this.data.owner && this.data.repo); }

  mask(t) { return t ? t.slice(0, 4) + '••••••••' + t.slice(-4) : ''; }

  defaults() {
    const c = (this.config && this.config.unlimited) || {};
    const env = process.env;
    let guess = c.serverId || env.KB_SERVER_ID || '';
    if (!guess && env.P_SERVER_UUID) guess = String(env.P_SERVER_UUID).slice(0, 8);
    return {
      serverId: guess,
      repo: c.repo || 'katabump-auto-renew',
      schedule: 'daily',
      email: c.katabumpEmail || env.KATABUMP_EMAIL || ''
    };
  }

  ghNote(msg) {
    try {
      if (!this.job || !this.job.running) return;
      const st = this.job.steps.find((x) => x.state === 'running');
      if (st) st.detail = msg;
    } catch {}
  }

  /* ordered list of ways to reach GitHub; the last one that worked is tried first */
  async ghRoutes() {
    const bases = [this.apiBase];
    for (const b of String(process.env.GITHUB_API_BASES || '').split(',').map((x) => x.trim()).filter(Boolean)) if (!bases.includes(b)) bases.push(b);
    const routes = [];
    const proxy = ghProxyUrl(this.config && this.config.unlimited);
    for (const base of bases) {
      routes.push({ id: 'v4:' + base, base, kind: 'https', family: 4 });
      routes.push({ id: 'fetch:' + base, base, kind: 'fetch' });
      routes.push({ id: 'v6:' + base, base, kind: 'https', family: 6 });
      if (proxy) routes.push({ id: 'proxy:' + base, base, kind: 'https', proxy });
    }
    return routes;
  }

  async ghIpRoutes(base) {
    let host = '';
    try { host = new URL(base).hostname; } catch { return []; }
    const ips = [];
    const fresh = await ghResolveIps(host).catch(() => []);
    ips.push(...fresh);
    if (host === 'api.github.com') ips.push(...GH_FALLBACK_IPS);
    return [...new Set(ips)].slice(0, 6).map((ip) => ({ id: 'ip:' + ip, base, kind: 'https', ip }));
  }

  async gh(method, p, body, token) {
    const tk = token || (this.data && this.data.token);
    const headers = {
      'Authorization': `Bearer ${tk}`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'parham-confing-panel',
      ...(body ? { 'Content-Type': 'application/json' } : {})
    };
    const payload = body ? JSON.stringify(body) : undefined;
    const isRead = method === 'GET' || method === 'HEAD';
    const budget = Number(process.env.GITHUB_TOTAL_TIMEOUT_MS) || 110000;
    const t0 = Date.now();
    let routes = await this.ghRoutes();
    if (this.ghGood) {
      const i = routes.findIndex((r) => r.id === this.ghGood);
      if (i > 0) routes = [routes[i], ...routes.slice(0, i), ...routes.slice(i + 1)];
    }
    let ipRoutes = null;
    let lastErr = null, tries = 0;
    const ROUNDS = 3;
    for (let round = 0; round < ROUNDS; round++) {
      let list = routes;
      if (round >= 1) {
        if (!ipRoutes) ipRoutes = await this.ghIpRoutes(this.apiBase);
        list = [...routes, ...ipRoutes];
      }
      for (const route of list) {
        if (Date.now() - t0 > budget) break;
        const connectTimeout = 10000 + round * 6000;
        const totalTimeout = Math.min(35000, 20000 + round * 8000);
        tries++;
        try {
          const o = { ...route, path: p, method, headers, payload, connectTimeout, totalTimeout };
          const r = route.kind === 'fetch' ? await ghFetchRoute(o) : await ghHttps(o);
          if (isRead && [502, 503, 504].includes(r.status) && round < ROUNDS - 1) { lastErr = new Error('HTTP ' + r.status); continue; }
          this.ghGood = route.id;
          return r;
        } catch (e) {
          lastErr = e;
          const code = e.code || (e.cause && e.cause.code) || '';
          const connectLevel = e.phase === 'connect' || GH_CONNECT_CODES.has(code);
          /* a write that may already have reached GitHub is never repeated blindly */
          if (!isRead && e.phase === 'response') {
            throw Object.assign(new UserError('پاسخ GitHub به‌موقع نرسید؛ یک بار دیگر «اجرا / راه‌اندازی مجدد» را بزن (کارهای انجام‌شده تکرار نمی‌شوند).', 504), { ghConnect: true });
          }
          if (!connectLevel && !isRead) throw new UserError('اتصال به GitHub برقرار نشد: ' + (code || e.message), 502);
          this.ghNote(`اتصال به GitHub کند است؛ مسیر دیگر امتحان می‌شود (${tries})...`);
        }
      }
      if (Date.now() - t0 > budget) break;
      await sleep(1200 * (round + 1));
    }
    const code = lastErr && (lastErr.code || (lastErr.cause && lastErr.cause.code)) || (lastErr && lastErr.message) || 'unknown';
    throw Object.assign(new UserError(`سرور فعلاً به GitHub نمی‌رسد (${code}). همه‌ی مسیرها امتحان شد؛ چند دقیقه بعد دوباره بزن یا در تنظیمات پروکسی (GITHUB_PROXY) بده.`, 502), { ghConnect: true });
  }

  explain(r, what) {
    const msg = r.data && r.data.message ? r.data.message : '';
    if (r.status === 401) return new UserError('توکن GitHub نامعتبر یا منقضی است.', 401);
    if (r.status === 403) {
      if (/rate limit/i.test(msg)) return new UserError('محدودیت درخواست GitHub پر شده؛ کمی بعد دوباره امتحان کن.', 429);
      return new UserError(`دسترسی توکن کافی نیست (${what}). توکن باید scope های repo و workflow داشته باشد.`, 403);
    }
    if (r.status === 404) return new UserError(`پیدا نشد (${what}). معمولاً یعنی دسترسی توکن کافی نیست.`, 404);
    return new UserError(`GitHub خطا داد (${what}): ${msg || r.status}`, 502);
  }

  async sealer(publicKeyB64) {
    if (this.sealerFactory) return this.sealerFactory(publicKeyB64);
    let sodium = this.sodiumMod;
    if (!sodium) try { sodium = require('libsodium-wrappers'); this.sodiumMod = sodium; } catch {
      throw new UserError('ماژول libsodium-wrappers نصب نیست. سرور را یک بار Restart کن تا npm install اجرا شود (package.json جدید را آپلود کرده باشی).', 500);
    }
    await sodium.ready;
    const key = sodium.from_base64(publicKeyB64, sodium.base64_variants.ORIGINAL);
    return (plain) => sodium.to_base64(
      sodium.crypto_box_seal(sodium.from_string(plain), key),
      sodium.base64_variants.ORIGINAL
    );
  }

  jobSnapshot() {
    if (!this.job) return null;
    return JSON.parse(JSON.stringify(this.job));
  }

  step(key, state, detail) {
    const s = this.job.steps.find((x) => x.key === key);
    if (!s) return;
    s.state = state;
    if (detail !== undefined) s.detail = detail;
  }

  validate(input) {
    const o = {};
    o.token = String(input.token || '').trim();
    if (!/^(gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|[a-f0-9]{40})$/.test(o.token)) {
      throw new UserError('فرمت توکن GitHub درست نیست (باید با ghp_ یا github_pat_ شروع شود).');
    }
    o.email = String(input.email || '').trim();
    if (o.email.length > 200) throw new UserError('ایمیل خیلی طولانی است.');
    o.accountPassword = String(input.accountPassword || '');
    if (o.accountPassword.length > 300) throw new UserError('رمز حساب خیلی طولانی است.');
    o.password = String(input.password || '');
    if (o.password.length > 300) throw new UserError('رمز سرور خیلی طولانی است.');
    o.serverId = String(input.serverId || '').trim();
    if (o.serverId && !/^[A-Za-z0-9-]{4,64}$/.test(o.serverId)) throw new UserError('آیدی سرور معتبر نیست (مثلاً d1712508).');
    o.cookies = '';
    const rawCk = String(input.cookies || '').trim();
    if (rawCk) {
      if (rawCk.length > 20000) throw new UserError('کوکی‌ها خیلی طولانی‌اند.');
      let arr;
      try { arr = JSON.parse(rawCk); } catch { arr = null; }
      if (!Array.isArray(arr)) throw new UserError('فرمت کوکی‌ها درست نیست؛ دوباره «آنالیز» را بزن.');
      arr = arr.filter((c) => c && typeof c.name === 'string' && c.name && c.value !== undefined && c.value !== null).slice(0, 60)
        .map((c) => ({ name: c.name, value: String(c.value), domain: String(c.domain || ''), path: String(c.path || '/') }));
      if (arr.length) o.cookies = JSON.stringify(arr);
    }
    if (!(o.serverId && o.password) && !(o.email && o.accountPassword) && !o.cookies) {
      throw new UserError('یکی از این‌ها لازمه: کوکی (با آنالیز)، آیدی و رمز سرور، یا ایمیل و رمز حساب.');
    }
    o.repo = String(input.repo || 'katabump-auto-renew').trim();
    if (!/^[A-Za-z0-9._-]{1,80}$/.test(o.repo)) throw new UserError('نام ریپو فقط می‌تواند حروف انگلیسی، عدد، نقطه، خط تیره و زیرخط باشد.');
    o.schedule = 'daily';
    return o;
  }

  startSetup(input) {
    if (this.job && this.job.running) throw new UserError('یک عملیات دیگر در حال اجراست.', 409);
    const o = this.validate(input);
    this.job = {
      id: crypto.randomBytes(4).toString('hex'),
      running: true,
      done: false,
      error: null,
      startedAt: Date.now(),
      steps: [
        { key: 'login', label: 'تست آیدی و رمز سرور', state: 'pending', detail: '' },
        { key: 'auth', label: 'بررسی توکن GitHub', state: 'pending', detail: '' },
        { key: 'repo', label: 'ساخت ریپوی خصوصی', state: 'pending', detail: '' },
        { key: 'secrets', label: 'رمزنگاری و ذخیره Secrets', state: 'pending', detail: '' },
        { key: 'files', label: 'آپلود اسکریپت و workflow', state: 'pending', detail: '' },
        { key: 'run', label: 'اولین اجرای تمدید', state: 'pending', detail: '' }
      ]
    };
    this.cache = null;
    this.runSetup(o).catch((e) => {
      const cur = this.job.steps.find((s) => s.state === 'running');
      if (cur) { cur.state = 'error'; cur.detail = e.message; }
      this.job.error = e instanceof UserError ? e.message : 'خطای غیرمنتظره: ' + e.message;
      this.job.running = false;
      this.job.done = true;
      Events.push('error', 'Unlimited setup failed: ' + this.job.error);
    });
    return this.jobSnapshot();
  }

  async putFile(owner, repo, branch, filePath, content, message, token) {
    const enc = filePath.split('/').map(encodeURIComponent).join('/');
    for (let attempt = 0; attempt < 4; attempt++) {
      const cur = await this.gh('GET', `/repos/${owner}/${repo}/contents/${enc}?ref=${encodeURIComponent(branch)}`, null, token);
      let sha;
      if (cur.ok && cur.data && !Array.isArray(cur.data) && cur.data.sha) {
        sha = cur.data.sha;
        if (cur.data.content && Buffer.from(cur.data.content, 'base64').toString('utf8') === content) return 'unchanged';
      }
      const put = await this.gh('PUT', `/repos/${owner}/${repo}/contents/${enc}`, {
        message, content: Buffer.from(content, 'utf8').toString('base64'), branch, ...(sha ? { sha } : {})
      }, token);
      if (put.ok) return 'ok';
      if ([404, 409, 422].includes(put.status) && attempt < 3) { await sleep(1500 * (attempt + 1)); continue; }
      throw this.explain(put, filePath);
    }
    throw new UserError('آپلود فایل ناموفق بود: ' + filePath);
  }

  async dispatch(owner, repo, branch, token) {
    for (let attempt = 0; attempt < 6; attempt++) {
      const r = await this.gh('POST', `/repos/${owner}/${repo}/actions/workflows/renew.yml/dispatches`, { ref: branch }, token);
      if (r.status === 204) return true;
      if ([404, 422].includes(r.status) && attempt < 5) { await sleep(3000); continue; }
      throw this.explain(r, 'اجرای workflow');
    }
    return false;
  }

  kbRequest(method, pathName, headers, body, cookies) {
    const https = require('https');
    return new Promise((resolve, reject) => {
      const h = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'application/json, text/plain, */*',
        'Accept-Language': 'en-US,en;q=0.9',
        'Origin': 'https://control.katabump.com',
        'Referer': 'https://control.katabump.com/auth/login',
        ...headers
      };
      const jar = Object.entries(cookies).map(([k, v]) => k + '=' + v).join('; ');
      if (jar) h.Cookie = jar;
      if (body) h['Content-Length'] = Buffer.byteLength(body);
      const req = https.request({ hostname: 'control.katabump.com', path: pathName, method, headers: h, timeout: 15000 }, (res) => {
        const chunks = [];
        res.on('data', (c) => chunks.push(c));
        res.on('end', () => {
          const set = res.headers['set-cookie'] || [];
          for (const c of set) {
            const m = /^([^=]+)=([^;]*)/.exec(c);
            if (m) cookies[m[1]] = m[2];
          }
          resolve({ status: res.statusCode, body: Buffer.concat(chunks).toString('utf8') });
        });
      });
      req.on('timeout', () => req.destroy(new Error('timeout')));
      req.on('error', reject);
      if (body) req.write(body);
      req.end();
    });
  }

  async kbTryLogin(ident, password) {
    const cookies = {};
    const first = await this.kbRequest('GET', '/sanctum/csrf-cookie', {}, null, cookies);
    if (first.status >= 500 || /just a moment|attention required|cf-chl/i.test(first.body.slice(0, 3000))) return { state: 'unknown', detail: 'HTTP ' + first.status };
    let xsrf = '';
    try { xsrf = decodeURIComponent(cookies['XSRF-TOKEN'] || ''); } catch (e) { xsrf = cookies['XSRF-TOKEN'] || ''; }
    const payload = JSON.stringify({ user: ident, password, 'g-recaptcha-response': '' });
    const r = await this.kbRequest('POST', '/auth/login', {
      'Content-Type': 'application/json',
      'X-Requested-With': 'XMLHttpRequest',
      'X-XSRF-TOKEN': xsrf
    }, payload, cookies);
    let j = null;
    try { j = JSON.parse(r.body); } catch (e) { j = null; }
    if (r.status === 200 && j && j.data) return { state: 'ok', detail: '' };
    const detail = j && j.errors && j.errors[0] && j.errors[0].detail ? String(j.errors[0].detail) : '';
    if (/no account|could not be found|credentials/i.test(detail)) return { state: 'bad', detail };
    return { state: 'unknown', detail: detail || 'HTTP ' + r.status };
  }

  async checkKatabump(serverId, email, password) {
    try {
      const idents = [serverId];
      if (email) {
        idents.push(email);
        if (email.includes('@') && email.split('@')[0]) idents.push(email.split('@')[0]);
      }
      let last = { state: 'unknown', detail: '' };
      for (const id of idents) {
        last = await this.kbTryLogin(id, password);
        if (last.state !== 'bad') return last;
      }
      return last;
    } catch (e) {
      return { state: 'unknown', detail: e.message };
    }
  }

  async runSetup(o) {
    const token = o.token;

    this.step('login', 'running');
    const kb = (o.serverId && o.password) ? await this.checkKatabump(o.serverId, o.email, o.password) : { state: 'skip', detail: '' };
    if (kb.state === 'bad') {
      throw new UserError('آیدی سرور یا رمز سرور اشتباه است. با همان آیدی و رمزی که در صفحه‌ی ورود control.katabump.com می‌زنی دوباره وارد کن. (پاسخ سایت: ' + kb.detail + ')');
    }
    this.step('login', 'done', kb.state === 'skip' ? 'رد شد (اختیاری)' : kb.state === 'ok' ? 'آیدی و رمز درست است' : 'تست قطعی نشد؛ ادامه داده شد');

    this.step('auth', 'running');
    let me;
    const AUTH_TRIES = Number(process.env.GITHUB_SETUP_RETRIES) || 4;
    for (let i = 0; ; i++) {
      try { me = await this.gh('GET', '/user', null, token); break; }
      catch (e) {
        if (e && e.ghConnect && i < AUTH_TRIES - 1) {
          this.ghNote(`GitHub در دسترس نبود؛ تلاش خودکار ${i + 2} از ${AUTH_TRIES} تا چند ثانیه‌ی دیگر...`);
          await sleep(15000);
          continue;
        }
        throw e;
      }
    }
    if (!me.ok) throw this.explain(me, 'بررسی توکن');
    const owner = me.data.login;
    const scopesHeader = me.headers.get('x-oauth-scopes');
    if (scopesHeader !== null) {
      const list = scopesHeader.split(',').map((s) => s.trim());
      if (!list.includes('repo')) throw new UserError('توکن scope «repo» ندارد.');
      if (!list.includes('workflow')) throw new UserError('توکن scope «workflow» ندارد.');
    }
    this.step('auth', 'done', '@' + owner);

    this.step('repo', 'running');
    let r = await this.gh('GET', `/repos/${owner}/${o.repo}`, null, token);
    let created = false;
    if (r.status === 404) {
      r = await this.gh('POST', '/user/repos', {
        name: o.repo, private: true, auto_init: true,
        description: 'Katabump auto-renew (Parham Confing panel)'
      }, token);
      if (!r.ok) throw this.explain(r, 'ساخت ریپو');
      created = true;
      await sleep(2000);
    } else if (!r.ok) {
      throw this.explain(r, 'خواندن ریپو');
    }
    const branch = (r.data && r.data.default_branch) || 'main';
    this.step('repo', 'done', `${owner}/${o.repo}${created ? ' (ساخته شد)' : ' (از قبل بود)'}`);

    this.step('secrets', 'running');
    const pk = await this.gh('GET', `/repos/${owner}/${o.repo}/actions/secrets/public-key`, null, token);
    if (!pk.ok) throw this.explain(pk, 'کلید عمومی Secrets');
    const seal = await this.sealer(pk.data.key);
    const secrets = { KATABUMP_PASSWORD: o.password, SERVER_ID: o.serverId, KATABUMP_EMAIL: o.email, KATABUMP_ACCOUNT_PASSWORD: o.accountPassword, KATABUMP_COOKIES: o.cookies };
    const entries = Object.entries(secrets).filter(([, value]) => value);
    const puts = await Promise.all(entries.map(async ([name, value]) => ({
      name,
      put: await this.gh('PUT', `/repos/${owner}/${o.repo}/actions/secrets/${name}`, {
        encrypted_value: seal(value), key_id: pk.data.key_id
      }, token)
    })));
    for (const { name, put } of puts) {
      if (![201, 204].includes(put.status)) throw this.explain(put, 'ذخیره ' + name);
    }
    this.step('secrets', 'done', entries.length + ' Secret');

    this.step('files', 'running');
    const nowUtc = new Date();
    const cron = `${nowUtc.getUTCMinutes()} ${nowUtc.getUTCHours()} * * *`;
    const yml = RENEW_YML_TEMPLATE.replace('__CRON__', cron);
    const a = await this.putFile(owner, o.repo, branch, 'renew.py', RENEW_PY, 'Add renew script', token);
    const b = await this.putFile(owner, o.repo, branch, '.github/workflows/renew.yml', yml, 'Add auto-renew workflow', token);
    await this.putFile(owner, o.repo, branch, '.github/workflows/watchdog.yml', WATCHDOG_YML, 'Add power watchdog workflow', token);
    this.step('files', 'done', `${a}, ${b}`);

    this.data = {
      token, owner, repo: o.repo, branch, serverId: o.serverId,
      schedule: o.schedule, cron, connectedAt: new Date().toISOString()
    };
    this.save();

    this.step('run', 'done', 'تمدید از فردا شروع می‌شود');
    try {
      const arx = Extras.autorenew;
      if (arx) { arx.cfg.nextRunAt = Date.now() + 24 * 3600e3; arx.saveCfg(); }
    } catch {}

    this.cache = null;
    this.job.running = false;
    this.job.done = true;
    Events.push('success', `Unlimited enabled: ${owner}/${o.repo}`);
  }

  async run() {
    if (!this.isConnected()) throw new UserError('ابتدا نامحدود را فعال کن.', 409);
    await this.dispatch(this.data.owner, this.data.repo, this.data.branch || 'main');
    this.cache = null;
    Events.push('info', 'Manual renew run dispatched');
    return true;
  }

  async status(force) {
    if (!this.isConnected()) return { connected: false, defaults: this.defaults(), job: this.jobSnapshot() };
    if (!force && this.cache && Date.now() - this.cache.t < 15000) {
      return { ...this.cache.v, job: this.jobSnapshot() };
    }
    const d = this.data;
    const out = {
      connected: true,
      owner: d.owner, repo: d.repo,
      repoUrl: `https://github.com/${d.owner}/${d.repo}`,
      schedule: d.schedule,
      scheduleLabel: 'روزانه (هر ۲۴ ساعت از زمان فعال‌سازی)',
      serverId: d.serverId,
      connectedAt: d.connectedAt,
      tokenMasked: this.mask(d.token),
      runs: [], lastOk: null, tokenInvalid: false, error: null
    };
    try {
      const r = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml/runs?per_page=8`);
      if (r.status === 401) out.tokenInvalid = true;
      else if (r.ok && r.data && Array.isArray(r.data.workflow_runs)) {
        out.runs = r.data.workflow_runs.map((w) => ({
          id: w.id, status: w.status, conclusion: w.conclusion, event: w.event,
          createdAt: w.created_at, url: w.html_url
        }));
        const ok = out.runs.find((w) => w.conclusion === 'success');
        out.lastOk = ok ? ok.createdAt : null;
        const live = out.runs.find((w) => w.status !== 'completed');
        if (live) {
          try {
            const jr = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/runs/${live.id}/jobs`);
            const steps = (jr.ok && jr.data && jr.data.jobs && jr.data.jobs[0] && jr.data.jobs[0].steps) || [];
            const cur = steps.find((x) => x.status === 'in_progress') || steps.find((x) => x.status === 'queued');
            if (cur) out.liveStep = cur.name;
          } catch (e) {}
        }
      } else if (!r.ok) out.error = this.explain(r, 'وضعیت اجراها').message;
    } catch (e) { out.error = e.message; }
    this.cache = { t: Date.now(), v: out };
    return { ...out, job: this.jobSnapshot() };
  }

  async disconnect() {
    if (!this.isConnected()) return true;
    const d = this.data;
    try {
      const w = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml`);
      if (w.ok && w.data && w.data.id) await this.gh('PUT', `/repos/${d.owner}/${d.repo}/actions/workflows/${w.data.id}/disable`);
    } catch {}
    this.data = null;
    this.cache = null;
    try { fs.unlinkSync(this.file); } catch {}
    Events.push('info', 'Unlimited disconnected');
    return true;
  }

  bootstrap() {
    const c = (this.config && this.config.unlimited) || {};
    const env = process.env;
    const token = c.githubToken || env.GITHUB_TOKEN || '';
    const email = c.katabumpEmail || env.KATABUMP_EMAIL || '';
    const password = c.katabumpPassword || env.KATABUMP_PASSWORD || '';
    const accountPassword = c.katabumpAccountPassword || env.KATABUMP_ACCOUNT_PASSWORD || '';
    const serverId = this.defaults().serverId;
    if (!c.autoSetup || this.isConnected()) return;
    if (!(token && ((password && serverId) || (email && accountPassword)))) {
      Logger.warn('Unlimited autoSetup is on, but githubToken / katabumpEmail / katabumpPassword / serverId is missing.');
      return;
    }
    try {
      this.startSetup({ token, email, password, accountPassword, serverId, repo: c.repo, schedule: c.schedule });
    } catch (e) { Logger.warn('Unlimited autoSetup could not start (check githubToken, katabumpEmail, katabumpPassword and serverId).'); }
  }
}

const SecretBox = {
  key: null,
  init(dataDir) {
    if (this.key) return;
    let master = process.env.PANEL_SECRET || '';
    if (!master) {
      const f = path.join(dataDir, 'secret.key');
      try { master = fs.readFileSync(f, 'utf8').trim(); } catch {}
      if (!master || master.length < 32) {
        master = crypto.randomBytes(32).toString('base64');
        try {
          fs.mkdirSync(dataDir, { recursive: true });
          fs.writeFileSync(f, master + '\n', { mode: 0o600 });
          try { fs.chmodSync(f, 0o600); } catch {}
        } catch (e) { Logger.warn('Could not save secret.key: ' + e.message); }
      }
    }
    this.key = crypto.scryptSync(master, 'parham-confing/secretbox/v1', 32);
  },
  seal(plain) {
    const iv = crypto.randomBytes(12);
    const c = crypto.createCipheriv('aes-256-gcm', this.key, iv);
    const ct = Buffer.concat([c.update(String(plain), 'utf8'), c.final()]);
    return 'enc:v1:' + [iv, c.getAuthTag(), ct].map((b) => b.toString('base64')).join(':');
  },
  open(text) {
    const s = String(text || '');
    if (!s.startsWith('enc:v1:')) return { plain: s, legacy: true };
    try {
      const [iv, tag, ct] = s.slice(7).split(':').map((x) => Buffer.from(x, 'base64'));
      const d = crypto.createDecipheriv('aes-256-gcm', this.key, iv);
      d.setAuthTag(tag);
      return { plain: Buffer.concat([d.update(ct), d.final()]).toString('utf8'), legacy: false };
    } catch { return null; }
  }
};

const AR = {
  POLL_MS: Number(process.env.AR_POLL_MS) || 10000,
  TICK_MS: Number(process.env.AR_TICK_MS) || 30000,
  START_MS: Number(process.env.AR_START_MS) || 20000,
  START_WAIT_MS: Number(process.env.AR_START_WAIT_MS) || 120000,
  RUN_WAIT_MS: Number(process.env.AR_RUN_WAIT_MS) || 16 * 60 * 1000,
  FAIL_COOLDOWN_MS: Number(process.env.AR_FAIL_COOLDOWN_MS) || 60 * 60 * 1000,
  MAX_LOGS: 300
};
const AR_INTERVAL_MS = { six_hours: 6 * 3600e3, daily: 24 * 3600e3, three_days: 72 * 3600e3 };
const arScrub = (s) => String(s == null ? '' : s)
  .replace(/\b(gh[pousr]_[A-Za-z0-9_]{10,}|github_pat_[A-Za-z0-9_]{10,})\b/g, '[redacted]')
  .replace(/\x1b\[[0-9;]*m/g, '').slice(0, 750);

class ArFail extends Error {
  constructor(message, retryable, extra) {
    super(message);
    this.retryable = retryable !== false;
    Object.assign(this, extra || {});
  }
}

const AUTH_FATAL = new Set(['MISSING_EMAIL', 'MISSING_PASSWORD', 'MISSING_SERVER_ID', 'INVALID_EMAIL_FORMAT', 'INVALID_SERVER_ID', 'INVALID_CREDENTIALS']);

class AutoRenew {
  constructor(um, paths) {
    this.um = um;
    this.cfgFile = path.join(paths.dataDir, 'autorenew.json');
    this.logFile = path.join(paths.dataDir, 'autorenew-log.json');
    this.cfg = { enabled: true, retries: 3, retryDelaySec: 60, nextRunAt: 0, lastRunAt: 0 };
    this.logs = [];
    this.current = null;
    this.timer = null;
    this.lastSync = 0;
    try { Object.assign(this.cfg, JSON.parse(fs.readFileSync(this.cfgFile, 'utf8'))); } catch {}
    try {
      const l = JSON.parse(fs.readFileSync(this.logFile, 'utf8'));
      if (Array.isArray(l)) this.logs = l.filter((x) => x && x.trigger !== 'settings' && !(x.service === 'github' && x.status !== 'failed')).slice(-AR.MAX_LOGS);
    } catch {}
  }

  writeJson(file, obj) {
    try {
      const tmp = file + '.tmp';
      fs.writeFileSync(tmp, JSON.stringify(obj), { mode: 0o600 });
      fs.renameSync(tmp, file);
    } catch (e) { Logger.warn('[AutoRenew] Could not write ' + path.basename(file) + ': ' + e.message); }
  }
  saveCfg() { this.writeJson(this.cfgFile, this.cfg); }
  saveLogs() { this.writeJson(this.logFile, this.logs); }

  intervalKey() {
    const k = this.um.data && this.um.data.schedule;
    return AR_INTERVAL_MS[k] ? k : 'six_hours';
  }
  intervalMs() { return AR_INTERVAL_MS[this.intervalKey()]; }

  start() {
    if (this.timer) return;
    this.timer = setInterval(() => { this.tick().catch((e) => Logger.warn('[AutoRenew] Tick failed: ' + e.message)); }, AR.TICK_MS);
    if (this.timer.unref) this.timer.unref();
    const first = setTimeout(() => { this.tick().catch(() => {}); }, AR.START_MS);
    if (first.unref) first.unref();
    Logger.info('[AutoRenew] Scheduler started (checks every ' + Math.round(AR.TICK_MS / 1000) + 's)');
  }

  addLog(e) {
    const entry = {
      id: crypto.randomBytes(4).toString('hex'),
      t: Date.now(),
      ...e,
      message: arScrub(e.message)
    };
    this.logs.push(entry);
    if (e.t) this.logs.sort((a, b) => a.t - b.t);
    if (this.logs.length > AR.MAX_LOGS) this.logs.splice(0, this.logs.length - AR.MAX_LOGS);
    this.saveLogs();
    const label = entry.service === 'github' ? 'GitHub' : 'Katabump';
    const att = entry.maxAttempts > 1 ? ` (attempt ${entry.attempt}/${entry.maxAttempts})` : '';
    const line = `[AutoRenew] ${label}${att}: ${String(entry.status).toUpperCase()} - ${entry.message}`;
    if (entry.status === 'failed') Logger.error(line);
    else if (entry.status === 'warning') Logger.warn(line);
    else if (entry.status === 'success') Logger.success(line);
    else Logger.info(line);
    return entry;
  }

  async gh(method, p, body) {
    try { return await this.um.gh(method, p, body); } catch (e) {
      throw new ArFail(e && e.status === 504 ? 'GitHub request timed out' : 'Could not reach GitHub', true);
    }
  }

  ghFail(r, what) {
    const msg = r && r.data && r.data.message ? String(r.data.message) : '';
    if (r.status === 401) return new ArFail('GitHub token is invalid or expired - reconnect Unlimited with a new token', false);
    if (r.status === 403 && /rate limit/i.test(msg)) return new ArFail('GitHub rate limit reached', true);
    if (r.status === 403) return new ArFail(`GitHub token lacks permission (${what}); scopes "repo" and "workflow" are required`, false);
    if (r.status === 404) return new ArFail(`${what} not found - check token scopes and the repository`, false);
    return new ArFail(`GitHub returned ${r.status} (${what})${msg ? ': ' + msg : ''}`, r.status >= 500 || r.status === 429);
  }

  asFail(e) {
    if (e instanceof ArFail) return e;
    return new ArFail('Unexpected error: ' + (e && e.message ? e.message : e), true);
  }

  async checkGithub() {
    const d = this.um.data;
    const me = await this.gh('GET', '/user');
    if (!me.ok) throw this.ghFail(me, 'token check');
    const notes = [];
    let level = 'success';
    const exp = me.headers && me.headers.get && me.headers.get('github-authentication-token-expiration');
    if (exp) {
      const ms = Date.parse(String(exp).replace(' UTC', 'Z').replace(' ', 'T'));
      if (Number.isFinite(ms)) {
        const days = Math.floor((ms - Date.now()) / 86400e3);
        if (days < 0) throw new ArFail('GitHub token has expired - reconnect Unlimited with a new token', false);
        if (days <= 7) { level = 'warning'; notes.push(`token expires in ${days} day(s) - create a new one and reconnect soon`); }
        else notes.push(`token valid, expires in ${days} days`);
      }
    } else notes.push('token valid');

    const w = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml`);
    if (w.status === 404) throw new ArFail('renew.yml workflow not found in the repository - reconnect Unlimited', false);
    if (!w.ok) throw this.ghFail(w, 'workflow lookup');
    if (w.data && w.data.state && w.data.state !== 'active') {
      const en = await this.gh('PUT', `/repos/${d.owner}/${d.repo}/actions/workflows/${w.data.id}/enable`);
      if (!(en.ok || en.status === 204)) throw this.ghFail(en, 'workflow enable');
      level = 'warning';
      notes.push(`workflow was ${w.data.state}, re-enabled`);
    } else notes.push('workflow active');

    try {
      const r = await this.um.putFile(d.owner, d.repo, d.branch || 'main', 'renew.py', RENEW_PY, 'Update renew script');
      if (r === 'ok') notes.push('renew script updated');
      await this.um.putFile(d.owner, d.repo, d.branch || 'main', '.github/workflows/watchdog.yml', WATCHDOG_YML, 'Update power watchdog workflow');
      const sch = UNLIMITED_SCHEDULES[d.schedule] || UNLIMITED_SCHEDULES.six_hours;
      await this.um.putFile(d.owner, d.repo, d.branch || 'main', '.github/workflows/renew.yml', RENEW_YML_TEMPLATE.replace('__CRON__', d.cron || sch.cron), 'Update auto-renew workflow');
    } catch { notes.push('renew script sync skipped'); }

    return { level, message: notes.join('; ') };
  }

  async renewOnce(trigger, attempt) {
    const d = this.um.data;
    const base = `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml/runs`;
    const list = await this.gh('GET', `${base}?per_page=10`);
    if (!list.ok) throw this.ghFail(list, 'workflow runs');
    const runs = (list.data && list.data.workflow_runs) || [];
    const iv = this.intervalMs();
    const now = Date.now();

    let run = runs.find((r) => r.status !== 'completed' && now - Date.parse(r.created_at) < 30 * 60e3) || null;
    const attached = !!run;

    if (!run && trigger === 'schedule' && attempt === 1) {
      const lastDone = runs.find((r) => r.status === 'completed');
      if (lastDone && lastDone.conclusion === 'success' && now - Date.parse(lastDone.updated_at || lastDone.created_at) < iv * 0.9) {
        return {
          status: 'skipped',
          message: `Recent successful run #${lastDone.run_number} found; no new renewal needed yet`,
          runId: lastDone.id, runUrl: lastDone.html_url,
          nextAt: Math.max(Date.parse(lastDone.created_at) + iv, now + 5 * 60e3)
        };
      }
    }

    if (!run) {
      const since = now - 10000;
      const disp = await this.gh('POST', `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml/dispatches`, { ref: d.branch || 'main' });
      if (disp.status !== 204) throw this.ghFail(disp, 'workflow dispatch');
      this.current.phase = 'waiting for the workflow run to start';
      const until = Date.now() + AR.START_WAIT_MS;
      while (!run && Date.now() < until) {
        await sleep(Math.min(AR.POLL_MS, 4000));
        try {
          const l = await this.gh('GET', `${base}?event=workflow_dispatch&per_page=5`);
          if (l.ok) run = ((l.data && l.data.workflow_runs) || []).find((r) => Date.parse(r.created_at) >= since) || null;
        } catch {}
      }
      if (!run) throw new ArFail('Workflow run did not start in time', true);
    }

    this.current.runUrl = run.html_url;
    this.current.phase = 'waiting for the workflow run to finish';
    const until2 = Date.now() + AR.RUN_WAIT_MS;
    let cur = run;
    let errs = 0;
    while (cur.status !== 'completed') {
      if (Date.now() > until2) throw new ArFail('Timed out waiting for the workflow run to finish', true, { runId: run.id, runUrl: run.html_url });
      await sleep(AR.POLL_MS);
      try {
        const g = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/runs/${run.id}`);
        if (g.ok) { cur = g.data; errs = 0; }
        else if (g.status === 401) throw this.ghFail(g, 'run status');
        else if (++errs >= 5) throw this.ghFail(g, 'run status');
      } catch (e) {
        if (e instanceof ArFail && !e.retryable) throw e;
        if (++errs >= 5) throw this.asFail(e);
      }
    }
    const info = { runId: cur.id, runUrl: cur.html_url };
    const auth = await this.readAuth(cur.id);
    this.setAuth(auth);
    await this.readRenewNote(cur.id);
    if (cur.conclusion === 'success') {
      return { status: 'success', message: `Workflow run #${cur.run_number} succeeded${attached ? ' (attached to a run already in progress)' : ''}`, ...info };
    }
    if (auth && !auth.ok) {
      const why = `Katabump login invalid (${auth.code}): ${auth.reason}`;
      throw new ArFail(`Workflow run #${cur.run_number} ${cur.conclusion || 'failed'} - ${why}`, !AUTH_FATAL.has(auth.code), info);
    }
    throw new ArFail(`Workflow run #${cur.run_number} ${cur.conclusion || 'failed'} - open the run log for details`, true, info);
  }

  async readAuth(runId) {
    try {
      const d = this.um.data;
      const jobs = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/runs/${runId}/jobs?per_page=5`);
      if (!jobs.ok || !jobs.data) return null;
      for (const j of jobs.data.jobs || []) {
        const an = await this.gh('GET', `/repos/${d.owner}/${d.repo}/check-runs/${j.id}/annotations?per_page=50`);
        if (!an.ok || !Array.isArray(an.data)) continue;
        const hit = an.data.find((a) => a.title === 'KB_AUTH');
        if (!hit) continue;
        const parts = String(hit.message || '').split('|');
        const ok = parts[0] === 'valid';
        return {
          ok,
          code: parts[1] || (ok ? 'OK' : 'UNKNOWN'),
          reason: arScrub(parts.slice(2).join('|') || (ok ? 'Login succeeded' : 'Login failed')),
          t: Date.parse(j.completed_at || '') || Date.now()
        };
      }
    } catch {}
    return null;
  }

  async readRenewNote(runId) {
    try {
      const d = this.um.data;
      const jobs = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/runs/${runId}/jobs?per_page=5`);
      if (!jobs.ok || !jobs.data) return;
      for (const j of jobs.data.jobs || []) {
        const an = await this.gh('GET', `/repos/${d.owner}/${d.repo}/check-runs/${j.id}/annotations?per_page=50`);
        if (!an.ok || !Array.isArray(an.data)) continue;
        const hits = an.data.filter((a) => a.title === 'KB_RENEW');
        if (!hits.length) continue;
        const last = hits[hits.length - 1];
        const parts = String(last.message || '').split('|');
        const state = parts[0] || 'unknown';
        const text = state === 'clicked' ? 'گزینه Renew دیده شد و روی آن کلیک شد'
          : state === 'seen' ? 'گزینه Renew دیده شد'
          : state === 'missing' ? 'گزینه Renew هنوز نیامده (زمانش نرسیده)'
          : 'خطا در بررسی گزینه Renew';
        this.cfg.renew = { state, text, detail: arScrub(parts.slice(1).join('|')), t: Date.parse(j.completed_at || '') || Date.now() };
        this.saveCfg();
        return;
      }
    } catch {}
  }

  setAuth(a) {
    if (!a) return;
    this.cfg.auth = a;
    this.saveCfg();
  }

  async backoff(attempt) {
    const sec = Math.max(1, Number(this.cfg.retryDelaySec) || 60) * attempt;
    this.current.phase = `retrying in ${sec}s`;
    this.current.retryAt = Date.now() + sec * 1000;
    Logger.warn(`[AutoRenew] Retrying in ${sec}s (attempt ${attempt + 1} next)`);
    await sleep(sec * 1000);
    this.current.retryAt = 0;
  }

  async cycle(trigger) {
    const max = Math.min(5, Math.max(1, parseInt(this.cfg.retries, 10) || 3));
    const cycleId = crypto.randomBytes(3).toString('hex');
    this.current = { id: cycleId, trigger, startedAt: Date.now(), attempt: 0, max, phase: 'starting', runUrl: null, retryAt: 0 };
    Logger.info(`[AutoRenew] Cycle ${cycleId} started (trigger: ${trigger}, max attempts: ${max})`);
    this.addLog({ cycle: cycleId, trigger, service: 'katabump', attempt: 1, maxAttempts: 1, status: 'running', message: 'تمدید ران شد' });
    let ok = false, nextAt = 0, fatal = false;
    try {
      for (let attempt = 1; attempt <= max; attempt++) {
        this.current.attempt = attempt;
        const base = { cycle: cycleId, trigger, attempt, maxAttempts: max };

        this.current.phase = 'checking GitHub account';
        let t0 = Date.now();
        try {
          const g = await this.checkGithub();
          void g;
        } catch (e) {
          const f = this.asFail(e);
          this.addLog({ ...base, service: 'github', status: 'failed', message: f.message, durationMs: Date.now() - t0 });
          if (!f.retryable) { fatal = true; break; }
          if (attempt < max) { await this.backoff(attempt); continue; }
          break;
        }

        this.current.phase = 'renewing Katabump server';
        t0 = Date.now();
        try {
          const r = await this.renewOnce(trigger, attempt);
          this.addLog({ ...base, service: 'katabump', status: r.status, message: r.message, runId: r.runId, runUrl: r.runUrl, durationMs: Date.now() - t0 });
          ok = true; nextAt = r.nextAt || 0;
          break;
        } catch (e) {
          const f = this.asFail(e);
          this.addLog({ ...base, service: 'katabump', status: 'failed', message: f.message, runId: f.runId, runUrl: f.runUrl, durationMs: Date.now() - t0 });
          if (!f.retryable) { fatal = true; break; }
          if (attempt < max) await this.backoff(attempt);
        }
      }
    } catch (e) {
      Logger.error('[AutoRenew] Cycle crashed: ' + (e && e.message));
    } finally {
      const now = Date.now();
      const iv = this.intervalMs();
      this.cfg.lastRunAt = now;
      this.cfg.nextRunAt = ok ? (nextAt || now + iv) : (fatal ? now + iv : now + Math.min(iv, AR.FAIL_COOLDOWN_MS));
      this.saveCfg();
      Logger.info(`[AutoRenew] Cycle ${cycleId} finished: ${ok ? 'OK' : 'FAILED'}; next run in ${Math.round((this.cfg.nextRunAt - now) / 60000)} min`);
      this.current = null;
    }
  }

  async syncRemoteRuns() {
    this.lastSync = Date.now();
    if (!this.um.isConnected() || this.current) return;
    const d = this.um.data;
    const r = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/workflows/renew.yml/runs?per_page=20`);
    if (!r.ok || !r.data) return;
    const known = new Set(this.logs.map((l) => l.runId).filter(Boolean));
    const cutoff = Date.now() - 7 * 86400e3;
    const fresh = (r.data.workflow_runs || [])
      .filter((w) => w.status === 'completed' && !known.has(w.id) && Date.parse(w.created_at) >= cutoff)
      .reverse();
    let newestFailed = false;
    for (const w of fresh) {
      const okRun = w.conclusion === 'success';
      const skipped = w.conclusion === 'cancelled' || w.conclusion === 'skipped';
      const t = Date.parse(w.updated_at || w.created_at);
      this.addLog({
        t, cycle: '-', trigger: w.event === 'schedule' ? 'github-cron' : 'github-' + w.event,
        service: 'katabump', attempt: 1, maxAttempts: 1,
        status: okRun ? 'success' : skipped ? 'skipped' : 'failed',
        message: `Workflow run #${w.run_number} (${w.event}) ${w.conclusion || 'finished'}`,
        runId: w.id, runUrl: w.html_url,
        durationMs: Math.max(0, t - Date.parse(w.created_at))
      });
      newestFailed = !okRun && !skipped;
    }
    if (fresh.length) {
      const newest = fresh[fresh.length - 1];
      if (newest.conclusion !== 'cancelled' && newest.conclusion !== 'skipped') this.setAuth(await this.readAuth(newest.id));
    }
    if (newestFailed && this.cfg.enabled) {
      const at = Date.now() + Math.max(1, Number(this.cfg.retryDelaySec) || 60) * 1000;
      if (!this.cfg.nextRunAt || this.cfg.nextRunAt > at) {
        this.cfg.nextRunAt = at; this.saveCfg();
        Logger.warn('[AutoRenew] A GitHub-side run failed; a retry cycle has been scheduled');
      }
    }
  }

  async tick() {
    if (!this.um.isConnected()) {
      if (this.cfg.nextRunAt) { this.cfg.nextRunAt = 0; this.saveCfg(); }
      return;
    }
    if (this.current) return;
    if (Date.now() - this.lastSync > 5 * 60e3) { try { await this.syncRemoteRuns(); } catch {} }
    if (!this.cfg.enabled || this.current) return;
    if (!this.cfg.nextRunAt) { this.cfg.nextRunAt = (Date.parse(this.um.data.connectedAt) || Date.now()) + 24 * 3600e3; this.saveCfg(); }
    if (Date.now() >= this.cfg.nextRunAt) this.cycle('schedule').catch(() => {});
  }

  manualRun() {
    if (!this.um.isConnected()) throw new UserError('Connect Unlimited first.', 409);
    if (this.current) throw new UserError('A renewal cycle is already running.', 409);
    const r = this.cfg.renew;
    if (r && Date.now() - (r.t || 0) < 24 * 3600e3 && (r.state === 'clicked' || r.state === 'seen')) {
      const at = Date.now() + 24 * 3600e3;
      if (!this.cfg.nextRunAt || this.cfg.nextRunAt > at) { this.cfg.nextRunAt = at; this.saveCfg(); }
      const message = 'اکانت در وضعیت تمدید است و تا ۲۴ ساعت آینده اجرا می‌شود';
      this.addLog({ cycle: '-', trigger: 'manual', service: 'katabump', attempt: 1, maxAttempts: 1, status: 'warning', message });
      return { ran: false, message };
    }
    this.cycle('manual').catch(() => {});
    return { ran: true, message: 'تمدید ران شد' };
  }

  async workflowStates() {
    if (!this.um.isConnected()) return [];
    const d = this.um.data;
    const out = [];
    for (const [file, name] of [['renew.yml', 'Auto Renew'], ['watchdog.yml', 'Power Watchdog']]) {
      try {
        const r = await this.gh('GET', `/repos/${d.owner}/${d.repo}/actions/workflows/${file}/runs?per_page=1`);
        const w = r.ok && r.data && r.data.workflow_runs && r.data.workflow_runs[0];
        if (!w) continue;
        const state = w.status !== 'completed' ? 'running'
          : w.conclusion === 'success' ? 'success'
          : (w.conclusion === 'cancelled' || w.conclusion === 'skipped') ? 'running' : 'failed';
        out.push({ name, file, state, t: Date.parse(w.updated_at || w.created_at) || 0, url: w.html_url });
      } catch {}
    }
    return out;
  }

  runNow(trigger) {
    if (!this.um.isConnected()) throw new UserError('Connect Unlimited first.', 409);
    if (this.current) throw new UserError('A renewal cycle is already running.', 409);
    this.cycle(trigger || 'manual').catch(() => {});
  }

  setConfig(b) {
    const was = this.cfg.enabled;
    if (b.enabled !== undefined) this.cfg.enabled = !!b.enabled;
    if (b.retries !== undefined) {
      const n = parseInt(b.retries, 10);
      if (!(n >= 1 && n <= 5)) throw new UserError('Attempts must be between 1 and 5.');
      this.cfg.retries = n;
    }
    if (b.retryDelaySec !== undefined) {
      const n = parseInt(b.retryDelaySec, 10);
      if (!(n >= 1 && n <= 3600)) throw new UserError('Retry delay must be between 1 and 3600 seconds.');
      this.cfg.retryDelaySec = n;
    }
    if (b.interval !== undefined) {
      if (!AR_INTERVAL_MS[b.interval]) throw new UserError('Unknown schedule.');
      if (this.um.isConnected() && this.um.data.schedule !== b.interval) {
        this.um.data.schedule = b.interval;
        this.um.save();
        this.um.cache = null;
        const at = Date.now() + AR_INTERVAL_MS[b.interval];
        this.cfg.nextRunAt = this.cfg.nextRunAt ? Math.min(this.cfg.nextRunAt, at) : at;
        this.syncWorkflowCron().catch(() => {});
      }
    }
    if (this.cfg.enabled && !was) this.cfg.nextRunAt = Date.now() + 24 * 3600e3;
    this.saveCfg();
    Logger.info(`[AutoRenew] Settings saved (enabled: ${this.cfg.enabled}, schedule: ${this.intervalKey()}, attempts: ${this.cfg.retries})`);
  }

  async syncWorkflowCron() {
    const d = this.um.data;
    if (!d) return;
    const t0 = Date.now();
    try {
      const yml = RENEW_YML_TEMPLATE.replace('__CRON__', d.cron || UNLIMITED_SCHEDULES[this.intervalKey()].cron);
      const r = await this.um.putFile(d.owner, d.repo, d.branch || 'main', '.github/workflows/renew.yml', yml, 'Update auto-renew schedule');
    } catch (e) {
    }
  }

  clearLogs() { this.logs = []; this.saveLogs(); Logger.info('[AutoRenew] Log cleared'); }

  snapshot() {
    const connected = this.um.isConnected();
    const k = this.logs.filter((l) => l.service === 'katabump' && l.status !== 'skipped');
    const success = k.filter((l) => l.status === 'success').length;
    const failed = k.filter((l) => l.status === 'failed').length;
    const last = k[k.length - 1] || null;
    const lastOk = [...k].reverse().find((l) => l.status === 'success') || null;
    const gh = [...this.logs].reverse().find((l) => l.service === 'github') || null;
    const pick = (l) => l && { t: l.t, status: l.status, message: l.message, trigger: l.trigger };
    return {
      connected,
      enabled: !!this.cfg.enabled,
      interval: this.intervalKey(),
      retries: this.cfg.retries,
      retryDelaySec: this.cfg.retryDelaySec,
      nextRunAt: connected && this.cfg.enabled ? this.cfg.nextRunAt : 0,
      running: !!this.current,
      current: this.current ? { ...this.current } : null,
      stats: { success, failed, total: success + failed, rate: success + failed ? Math.round((success / (success + failed)) * 100) : 0 },
      last: pick(last),
      lastSuccessAt: lastOk ? lastOk.t : null,
      github: pick(gh),
      auth: this.cfg.auth || null,
      renew: this.cfg.renew || null
    };
  }
}

const Extras = {
  inited: false,
  admin: null,
  unlimited: null,
  autorenew: null,

  init(config, stateManager) {
    if (this.inited) return;
    this.inited = true;
    DiskGuard.start(config.paths);
    Stats.init(config.paths);
    this.admin = new AdminAuth(config, config.paths);
    this.unlimited = new UnlimitedManager(config, config.paths);
    this.autorenew = new AutoRenew(this.unlimited, config.paths);
    this.autorenew.start();
    const t = setTimeout(() => { try { this.unlimited.bootstrap(); } catch {} }, 4000);
    if (t.unref) t.unref();
  },

  printHint() { },

  routes(app, ctx) {
    const { config, stateManager, authMiddleware, panelPath } = ctx;
    this.init(config, stateManager);
    const admin = this.admin.middleware;
    const open = authMiddleware;
    const un = this.unlimited;
    const ar = this.autorenew;
    app.use((req, res, next) => { try { if (this.admin.valid(req)) HostDetect.observe(req, config); } catch {} next(); });
    const router = express.Router();
    router.use(express.json({ limit: '256kb' }));

    const wrap = (fn) => async (req, res) => {
      try { await fn(req, res); } catch (e) {
        const status = e && e.status ? e.status : 500;
        if (!(e instanceof UserError)) Events.push('error', 'API error: ' + (e && e.message));
        res.status(status).json({ ok: false, error: e instanceof UserError ? e.message : 'خطای داخلی سرور' });
      }
    };

    router.get('/ping', (req, res) => res.json({ ok: true, t: Date.now() }));
    router.get('/stats', open, (req, res) => res.json({ ok: true, ...Stats.snapshot() }));
    router.post('/stats/reset', admin, (req, res) => { Stats.reset(); res.json({ ok: true }); });
    router.get('/events', open, (req, res) => res.json({ ok: true, items: Events.items.slice(-120) }));
    router.get('/host', open, (req, res) => res.json({ ok: true, ...HostDetect.report(req, config, null) }));
    router.post('/host', admin, wrap(async (req, res) => { const o = HostDetect.setOverride(config, req.body || {}); Events.push('info', 'Host override: ' + o.host + ':' + o.port); res.json({ ok: true, override: o, ...HostDetect.report(req, config, null) }); }));
    router.delete('/host', admin, (req, res) => { HostDetect.clear(); res.json({ ok: true, ...HostDetect.report(req, config, null) }); });
    router.get('/admin/check', admin, (req, res) => res.json({ ok: true, mode: this.admin.fromPanelToken ? 'panelToken' : 'adminKey' }));

    router.get('/katabump/verification', admin, (req, res) => res.json({
      ok: true,
      verified: false,
      supported: false,
      method: 'manual',
      message: 'ورود Katabump از این برنامه قابل تأیید خودکار نیست؛ API رسمی احراز هویت در این نسخه در دسترس نیست. برای جلوگیری از تیک جعلی، وضعیت تأییدنشده باقی می‌ماند.',
      loginUrl: 'https://control.katabump.com'
    }));

    router.get('/unlimited/status', admin, wrap(async (req, res) => {
      res.json({ ok: true, ...(await un.status(req.query.force === '1')), katabumpVerification: {
        verified: false,
        supported: false,
        message: 'اتصال GitHub جداگانه بررسی می‌شود؛ این وضعیت به معنی ورود تأییدشده به Katabump نیست.'
      }});
    }));
    router.get('/unlimited/job', admin, (req, res) => res.json({ ok: true, job: un.jobSnapshot() }));
    router.post('/unlimited/connect', admin, wrap(async (req, res) => {
      const job = un.startSetup(req.body || {});
      res.json({ ok: true, job });
    }));
    router.post('/unlimited/run', admin, wrap(async (req, res) => {
      res.json({ ok: true, ...ar.manualRun() });
    }));
    router.post('/unlimited/disconnect', admin, wrap(async (req, res) => {
      await un.disconnect();
      res.json({ ok: true });
    }));

    router.get('/autorenew/status', admin, (req, res) => res.json({ ok: true, ...ar.snapshot() }));
    router.get('/autorenew/logs', admin, (req, res) => {
      const n = Math.min(300, Math.max(1, parseInt(req.query.limit, 10) || 100));
      res.json({ ok: true, items: ar.logs.slice(-n).reverse() });
    });
    router.post('/autorenew/run', admin, wrap(async (req, res) => { const mr = ar.manualRun(); res.json({ ok: true, ...ar.snapshot(), ...mr }); }));
    router.get('/autorenew/workflows', admin, wrap(async (req, res) => { res.json({ ok: true, items: await ar.workflowStates() }); }));
    router.post('/autorenew/config', admin, wrap(async (req, res) => { ar.setConfig(req.body || {}); res.json({ ok: true, ...ar.snapshot() }); }));
    router.delete('/autorenew/logs', admin, (req, res) => { ar.clearLogs(); res.json({ ok: true }); });

    router.get('/backup', admin, (req, res) => {
      const s = stateManager.state || {};
      const snapshot = {};
      for (const k of Object.keys(s)) {
        if (!/^[A-Za-z][A-Za-z0-9_]{0,80}$/.test(k) || ['__proto__', 'prototype', 'constructor'].includes(k)) continue;
        const v = s[k];
        if (typeof v === 'string' && v.length <= 4096) snapshot[k] = v;
        else if (typeof v === 'number' && Number.isFinite(v)) snapshot[k] = v;
        else if (typeof v === 'boolean' || v === null) snapshot[k] = v;
      }
      const out = { kind: 'parham-confing-backup', version: 2, createdAt: new Date().toISOString(), state: snapshot };
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Content-Disposition', 'attachment; filename="parham-confing-settings-backup.json"');
      res.setHeader('Cache-Control', 'no-store');
      res.send(JSON.stringify(out, null, 2));
    });
    router.post('/restore', admin, wrap(async (req, res) => {
      const b = req.body;
      if (!b || b.kind !== 'parham-confing-backup' || !b.state || typeof b.state !== 'object' || Array.isArray(b.state) || ![1, 2].includes(Number(b.version))) {
        throw new UserError('فایل تنظیمات معتبر نیست یا نسخه آن پشتیبانی نمی‌شود.');
      }
      const current = stateManager.state || {};
      const sensitive = new Set(['__proto__', 'prototype', 'constructor']);
      let n = 0;
      for (const [k, v] of Object.entries(b.state)) {
        if (!Object.prototype.hasOwnProperty.call(current, k) || sensitive.has(k) || !/^[A-Za-z][A-Za-z0-9_]{0,80}$/.test(k)) continue;
        if (typeof v === 'string' && v.length <= 4096) { current[k] = v; n++; }
        else if (typeof v === 'number' && Number.isFinite(v)) { current[k] = v; n++; }
        else if (typeof v === 'boolean' || v === null) { current[k] = v; n++; }
      }
      if (!n) throw new UserError('هیچ کلید سازگار با نسخه فعلی در فایل پیدا نشد.');
      stateManager.save();
      Events.push('success', `Settings restored (${n} fields)`);
      res.json({ ok: true, restored: n, note: 'تنظیمات سازگار بازیابی شد؛ برای اعمال همه تغییرات، سرور را از پنل Katabump Restart کن.' });
    }));

    UserStore.init(stateManager && stateManager.paths && stateManager.paths.stateFile ? path.dirname(stateManager.paths.stateFile) : process.cwd());
    const uHost = (req) => config.forceHost || config.domain || String(req.headers.host || '127.0.0.1').split(':')[0];
    const nodeCache = { host: '', t: 0, v: null };
    const uNodes = (req) => {
      const h = uHost(req);
      const now = Date.now();
      if (nodeCache.v && nodeCache.host === h && now - nodeCache.t < 60000) return nodeCache.v;
      nodeCache.v = new LinkGenerator(config, stateManager.state, h).getAllNodes({ compat: 'full', allowLocalHostLinks: true });
      nodeCache.host = h;
      nodeCache.t = now;
      return nodeCache.v;
    };
    const uLinks = (nodes, u) => nodes.filter(n => !u.proto || n.type === u.proto).map(n => ({ name: n.name, type: n.type, metered: METERED_TYPES.test(n.type), uri: UserStore.tagUri(n.uri, u, n.type) }));
    const uView = (req, u, nodes) => UserStore.view(u, uLinks(nodes || uNodes(req), u));
    router.get('/users', open, wrap(async (req, res) => {
      const nodes = uNodes(req);
      res.json({ ok: true, now: Date.now(), settings: UserStore.data.settings, users: UserStore.data.users.map(u => uView(req, u, nodes)) });
    }));
    router.post('/users/settings', open, wrap(async (req, res) => {
      UserStore.data.settings.requireUser = !!(req.body && req.body.requireUser); UserStore.dirty = true; UserStore.flush();
      res.json({ ok: true, settings: UserStore.data.settings });
    }));
    router.post('/users', open, wrap(async (req, res) => {
      const body = req.body || {};
      const wantProto = String(body.proto || '').trim();
      if (wantProto && !uNodes(req).some(n => n.type === wantProto)) throw new UserError('این پروتکل روی این سرور فعال نیست.');
      const u = UserStore.create(body);
      Events.push('success', 'User created: ' + u.name);
      res.json({ ok: true, user: uView(req, u) });
    }));
    router.post('/users/:id/toggle', open, wrap(async (req, res) => {
      const u = UserStore.get(req.params.id); if (!u) throw new UserError('کاربر پیدا نشد.');
      u.enabled = !u.enabled; UserStore.dirty = true; UserStore.flush();
      res.json({ ok: true, user: uView(req, u) });
    }));
    router.post('/users/:id/reset', open, wrap(async (req, res) => {
      const u = UserStore.get(req.params.id); if (!u) throw new UserError('کاربر پیدا نشد.');
      u.used = 0; u.up = 0; UserStore.dirty = true; UserStore.flush();
      res.json({ ok: true, user: uView(req, u) });
    }));
    router.delete('/users/:id', open, wrap(async (req, res) => {
      const u = UserStore.remove(req.params.id);
      Events.push('info', 'User deleted: ' + u.name);
      res.json({ ok: true });
    }));
    ConfigStore.init(stateManager && stateManager.paths && stateManager.paths.stateFile ? path.dirname(stateManager.paths.stateFile) : process.cwd());
    const cfgNodes = uNodes;
    router.get('/configs', open, wrap(async (req, res) => {
      const nodes = cfgNodes(req);
      res.json({ ok: true, protocols: ConfigStore.protocols(nodes), configs: ConfigStore.data.configs.map(c => ConfigStore.view(c, nodes)) });
    }));
    router.post('/configs', open, wrap(async (req, res) => {
      const nodes = cfgNodes(req);
      const c = ConfigStore.create(req.body || {}, nodes);
      Events.push('success', 'Config created: ' + c.name + ' (' + c.type + ')');
      res.json({ ok: true, config: ConfigStore.view(c, nodes) });
    }));
    router.delete('/configs/:id', open, wrap(async (req, res) => {
      const c = ConfigStore.remove(String(req.params.id || ''));
      Events.push('info', 'Config deleted: ' + c.name);
      res.json({ ok: true });
    }));
    const subNodeFor = (n, u) => {
      const c = Object.assign({}, n);
      c.uri = UserStore.tagUri(n.uri, u, n.type);
      if (METERED_TYPES.test(n.type)) {
        const add = (p) => String(p) + (String(p).includes('?') ? '&' : '?') + 'u=' + u.id;
        if (Array.isArray(n.singboxOutbound)) c.singboxOutbound = n.singboxOutbound.map(o => (o && o.transport && o.transport.path) ? Object.assign({}, o, { transport: Object.assign({}, o.transport, { path: add(o.transport.path) }) }) : o);
        if (n.clash) {
          const cl = Object.assign({}, n.clash);
          if (cl['ws-opts']) cl['ws-opts'] = Object.assign({}, cl['ws-opts'], { path: add(cl['ws-opts'].path) });
          if (cl['httpupgrade-opts']) cl['httpupgrade-opts'] = Object.assign({}, cl['httpupgrade-opts'], { path: add(cl['httpupgrade-opts'].path) });
          c.clash = cl;
        }
      }
      return c;
    };
    app.get(`/${panelPath}/u/:id/sub`, (req, res) => {
      const u = UserStore.get(String(req.params.id || ''));
      if (!u) return res.status(404).type('text').send('not found');
      const st = UserStore.state(u);
      const nodes = st === 'active' ? uNodes(req).filter(n => !u.proto || n.type === u.proto) : [];
      const tagged = nodes.map(n => subNodeFor(n, u));
      const used = Math.max(0, Math.round(u.used || 0));
      const up = Math.min(used, Math.max(0, Math.floor(u.up || 0)));
      const down = Math.max(0, used - up);
      const brand = config.brand || 'Parham Confing';
      const ua = String(req.headers['user-agent'] || '');
      const accept = String(req.headers.accept || '');
      const fmt = String(req.query.format || '').toLowerCase();
      const isApp = /v2ray|v2box|happ|sing-box|singbox|hiddify|streisand|shadowrocket|clash|mihomo|stash|incy|nekobox|nekoray|karing|okhttp|cfnetwork|dalvik|curl|wget|quantumult|loon|surge|\b(SFA|SFI|SFM|SFT)\//i.test(ua);
      const wantsPage = !req.query.raw && !fmt && (req.query.page === '1' || (/text\/html/i.test(accept) && /^Mozilla\//i.test(ua) && !isApp));

      res.setHeader('Cache-Control', 'no-store');
      res.setHeader('Profile-Update-Interval', '12');
      res.setHeader('Subscription-Userinfo', `upload=${up}; download=${down}; total=${u.limitBytes || 0}; expire=${u.expireAt ? Math.floor(u.expireAt / 1000) : 0}`);
      res.setHeader('Profile-Title', 'base64:' + Buffer.from(u.name).toString('base64'));
      res.setHeader('Content-Disposition', `inline; filename="${encodeURIComponent(u.name)}"`);
      res.setHeader('Support-Url', config.channelUrl || 'https://t.me/parham_ste01');

      if (wantsPage) {
        const links = tagged.map(n => Object.assign(subDescribe(n.uri), { uri: n.uri }));
        return res.type('html').send(subPageHtml({ brand, id: u.id, name: u.name, status: st, limitBytes: u.limitBytes || 0, used, up, down, expireAt: u.expireAt || 0, lastOnline: u.lastOnline || 0, links }));
      }
      const lg = new LinkGenerator(config, stateManager.state, uHost(req));
      if (fmt === 'singbox' || (!fmt && /\b(SFA|SFI|SFM|SFT)\/|sing-box/i.test(ua) && !/hiddify/i.test(ua))) {
        res.type('application/json');
        return res.send(lg.buildSingBoxClientJson(tagged));
      }
      if (fmt === 'clash' || (!fmt && /clash|mihomo|stash/i.test(ua))) {
        res.type('text/yaml; charset=utf-8');
        return res.send(lg.buildClashMetaYaml(tagged));
      }
      const text = tagged.filter(n => !/^(ShadowTLS-VLESS|WireGuard)$/.test(n.type)).map(n => n.uri).join('\n');
      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      res.send(req.query.raw ? text : Buffer.from(text).toString('base64'));
    });

    app.use(`/${panelPath}/api`, router);
    const adminToolsHtml = Buffer.from('', 'base64').toString('utf8');
    app.get(`/${panelPath}/tools`, (req, res) => {
      res.setHeader('Cache-Control', 'no-store');
      res.type('html').send(adminToolsHtml);
    });
  }
};

function startWatchdog(engine, name) {
  const hist = [];
  const t = setInterval(() => {
    try {
      const p = engine && engine.process;
      const dead = !p || p.exitCode !== null || p.signalCode !== null;
      if (!dead) return;
      const now = Date.now();
      while (hist.length && now - hist[0] > 10 * 60 * 1000) hist.shift();
      if (hist.length >= 5) return;
      hist.push(now);
      Logger.warn(`${name} is not running — watchdog restarting it`);
      engine.start();
    } catch (e) { Logger.warn(`${name} watchdog error: ${e.message}`); }
  }, 15000);
  if (t.unref) t.unref();
}

function createHttpPanel(config, stateManager, engineStatusGetter, resolvedHostGetter) {
  const app = express();
  const panelPath = config.panelPath.replace(/^\//, '') || 'parham-confing';

  const authMiddleware = (req, res, next) => {
    if (!config.panelToken) return next();

    const authHeader = req.headers.authorization;
    const bearer = authHeader && authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : null;
    const queryToken = req.query.token;

    if (queryToken === config.panelToken || bearer === config.panelToken) {
      return next();
    }

    res.status(401).send('Unauthorized: Invalid or missing panelToken.');
  };

  Extras.routes(app, { config, stateManager, authMiddleware, panelPath });

  app.get('/parham-confing-assets/app.css', (req, res) => {
    res.setHeader('Content-Type', 'text/css; charset=utf-8');
    res.send(AssetManager.getAppCss());
  });

  app.get('/parham-confing-assets/app.js', (req, res) => {
    res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
    res.send(AssetManager.getAppJs());
  });

  app.get('/parham-confing-assets/tutorial.mp4', (req, res) => {
    const total = TUTORIAL_MP4.length;
    res.setHeader('Content-Type', 'video/mp4');
    res.setHeader('Accept-Ranges', 'bytes');
    res.setHeader('Cache-Control', 'public, max-age=86400');
    const m = /bytes=(\d*)-(\d*)/.exec(req.headers.range || '');
    if (!m) { res.setHeader('Content-Length', total); return res.end(TUTORIAL_MP4); }
    let start = m[1] ? parseInt(m[1], 10) : total - parseInt(m[2] || '0', 10);
    let end = m[1] && m[2] ? parseInt(m[2], 10) : total - 1;
    if (!(start >= 0) || start >= total || end >= total || end < start) { res.status(416).setHeader('Content-Range', 'bytes */' + total); return res.end(); }
    res.status(206);
    res.setHeader('Content-Range', `bytes ${start}-${end}/${total}`);
    res.setHeader('Content-Length', end - start + 1);
    res.end(TUTORIAL_MP4.subarray(start, end + 1));
  });

  app.get('/parham-confing-assets/logo-v3.jpg', (req, res) => {
    const imgBuffer = AssetManager.getLogoPng();
    if (imgBuffer) {
      res.setHeader('Content-Type', 'image/jpeg');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(imgBuffer);
    } else {
      res.status(404).send('Logo not found');
    }
  });

  app.get('/favicon.ico', (req, res) => {
    const imgBuffer = AssetManager.getLogoPng();
    if (imgBuffer) {
      res.setHeader('Content-Type', 'image/jpeg');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(imgBuffer);
    } else {
      res.status(404).end();
    }
  });

  app.get('/parham-confing-assets/panel-bg.png', (req, res) => {
    const imgBuffer = AssetManager.getPanelBgPng();
    if (imgBuffer) {
      res.setHeader('Content-Type', 'image/png');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(imgBuffer);
    } else {
      res.status(404).send('Panel background not found');
    }
  });

  app.get('/parham-confing-assets/cyber-bg.svg', (req, res) => {
    const svgBuffer = AssetManager.getCyberBgSvg();
    if (svgBuffer) {
      res.setHeader('Content-Type', 'image/svg+xml');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(svgBuffer);
    } else {
      res.status(404).send('Background not found');
    }
  });

  app.get('/parham-confing-assets/ninja-bg.png', (req, res) => {
    const imgBuffer = AssetManager.getNinjaBgPng();
    if (imgBuffer) {
      res.setHeader('Content-Type', 'image/jpeg');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(imgBuffer);
    } else {
      res.status(404).send('Ninja background not found');
    }
  });

  app.get('/parham-confing-assets/bg:id.jpg', (req, res) => {
    const id = req.params.id;
    const imgBuffer = AssetManager.getBackgroundImage(id);
    if (imgBuffer) {
      res.setHeader('Content-Type', 'image/jpeg');
      res.setHeader('Cache-Control', 'public, max-age=86400');
      res.send(imgBuffer);
    } else {
      res.status(404).send('Image not found');
    }
  });

  const getRequestHost = (req) => {
    if (config.forceHost) return config.forceHost;
    if (resolvedHostGetter) {
      const h = resolvedHostGetter();
      if (h && h !== '127.0.0.1') return h;
    }
    if (config.domain) return config.domain;
    if (req && req.headers && req.headers.host) {
      return req.headers.host.split(':')[0];
    }
    return '127.0.0.1';
  };

  app.get('/health', authMiddleware, (req, res) => {
    const engines = engineStatusGetter ? engineStatusGetter() : {};
    const host = getRequestHost(req);
    const linkGen = new LinkGenerator(config, stateManager.state, host);
    const allNodes = linkGen.getAllNodes({ compat: 'full', allowLocalHostLinks: true });

    res.json({
      ok: true,
      brand: config.brand,
      product: config.product,
      uptime: process.uptime(),
      publicPort: HostDetect.effective(config, host).linkPort,
      hostInfo: (() => { const e = HostDetect.effective(config, host); return { provider: e.label, source: e.source, edge: e.edge, tls: e.tls }; })(),
      host,
      forceHost: config.forceHost || '',
      engines,
      nodes: allNodes.map(node => ({
        name: node.name,
        type: node.type,
        compat: node.compat,
        uri: node.uri,
        wgConf: node.wgConf || null,
        singboxJson: node.singboxJson || null,
        note: node.note || null
      }))
    });
  });

  const renderPanel = (req, res) => {
    res.setHeader('Content-Type', 'text/html; charset=utf-8');
    const safeServerName = String(config.serverName || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    res.send(AssetManager.getIndexHtml().replaceAll('__SERVER_NAME__', safeServerName).replaceAll('__TELEGRAM_URL__', 'https://t.me/parham_ste01').replaceAll('__PANEL_PATH__', String(panelPath)));
  };

  app.get('/', authMiddleware, renderPanel);
  app.get(`/${panelPath}`, authMiddleware, renderPanel);

  app.get([`/${panelPath}/base64`, `/${panelPath}/raw`], authMiddleware, (req, res) => {
    const isBase64 = req.path.endsWith('/base64');
    const compatMode = req.query.compat || 'v2ray';
    const host = getRequestHost(req);

    const linkGen = new LinkGenerator(config, stateManager.state, host);
    const nodes = linkGen.getAllNodes({
      compat: compatMode,
      allowLocalHostLinks: config.allowLocalHostLinks
    });

    const links = nodes.map(n => n.uri);
    const text = links.join('\n');

    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="Parham Confing.txt"');
    res.setHeader('Profile-Update-Interval', '24');
    res.setHeader('Subscription-Userinfo', `upload=${Math.floor(Stats.totalUp)}; download=${Math.floor(Stats.totalDown)}; total=0; expire=0`);

    if (isBase64) {
      res.send(Buffer.from(text).toString('base64'));
    } else {
      res.send(text);
    }
  });

  app.get([`/${panelPath}/clash`, `/${panelPath}/clash.yaml`], authMiddleware, (req, res) => {
    const host = getRequestHost(req);
    const linkGen = new LinkGenerator(config, stateManager.state, host);
    const nodes = linkGen.getAllNodes({ compat: 'full', allowLocalHostLinks: true });
    const yaml = linkGen.buildClashMetaYaml(nodes);

    res.setHeader('Content-Type', 'text/yaml; charset=utf-8');
    res.setHeader('Content-Disposition', 'inline; filename="Parham ConfingGate.yaml"');
    res.setHeader('Profile-Update-Interval', '24');
    res.send(yaml);
  });

  app.get([`/${panelPath}/sb/raw`, `/${panelPath}/sb/base64`], authMiddleware, (req, res) => {
    const isBase64 = req.path.endsWith('/base64');
    const host = getRequestHost(req);
    const linkGen = new LinkGenerator(config, stateManager.state, host);
    const nodes = linkGen.getAllNodes({ compat: 'full', allowLocalHostLinks: true });
    const jsonStr = linkGen.buildSingBoxClientJson(nodes);

    res.setHeader('Content-Type', isBase64 ? 'text/plain; charset=utf-8' : 'application/json; charset=utf-8');
    if (isBase64) {
      res.send(Buffer.from(jsonStr).toString('base64'));
    } else {
      res.send(jsonStr);
    }
  });

  app.get([`/${panelPath}/xray/raw`, `/${panelPath}/xray/base64`], authMiddleware, (req, res) => {
    const isBase64 = req.path.endsWith('/base64');
    const jsonStr = stateManager.state.xrayJson || '{}';

    res.setHeader('Content-Type', isBase64 ? 'text/plain; charset=utf-8' : 'application/json; charset=utf-8');
    if (isBase64) {
      res.send(Buffer.from(jsonStr).toString('base64'));
    } else {
      res.send(jsonStr);
    }
  });

  app.get([`/${panelPath}/wg.conf`, `/${panelPath}/wireguard.conf`], authMiddleware, (req, res) => {
    const host = getRequestHost(req);
    const linkGen = new LinkGenerator(config, stateManager.state, host);
    const wgNode = linkGen.generateWireGuard();
    if (!wgNode || !wgNode.wgConf) {
      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      return res.status(404).send('# WireGuard is not enabled or keys are not available.');
    }
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="wg0.conf"');
    res.send(wgNode.wgConf);
  });

  const server = http.createServer(app);
  return { app, server };
}

const METERED_TYPES = /^(VLESS-WS|VLESS-HTTPUpgrade|Trojan-WS|VMess-WS)$/;

function vmessUri(o) {
  const j = { v: '2', ps: o.name, add: o.host, port: String(o.port), id: o.uuid, aid: '0', scy: 'auto', net: 'ws', type: 'none', host: o.host, path: o.path, tls: o.tls ? 'tls' : '', sni: o.tls ? o.host : '' };
  return 'vmess://' + Buffer.from(JSON.stringify(j)).toString('base64');
}

function subDescribe(uri) {
  const out = { proto: '', net: '', sec: '', name: '' };
  try {
    uri = String(uri || '');
    if (/^vmess:\/\//i.test(uri)) {
      const j = JSON.parse(Buffer.from(uri.slice(8), 'base64').toString('utf8'));
      out.proto = 'Vmess'; out.net = String(j.net || 'tcp').toUpperCase(); out.sec = j.tls === 'tls' ? 'TLS' : 'None'; out.name = j.ps || '';
      return out;
    }
    const m = /^([a-z0-9]+):\/\//i.exec(uri);
    const s = (m ? m[1] : '').toLowerCase();
    const names = { vless: 'Vless', trojan: 'Trojan', ss: 'Shadowsocks', hysteria2: 'Hysteria2', hy2: 'Hysteria2', tuic: 'TUIC', wireguard: 'WireGuard' };
    out.proto = names[s] || s;
    const qs = (uri.split('#')[0].split('?')[1]) || '';
    const q = new URLSearchParams(qs);
    const t = String(q.get('type') || '').toLowerCase();
    const nm = { ws: 'WS', httpupgrade: 'HTTPUpgrade', grpc: 'gRPC', xhttp: 'XHTTP', tcp: 'TCP' };
    const quic = s === 'hysteria2' || s === 'hy2' || s === 'tuic';
    out.net = nm[t] || (quic ? 'QUIC' : s === 'wireguard' ? 'UDP' : 'TCP');
    const sec = String(q.get('security') || '').toLowerCase();
    out.sec = sec === 'tls' ? 'TLS' : sec === 'reality' ? 'Reality' : quic ? 'TLS' : 'None';
    const h = uri.indexOf('#');
    out.name = h >= 0 ? decodeURIComponent(uri.slice(h + 1)) : '';
  } catch {}
  return out;
}

